window.__NLM_CHAPS = window.__NLM_CHAPS || {};
window.__NLM_CHAPS["vocab-ex-1-3"] = "<section class=\"chapter-section\" id=\"vocab-ex-1-3\">\n\n<div class=\"chapter-header\">\n\n  <h2>2. Latihan Soal Kosakata &amp; Kanji (\u7df4\u7fd2\u554f\u984c)</h2>\n\n  <p class=\"book-ref\">Bab 1 Bagian B: Soal Latihan \u554f\u984c1 s.d. \u554f\u984c3 (Hal. Buku 60-92 / PDF hal. 63-95)</p>\n\n  <div class=\"info-box\">\n\n    <p><strong>Format Soal (<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u306e<ruby>\u5f62<rt>\u3051\u3044</rt></ruby><ruby>\u5f0f<rt>\u3057\u304d</rt></ruby>):</strong> Seluruhnya terdapat <strong>5 jenis format soal</strong> pada bagian Kosakata (<em>Moji &amp; Goi</em>). <em>(Jumlah soal pada ujian sebenarnya dapat berubah sewaktu-waktu.)</em></p>\n\n    <ul class=\"format-list\">\n\n      <li><strong><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>1\u3000<ruby>\u6f22<rt>\u304b\u3093</rt></ruby><ruby>\u5b57<rt>\u3058</rt></ruby><ruby>\u8aad<rt>\u3088</rt></ruby>\u307f</strong>: Membaca Kanji (8 soal)</li>\n\n      <li><strong><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>2\u3000<ruby>\u8868<rt>\u3072\u3087\u3046</rt></ruby><ruby>\u8a18<rt>\u304d</rt></ruby></strong>: Penulisan Kanji (6 soal)</li>\n\n      <li><strong><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>3\u3000<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u8108<rt>\u307f\u3083\u304f</rt></ruby><ruby>\u898f<rt>\u304d</rt></ruby><ruby>\u5b9a<rt>\u3066\u3044</rt></ruby></strong>: Konteks Kalimat (11 soal)</li>\n\n      <li><strong><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>4\u3000<ruby>\u8a00<rt>\u3044</rt></ruby>\u3044<ruby>\u63db<rt>\u304b</rt></ruby>\u3048<ruby>\u985e<rt>\u308b\u3044</rt></ruby><ruby>\u7fa9<rt>\u304e</rt></ruby></strong>: Sinonim / Padanan Kata (5 soal)</li>\n\n      <li><strong><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>5\u3000<ruby>\u7528<rt>\u3088\u3046</rt></ruby><ruby>\u6cd5<rt>\u307b\u3046</rt></ruby></strong>: Penggunaan Kata (5 soal)</li>\n\n    </ul>\n\n  </div>\n\n</div>\n\n\n\n<div class=\"mondai-section\" id=\"mondai-1\">\n\n  <h3>\u554f\u984c1\u3000\u6f22\u5b57\u8aad\u307f: Cara Baca Kanji</h3>\n\n  <div class=\"example-box\">\n\n    <h4>\u3007 Contoh Soal \u554f\u984c1 (\u554f\u984c1 \u4f8b \u00b7 Hal. 61)</h4>\n\n    <div class=\"q-instruction\">\n\n      <div class=\"q-inst-jp\">\u554f\u984c1\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u306e\u8aad\u307f\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n\n      <div class=\"q-inst-id\">Pilihlah cara baca yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n\n    </div>\n\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u65e5\u672c\u3078<u>\u7559\u5b66</u>\u3059\u308b\u3053\u3068\u3092\u6c7a\u3081\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya memutuskan untuk belajar ke luar negeri (berkuliah di Jepang).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u308a\u3085\u304c\u304f</span>\n      <span class=\"opt\">2. \u308a\u3085\u3046\u304c\u304f</span>\n      <span class=\"opt\">3. \u308a\u3085\u304b\u304f</span>\n      <span class=\"opt\">4. \u308a\u3085\u3046\u304b\u304f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u6559\u5ba4\u306b\u4eba\u304c<u>\u96c6\u307e\u308b</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Orang-orang berkumpul di ruang kelas.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304b\u305f\u307e\u308b</span>\n      <span class=\"opt\">2. \u3068\u307e\u308b</span>\n      <span class=\"opt\">3. \u3042\u3064\u307e\u308b</span>\n      <span class=\"opt\">4. \u305f\u307e\u308b</span>\n    </div>\n  </div>\n\n    <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 3</div>\n\n  </div>\n\n\n\n  <div class=\"strategy-box\">\n\n    <h4>Strategi &amp; Tips \u554f\u984c1 (Cara Baca Kanji)</h4>\n\n    <p class=\"jp-quote\"><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>1\u3067\u306f\u3001<ruby>\u6f22<rt>\u304b\u3093</rt></ruby><ruby>\u5b57<rt>\u3058</rt></ruby>\u306e<ruby>\u8aad<rt>\u3088</rt></ruby>\u307f<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u3092<ruby>\u7b54<rt>\u3053\u305f</rt></ruby>\u3048\u308b<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u304c8<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\u306e<ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u306b\u306f\u3001<ruby>\u8ff7<rt>\u307e\u3088</rt></ruby>\u3046\u3082\u306e\u304c\u305f\u304f\u3055\u3093\u3042\u308b\u3068<ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3044\u307e\u3059\u3002<ruby>\u97f3<rt>\u304a\u3093</rt></ruby><ruby>\u8aad<rt>\u3088</rt></ruby>\u307f\u3084<ruby>\u8a13<rt>\u304f\u3093</rt></ruby><ruby>\u8aad<rt>\u3088</rt></ruby>\u307f\u3001<ruby>\u9577<rt>\u3061\u3087\u3046</rt></ruby><ruby>\u97f3<rt>\u304a\u3093</rt></ruby>\uff08\u30fc\uff09<ruby>\u4fc3<rt>\u305d\u304f</rt></ruby><ruby>\u97f3<rt>\u304a\u3093</rt></ruby>\uff08\u3063\uff09<ruby>\u6fc1<rt>\u3060\u304f</rt></ruby><ruby>\u97f3<rt>\u304a\u3093</rt></ruby>\uff08\u309b\uff09<ruby>\u534a<rt>\u306f\u3093</rt></ruby><ruby>\u6fc1<rt>\u3060\u304f</rt></ruby><ruby>\u97f3<rt>\u304a\u3093</rt></ruby>\uff08\u309c\uff09\u306a\u3069\u306b<ruby>\u6ce8<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3057\u306a\u304c\u3089\u3001<ruby>\u8aad<rt>\u3088</rt></ruby>\u307f<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u3092<ruby>\u78ba<rt>\u304b\u304f</rt></ruby><ruby>\u8a8d<rt>\u306b\u3093</rt></ruby>\u3057\u3066\u3044\u304d\u307e\u3057\u3087\u3046\u3002</p>\n\n    <p>Pada <strong>Mondai 1</strong>, akan keluar <strong>8 soal</strong> yang menanyakan cara baca kanji. Di antara pilihan jawabannya, pasti banyak pilihan yang mengecoh dan membuat ragu. Mari kita periksa cara bacanya dengan memperhatikan baik-baik <em>on'yomi</em> (bacaan Sino-Jepang) dan <em>kun'yomi</em> (bacaan asli Jepang), bunyi panjang / <em>ch\u014don</em> (\u30fc), konsonan rangkap / <em>sokuon</em> (\u3063), bunyi bersuara / <em>dakuon</em> (\u309b), serta bunyi letup-p / <em>handakuon</em> (\u309c).</p>\n\n  </div>\n\n\n\n  <div class=\"tip-box\">\n\n    <h4>\u3007 Contoh yang Sering Salah (\u9593\u9055\u3044\u3084\u3059\u3044\u4f8b)</h4>\n\n    <ul>\n\n      <li><strong>\u7559\u5b66</strong> (belajar di luar negeri / kuliah di luar negeri): <strong>\u308a\u3085\u3046\u304c\u304f (\u25cb)</strong>, bukan \u308a\u3085\u304c\u304f (\u00d7), <em>perhatikan bunyi panjang (ch\u014don)</em></li>\n\n      <li><strong>\u4e0a\u7d1a</strong> (tingkat mahir / lanjutan): <strong>\u3058\u3087\u3046\u304d\u3085\u3046 (\u25cb)</strong>, bukan \u3057\u3087\u3046\u304d\u3085\u3046 (\u00d7), <em>perhatikan dakuon (\u309b)</em></li>\n\n      <li><strong>\u5b9f\u5bb6</strong> (rumah orang tua / kampung halaman): <strong>\u3058\u3063\u304b (\u25cb)</strong>, bukan \u3058\u3064\u304b (\u00d7), <em>perhatikan sokuon (\u3063)</em></li>\n\n      <li><strong>\u9032\u6b69</strong> (kemajuan): <strong>\u3057\u3093\u307d (\u25cb)</strong>, bukan \u3057\u3093\u307b (\u00d7), <em>perhatikan handakuon (\u309c)</em></li>\n\n      <li><strong>\u6708\u65e5</strong> (waktu / hari demi hari yang berlalu): <strong>\u3064\u304d\u3072 (\u25cb)</strong>, bukan \u3052\u3064\u306b\u3061 (\u00d7), <em>perhatikan bacaan kun'yomi</em></li>\n\n    </ul>\n\n  </div>\n\n<div class=\"exercise-set\" id=\"mondai-1-p65\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c1: Set 1 (Kata Benda 1 Kanji \u00b7 Hal. 62)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c1\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u306e\u8aad\u307f\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah cara baca yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u79cb\u306b\u306a\u308a\u3001<u>\u8449</u>\u306e\u8272\u304c\u5909\u308f\u3063\u3066\u304d\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Musim gugur telah tiba, dan warna daun mulai berubah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3048\u3060</span>\n      <span class=\"opt\">2. \u304d</span>\n      <span class=\"opt\">3. \u306f</span>\n      <span class=\"opt\">4. \u306d</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u6628\u65e5\u306e\u591c\u3001<u>\u71b1</u>\u304c\u51fa\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Tadi malam saya demam.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3051\u3080\u308a</span>\n      <span class=\"opt\">2. \u306d\u3064</span>\n      <span class=\"opt\">3. \u3072</span>\n      <span class=\"opt\">4. \u3086</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\"><ruby>\u5ead<rt>\u306b\u308f</rt></ruby>\u306e\u6728\u306b\u8d64\u3044<u>\u5b9f</u>\u304c\u306a\u308a\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Buah merah telah tumbuh di pohon halaman rumah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305f\u306d</span>\n      <span class=\"opt\">2. \u306f\u306a</span>\n      <span class=\"opt\">3. \u3081</span>\n      <span class=\"opt\">4. \u307f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u68da<rt>\u3060\u306a</rt></ruby>\u306e<u>\u89d2</u>\u3067\u982d\u3092\u6253\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Kepala saya terbentur sudut rak buku.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u306f\u3057</span>\n      <span class=\"opt\">2. \u3088\u3053</span>\n      <span class=\"opt\">3. \u304b\u3069</span>\n      <span class=\"opt\">4. \u3055\u304d</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u672c\u306e<u>\u8868</u>\u306b\u540d\u524d\u3092\u66f8\u304f\u3002</span></div>\n    <div class=\"q-id-trans\">Menulis nama di bagian depan (sampul) buku.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304a\u3082\u3066</span>\n      <span class=\"opt\">2. \u3046\u3089</span>\n      <span class=\"opt\">3. \u3057\u305f</span>\n      <span class=\"opt\">4. \u3046\u3048</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u5bd2\u3059\u304e\u3066\u3001<u>\u6307</u>\u304c\u51b7\u305f\u304f\u306a\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena terlalu dingin, jari-jari saya menjadi dingin.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3066</span>\n      <span class=\"opt\">2. \u3042\u3057</span>\n      <span class=\"opt\">3. \u3086\u3073</span>\n      <span class=\"opt\">4. \u3046\u3067</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u6bcd\u304b\u3089\u304d\u308c\u3044\u306a<u>\u5668</u>\u3092\u3082\u3089\u3044\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya mendapat wadah (mangkuk/piring) yang cantik dari ibu.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u306a\u3079</span>\n      <span class=\"opt\">2. \u3055\u3089</span>\n      <span class=\"opt\">3. \u3046\u3064\u308f</span>\n      <span class=\"opt\">4. \u3044\u305f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u5375\u3068<u>\u7c89</u>\u3092\u5bb9\u5668\u306b\u5165\u308c\u3066\u3001\u3088\u304f\u304b\u304d\u307e\u305c\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Masukkan telur dan tepung ke dalam wadah, lalu aduk rata.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3059</span>\n      <span class=\"opt\">2. \u3042\u3076\u3089</span>\n      <span class=\"opt\">3. \u3057\u304a</span>\n      <span class=\"opt\">4. \u3053\u306a</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\"><ruby>\u6f14<rt>\u3048\u3093</rt></ruby><ruby>\u594f<rt>\u305d\u3046</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u306e<u>\u5e2d</u>\u3092\u53d6\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Memesan kursi untuk konser musik.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305b\u304d</span>\n      <span class=\"opt\">2. \u3086\u304b</span>\n      <span class=\"opt\">3. \u3044\u3059</span>\n      <span class=\"opt\">4. \u3070</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\"><ruby>\u8377<rt>\u306b</rt></ruby><ruby>\u7269<rt>\u3082\u3064</rt></ruby>\u3092<u>\u7bb1</u>\u306b\u5165\u308c\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Memasukkan barang bawaan ke dalam kotak.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304b\u3054</span>\n      <span class=\"opt\">2. \u306f\u3053</span>\n      <span class=\"opt\">3. \u305f\u3093\u3059</span>\n      <span class=\"opt\">4. \u304b\u3070\u3093</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\u3000\u2461 2\u3000\u2462 4\u3000\u2463 3\u3000\u2464 1\u3000\u2465 3\u3000\u2466 3\u3000\u2467 4\u3000\u2468 1\u3000\u2469 2</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-1-p66\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c1: Set 2 (Kata Benda 1-2 Kanji \u00b7 Hal. 63)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c1\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u306e\u8aad\u307f\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah cara baca yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u5c0f\u3055\u3044<ruby>\u866b<rt>\u3080\u3057</rt></ruby>\u304c<u>\u5217</u>\u306b\u306a\u3063\u3066\u6b69\u3044\u3066\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Serangga kecil berjalan berbaris membentuk barisan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u308c\u3064</span>\n      <span class=\"opt\">2. \u305f\u3066</span>\n      <span class=\"opt\">3. \u306a\u306a\u3081</span>\n      <span class=\"opt\">4. \u305b\u3093</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\"><u>\u7f36</u>\u3092\u3054\u307f\u7bb1\u306b\u6368\u3066\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Membuang kaleng ke tempat sampah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3075\u304f\u308d</span>\n      <span class=\"opt\">2. \u304b\u307f</span>\n      <span class=\"opt\">3. \u3075\u304f</span>\n      <span class=\"opt\">4. \u304b\u3093</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u308f\u305f\u3057\u306e<u>\u673a</u>\u306b\u7f6e\u3044\u3066\u304a\u3044\u3066\u304f\u3060\u3055\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Tolong letakkan di atas meja saya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3060\u3044</span>\n      <span class=\"opt\">2. \u3044\u3059</span>\n      <span class=\"opt\">3. \u3064\u304f\u3048</span>\n      <span class=\"opt\">4. \u3078\u3084</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u51ac\u306f\u5bd2\u304f\u3066\u3001\u5916\u306b\u51fa\u308b\u3068<u>\u9f3b</u>\u304c\u8d64\u304f\u306a\u3063\u3066\u3057\u307e\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Di musim dingin udaranya dingin, sehingga kalau keluar rumah hidung menjadi merah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u307f\u307f</span>\n      <span class=\"opt\">2. \u307b\u307b</span>\n      <span class=\"opt\">3. \u306f\u306a</span>\n      <span class=\"opt\">4. \u304b\u304a</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u7528\u7d19\u306b\u304d\u308c\u3044\u306a<u>\u7dda</u>\u3092\u66f8\u304f\u3002</span></div>\n    <div class=\"q-id-trans\">Menggambar garis yang rapi di atas kertas.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u307e\u308b</span>\n      <span class=\"opt\">2. \u305b\u3093</span>\n      <span class=\"opt\">3. \u3048</span>\n      <span class=\"opt\">4. \u3058</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u308f\u305f\u3057\u306f\u7d75\u3084\u97f3\u697d\u306a\u3069\u306e<u>\u82b8\u8853</u>\u304c\u597d\u304d\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Saya menyukai seni seperti lukisan dan musik.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3052\u3058\u3085\u3064</span>\n      <span class=\"opt\">2. \u3052\u3057\u3085\u3064</span>\n      <span class=\"opt\">3. \u3052\u3044\u3058\u3085\u3064</span>\n      <span class=\"opt\">4. \u3052\u3044\u3057\u3085\u3064</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u308f\u305f\u3057\u3068<ruby>\u91ce<rt>\u306e</rt></ruby><ruby>\u7530<rt>\u3060</rt></ruby>\u3055\u3093\u306e\u9593\u306b\u306f\u71b1\u3044<u>\u53cb\u60c5</u>\u304c\u3042\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Di antara saya dan Noda-san terdapat persahabatan yang erat.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3086\u3046\u3058\u3087</span>\n      <span class=\"opt\">2. \u3086\u3046\u3058\u3087\u3046</span>\n      <span class=\"opt\">3. \u3086\u3058\u3087</span>\n      <span class=\"opt\">4. \u3086\u3058\u3087\u3046</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u81ea\u8ee2\u8eca\u306e\u4fee\u7406\u3092\u3059\u308b\u306b\u306f\u3001<ruby>\u69d8<rt>\u3055\u307e</rt></ruby><ruby>\u3005<rt>\u3056\u307e</rt></ruby>\u306a<u>\u9053\u5177</u>\u304c\u5fc5\u8981\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Untuk memperbaiki sepeda, diperlukan berbagai macam alat.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3069\u3050\u3046</span>\n      <span class=\"opt\">2. \u3069\u3050</span>\n      <span class=\"opt\">3. \u3069\u3046\u3050\u3046</span>\n      <span class=\"opt\">4. \u3069\u3046\u3050</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u6b63\u3057\u3044<u>\u65b9\u89d2</u>\u3092\u8abf\u3079\u3066\u304b\u3089\u884c\u3053\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Mari kita periksa arah yang benar terlebih dahulu sebelum pergi.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u307b\u3046\u304c\u304f</span>\n      <span class=\"opt\">2. \u307b\u304c\u304f</span>\n      <span class=\"opt\">3. \u307b\u3046\u304b\u304f</span>\n      <span class=\"opt\">4. \u307b\u304b\u304f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\"><ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u306e\u5bb6\u306b\u306f<u>\u697d\u5668</u>\u304c\u305f\u304f\u3055\u3093\u3042\u308a\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Di rumah nenek ada banyak sekali alat musik.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304c\u3064\u304d</span>\n      <span class=\"opt\">2. \u304c\u3063\u304e</span>\n      <span class=\"opt\">3. \u304c\u3063\u304d</span>\n      <span class=\"opt\">4. \u304c\u3064\u304e</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 1\u3000\u2461 4\u3000\u2462 3\u3000\u2463 3\u3000\u2464 2\u3000\u2465 3\u3000\u2466 2\u3000\u2467 4\u3000\u2468 1\u3000\u2469 3</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-1-p67\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c1: Set 3 (Kata Benda 2 Kanji \u00b7 Hal. 64)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c1\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u306e\u8aad\u307f\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah cara baca yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u3055\u3063\u304d\u96fb\u8a71\u306710\u4eba\u5206\u306e<u>\u6ce8\u6587</u>\u3092\u53d7\u3051\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Tadi saya menerima pesanan untuk 10 orang melalui telepon.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3061\u3085\u3046\u3076\u3093</span>\n      <span class=\"opt\">2. \u3061\u3085\u3076\u3093</span>\n      <span class=\"opt\">3. \u3061\u3085\u3046\u3082\u3093</span>\n      <span class=\"opt\">4. \u3061\u3085\u3082\u3093</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\"><ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby>\u306e<ruby>\u7bb8<rt>\u306f\u3057</rt></ruby>\u3092\u4f5c\u3063\u3066\u3044\u308b\u4eba\u306f\u3001\u9ad8\u3044<u>\u6280\u8853</u>\u3092\u6301\u3063\u3066\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Pengrajin yang membuat sumpit Jepang memiliki teknik (keahlian) yang tinggi.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304d\u3058\u3085\u3064</span>\n      <span class=\"opt\">2. \u304e\u3058\u3085\u3064</span>\n      <span class=\"opt\">3. \u304d\u3057\u3085\u3064</span>\n      <span class=\"opt\">4. \u304e\u3057\u3085\u3064</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u9ad8\u6821\u6642\u4ee3\u306f<u>\u91ce\u7403</u>\u3092\u3057\u3066\u3044\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saat SMA saya bermain bisbol.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3084\u304f\u3046</span>\n      <span class=\"opt\">2. \u3084\u304f</span>\n      <span class=\"opt\">3. \u3084\u304d\u3085\u3046</span>\n      <span class=\"opt\">4. \u3084\u304d\u3085</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><u>\u8f9e\u66f8</u>\u3092\u4f7f\u3063\u3066\u8abf\u3079\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Mencari arti kata menggunakan kamus.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3058\u3057\u3087</span>\n      <span class=\"opt\">2. \u3058\u3057\u3087\u3046</span>\n      <span class=\"opt\">3. \u3057\u3057\u3087</span>\n      <span class=\"opt\">4. \u3057\u3057\u3087\u3046</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u533b\u8005\u304b\u3089<ruby>\u75c5<rt>\u3073\u3087\u3046</rt></ruby><ruby>\u6c17<rt>\u304d</rt></ruby>\u306b\u3064\u3044\u3066\u306e<u>\u8aac\u660e</u>\u3092\u53d7\u3051\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Menerima penjelasan mengenai penyakit dari dokter.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305b\u3064\u3081</span>\n      <span class=\"opt\">2. \u305b\u3063\u3081</span>\n      <span class=\"opt\">3. \u305b\u3063\u3081\u3044</span>\n      <span class=\"opt\">4. \u305b\u3064\u3081\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u5927\u5b66\u306e\u5408\u683c<u>\u767a\u8868</u>\u304c\u884c\u308f\u308c\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Pengumuman kelulusan universitas telah dilaksanakan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u306f\u3063\u3074\u3087</span>\n      <span class=\"opt\">2. \u306f\u3074\u3087</span>\n      <span class=\"opt\">3. \u306f\u3063\u3074\u3087\u3046</span>\n      <span class=\"opt\">4. \u306f\u3074\u3087\u3046</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\"><ruby>\u67d4<rt>\u3058\u3085\u3046</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u306e<u>\u521d\u7d1a</u>\u306e\u8a66\u9a13\u306b\u5408\u683c\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya lulus ujian judo tingkat pemula (dasar).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3057\u3087\u3046\u304d\u3085\u3046</span>\n      <span class=\"opt\">2. \u3057\u3087\u304d\u3085\u3046</span>\n      <span class=\"opt\">3. \u3057\u3087\u3046\u304d\u3085</span>\n      <span class=\"opt\">4. \u3057\u3087\u304d\u3085</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u5929\u6c17\u304c\u3044\u3044\u306e\u3067<u>\u5e03\u56e3</u>\u3092\u5e72\u3057\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Karena cuacanya cerah, mari kita jemur futon (kasur lipat Jepang).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3076\u3068\u3093</span>\n      <span class=\"opt\">2. \u3075\u3068\u3093</span>\n      <span class=\"opt\">3. \u3076\u3060\u3093</span>\n      <span class=\"opt\">4. \u3075\u3060\u3093</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\"><u>\u901a\u8def</u>\u304c<ruby>\u72ed<rt>\u305b\u307e</rt></ruby>\u304f\u3066\u901a\u308c\u307e\u305b\u3093\u3002</span></div>\n    <div class=\"q-id-trans\">Lorongnya sempit sehingga tidak bisa dilewati.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3064\u3046\u308d</span>\n      <span class=\"opt\">2. \u3064\u3046\u308d\u3046</span>\n      <span class=\"opt\">3. \u3064\u308d\u3046</span>\n      <span class=\"opt\">4. \u3064\u308d</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\">\u9032\u5b66\u306e\u3053\u3068\u306b\u3064\u3044\u3066\u3001\u5148\u751f\u306b<u>\u76f8\u8ac7</u>\u304c\u3042\u308a\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Ada hal yang ingin saya konsultasikan dengan guru mengenai kelanjutan pendidikan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305d\u3046\u305f\u3093</span>\n      <span class=\"opt\">2. \u3057\u3087\u3046\u305f\u3093</span>\n      <span class=\"opt\">3. \u305d\u3046\u3060\u3093</span>\n      <span class=\"opt\">4. \u3057\u3087\u3046\u3060\u3093</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\u3000\u2461 2\u3000\u2462 3\u3000\u2463 1\u3000\u2464 4\u3000\u2465 3\u3000\u2466 2\u3000\u2467 2\u3000\u2468 1\u3000\u2469 3</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-1-p68\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c1: Set 4 (Kata Benda 2 Kanji Lanjutan \u00b7 Hal. 65)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c1\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u306e\u8aad\u307f\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah cara baca yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u6765\u5e74\u306f<ruby>\u5927<rt>\u304a\u304a</rt></ruby><ruby>\u962a<rt>\u3055\u304b</rt></ruby>\u306e\u652f\u5e97\u3067\u50cd\u304f\u3053\u3068\u3092<u>\u5e0c\u671b</u>\u3057\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Tahun depan saya berharap dapat bekerja di kantor cabang Osaka.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304d\u307c\u3046</span>\n      <span class=\"opt\">2. \u304d\u307c</span>\n      <span class=\"opt\">3. \u304d\u3044\u307c</span>\n      <span class=\"opt\">4. \u304d\u3044\u307c\u3046</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u5f1f\u306f\u6765\u5e74\u306e3\u6708\u306b\u5927\u5b66\u3092<u>\u5352\u696d</u>\u3059\u308b\u4e88\u5b9a\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Adik laki-laki saya berencana lulus dari universitas pada bulan Maret tahun depan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305d\u3064\u304e\u3087</span>\n      <span class=\"opt\">2. \u305d\u3063\u304e\u3087</span>\n      <span class=\"opt\">3. \u305d\u3063\u304e\u3087\u3046</span>\n      <span class=\"opt\">4. \u305d\u3064\u304e\u3087\u3046</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u305a\u3063\u3068\u98df\u3079\u305f\u304b\u3063\u305f\u30ab\u30ec\u30fc\u3092\u98df\u3079\u3089\u308c\u3066<u>\u6e80\u8db3</u>\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya merasa puas karena bisa makan kare yang sudah lama ingin saya makan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u307e\u3093\u305d\u304f</span>\n      <span class=\"opt\">2. \u307e\u3093\u305e\u304f</span>\n      <span class=\"opt\">3. \u307e\u3093\u305d\u3050</span>\n      <span class=\"opt\">4. \u307e\u3093\u305e\u3050</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u308f\u305f\u3057\u306f\u30d7\u30ed\u306e\u6b4c\u624b\u3068\u3057\u3066\u300110\u5e74\u9593<u>\u6d3b\u52d5</u>\u3057\u3066\u3044\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Saya telah beraktivitas sebagai penyanyi profesional selama 10 tahun.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304b\u3063\u3069\u3046</span>\n      <span class=\"opt\">2. \u304b\u3063\u3069</span>\n      <span class=\"opt\">3. \u304b\u3064\u3069\u3046</span>\n      <span class=\"opt\">4. \u304b\u3064\u3069</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u751f\u5f92\u3092<u>\u4ee3\u8868</u>\u3057\u3066\u3042\u3044\u3055\u3064\u3092\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Memberikan sambutan mewakili para siswa.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305f\u3044\u3072\u3087\u3046</span>\n      <span class=\"opt\">2. \u3060\u3044\u3072\u3087\u3046</span>\n      <span class=\"opt\">3. \u305f\u3044\u3072\u3087</span>\n      <span class=\"opt\">4. \u3060\u3044\u3072\u3087</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u5148\u751f\u306f\u308f\u305f\u3057\u306e\u8003\u3048\u3092<u>\u5426\u5b9a</u>\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Guru menolak (menyangkal) pendapat saya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3072\u3066\u3044</span>\n      <span class=\"opt\">2. \u3072\u3066</span>\n      <span class=\"opt\">3. \u3075\u3066\u3044</span>\n      <span class=\"opt\">4. \u3075\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u30ac\u30bd\u30ea\u30f3\u3092\u305f\u304f\u3055\u3093<u>\u6d88\u8cbb</u>\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Banyak mengonsumsi bensin.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305d\u3072</span>\n      <span class=\"opt\">2. \u305d\u3046\u3072</span>\n      <span class=\"opt\">3. \u3057\u3087\u3072</span>\n      <span class=\"opt\">4. \u3057\u3087\u3046\u3072</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\"><u>\u60f3\u5b9a</u>\u3057\u3066\u3044\u306a\u304b\u3063\u305f\u554f\u984c\u304c\u8d77\u304d\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Terjadi masalah yang tidak diperkirakan (diantisipasi) sebelumnya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305d\u3046\u3066\u3044</span>\n      <span class=\"opt\">2. \u3057\u3087\u3046\u3066\u3044</span>\n      <span class=\"opt\">3. \u305d\u3046\u3066</span>\n      <span class=\"opt\">4. \u3057\u3087\u3046\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u6b6f\u533b\u8005\u306e<u>\u4e88\u7d04</u>\u3092\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Membuat janji temu (reservasi) dengan dokter gigi.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305e\u3046\u3084\u304f</span>\n      <span class=\"opt\">2. \u305e\u3084\u304f</span>\n      <span class=\"opt\">3. \u3088\u3084\u304f</span>\n      <span class=\"opt\">4. \u3088\u3046\u3084\u304f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\">\u5b66\u6821\u306b<ruby>\u643a<rt>\u3051\u3044</rt></ruby><ruby>\u5e2f<rt>\u305f\u3044</rt></ruby><ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u3092\u6301\u3063\u3066\u304f\u308b\u3053\u3068\u3092<u>\u7981\u6b62</u>\u3057\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Dilarang membawa telepon genggam ke sekolah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304d\u3093\u3058</span>\n      <span class=\"opt\">2. \u304e\u3093\u3058</span>\n      <span class=\"opt\">3. \u304e\u3093\u3057</span>\n      <span class=\"opt\">4. \u304d\u3093\u3057</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 1\u3000\u2461 4\u3000\u2462 2\u3000\u2463 3\u3000\u2464 2\u3000\u2465 1\u3000\u2466 4\u3000\u2467 1\u3000\u2468 3\u3000\u2469 4</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-1-p69\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c1: Set 5 (Kata Benda &amp; Kata Kerja \u00b7 Hal. 66)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c1\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u306e\u8aad\u307f\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah cara baca yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u4eca\u56de\u306e<ruby>\u4e8b<rt>\u3058</rt></ruby><ruby>\u4ef6<rt>\u3051\u3093</rt></ruby>\u306f\u3001\u524d\u56de\u306e<ruby>\u4e8b<rt>\u3058</rt></ruby><ruby>\u4ef6<rt>\u3051\u3093</rt></ruby>\u3068<u>\u95a2\u4fc2</u>\u3057\u3066\u3044\u308b\u3088\u3046\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Tampaknya kasus kali ini berhubungan dengan kasus sebelumnya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304b\u3093\u3051</span>\n      <span class=\"opt\">2. \u304b\u3093\u3052</span>\n      <span class=\"opt\">3. \u304b\u3051\u3044</span>\n      <span class=\"opt\">4. \u304b\u3093\u3051\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u4eca\u5e74\u306f\u8d64\u306e\u30c1\u30fc\u30e0\u304c<u>\u512a\u52dd</u>\u3057\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Tahun ini tim merah yang meraih juara pertama (menang).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3086\u3057\u3087\u3046</span>\n      <span class=\"opt\">2. \u3086\u3046\u3057\u3087\u3046</span>\n      <span class=\"opt\">3. \u3086\u3046\u3057\u3087</span>\n      <span class=\"opt\">4. \u3086\u3057\u3087</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u6628\u65e5\u3001\u8db3\u3092<u>\u624b\u8853</u>\u3057\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Kemarin kaki saya menjalani operasi.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3057\u3085\u3046\u3057\u3085\u3064</span>\n      <span class=\"opt\">2. \u3057\u3085\u3046\u3058\u3085\u3064</span>\n      <span class=\"opt\">3. \u3057\u3085\u3057\u3085\u3064</span>\n      <span class=\"opt\">4. \u3057\u3085\u3058\u3085\u3064</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u5927\u4e8b\u306a\u65e5\u306a\u306e\u306b\u3001<u>\u5931\u6557</u>\u3057\u3066\u3057\u307e\u3044\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Padahal hari yang penting, saya malah mengalami kegagalan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3057\u3063\u306f\u3044</span>\n      <span class=\"opt\">2. \u3057\u3071\u3044</span>\n      <span class=\"opt\">3. \u3057\u3063\u3071\u3044</span>\n      <span class=\"opt\">4. \u3057\u306f\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u308f\u305f\u3057\u306f\u4ed5\u4e8b\u3067\u30d0\u30b9\u3092<u>\u904b\u8ee2</u>\u3057\u3066\u3044\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Dalam pekerjaan, saya mengemudikan bus.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3046\u3066\u3093</span>\n      <span class=\"opt\">2. \u3046\u3093\u3066\u3093</span>\n      <span class=\"opt\">3. \u3046\u3093\u3066</span>\n      <span class=\"opt\">4. \u3046\u3063\u3066\u3093</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u673a\u3092<u>\u5f15\u3044\u3066</u>\u304f\u3060\u3055\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Tolong tarik mejanya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3075\u3044\u3066</span>\n      <span class=\"opt\">2. \u305f\u305f\u3044\u3066</span>\n      <span class=\"opt\">3. \u3072\u3044\u3066</span>\n      <span class=\"opt\">4. \u304a\u3044\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u3053\u308c\u306f<ruby>\u99d0<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u8eca<rt>\u3057\u3083</rt></ruby><ruby>\u5834<rt>\u3058\u3087\u3046</rt></ruby>\u3092<u>\u8868\u3059</u>\u30de\u30fc\u30af\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Ini adalah tanda yang menunjukkan tempat parkir.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3057\u3081\u3059</span>\n      <span class=\"opt\">2. \u3055\u3059</span>\n      <span class=\"opt\">3. \u304b\u3059</span>\n      <span class=\"opt\">4. \u3042\u3089\u308f\u3059</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u5927\u304d\u306a\u6bb5\u30dc\u30fc\u30eb\u7bb1\u3092<u>\u5c4a\u3051\u308b</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Mengantarkan kotak kardus yang besar.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3068\u3069\u3051\u308b</span>\n      <span class=\"opt\">2. \u3076\u3064\u3051\u308b</span>\n      <span class=\"opt\">3. \u3042\u305a\u3051\u308b</span>\n      <span class=\"opt\">4. \u308f\u3051\u308b</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u59b9\u306e\u8d64\u3044\u6d0b\u670d\u3092<u>\u63a2\u3059</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Mencari pakaian berwarna merah milik adik perempuan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u306a\u304a\u3059</span>\n      <span class=\"opt\">2. \u306e\u3053\u3059</span>\n      <span class=\"opt\">3. \u307b\u3059</span>\n      <span class=\"opt\">4. \u3055\u304c\u3059</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\">\u5f7c\u5973\u306f\u6628\u65e5\u304b\u3089<u>\u6012\u3063\u3066</u>\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Dia (perempuan) marah sejak kemarin.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3053\u307e\u3063\u3066</span>\n      <span class=\"opt\">2. \u304a\u3053\u3063\u3066</span>\n      <span class=\"opt\">3. \u3060\u307e\u3063\u3066</span>\n      <span class=\"opt\">4. \u307e\u3088\u3063\u3066</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 4\u3000\u2461 2\u3000\u2462 4\u3000\u2463 3\u3000\u2464 2\u3000\u2465 3\u3000\u2466 4\u3000\u2467 1\u3000\u2468 4\u3000\u2469 2</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-1-p70\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c1: Set 6 (Kata Kerja \u00b7 Hal. 67)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c1\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u306e\u8aad\u307f\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah cara baca yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u7dd1\u306e\u7cf8\u3068\u767d\u3044\u7cf8\u3092<u>\u7de8\u3093\u3067</u>\u3044\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Sedang merajut benang hijau dan benang putih.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3048\u3089\u3093\u3067</span>\n      <span class=\"opt\">2. \u3080\u3059\u3093\u3067</span>\n      <span class=\"opt\">3. \u3042\u3093\u3067</span>\n      <span class=\"opt\">4. \u305f\u306e\u3093\u3067</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u5f37\u3044\u98a8\u3067\u6728\u304c<u>\u6298\u308c\u305f</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Pohon patah karena angin kencang.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305f\u304a\u308c\u305f</span>\n      <span class=\"opt\">2. \u304a\u308c\u305f</span>\n      <span class=\"opt\">3. \u3086\u308c\u305f</span>\n      <span class=\"opt\">4. \u304b\u308c\u305f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u5f1f\u304c\u59b9\u306e<ruby>\u5e03\u56e3<rt>\u3075\u3068\u3093</rt></ruby>\u3092<u>\u5e72\u3057\u305f</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Adik laki-laki menjemur futon milik adik perempuan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304b\u304f\u3057\u305f</span>\n      <span class=\"opt\">2. \u3088\u3054\u3057\u305f</span>\n      <span class=\"opt\">3. \u307b\u3057\u305f</span>\n      <span class=\"opt\">4. \u304b\u3048\u3057\u305f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><ruby>\u4e2d<rt>\u306a\u304b</rt></ruby><ruby>\u5cf6<rt>\u3058\u307e</rt></ruby>\u3055\u3093\u304c<u>\u9154\u3063\u3066</u>\u3057\u307e\u3044\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Nakajima-san telah mabuk.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3088\u3063\u3066</span>\n      <span class=\"opt\">2. \u3059\u3079\u3063\u3066</span>\n      <span class=\"opt\">3. \u3057\u3083\u3079\u3063\u3066</span>\n      <span class=\"opt\">4. \u3042\u307e\u3063\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\"><ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u306b\u501f\u308a\u3066\u3044\u305f\u670d\u3092<u>\u6e21\u3059</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Menyerahkan pakaian yang dipinjam dari teman.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304b\u3048\u3059</span>\n      <span class=\"opt\">2. \u307b\u3059</span>\n      <span class=\"opt\">3. \u308f\u305f\u3059</span>\n      <span class=\"opt\">4. \u3088\u3054\u3059</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\"><ruby>\u96a3<rt>\u3068\u306a\u308a</rt></ruby>\u306e\u5e2d\u306b<u>\u79fb\u308a</u>\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Mari kita pindah ke kursi sebelah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3059\u308f\u308a</span>\n      <span class=\"opt\">2. \u3046\u3064\u308a</span>\n      <span class=\"opt\">3. \u304f\u3070\u308a</span>\n      <span class=\"opt\">4. \u3082\u3069\u308a</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u30c6\u30b9\u30c8\u306e\u5185\u5bb9\u3092<u>\u5909\u3048\u308b</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Mengubah isi (materi) tes.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304a\u307c\u3048\u308b</span>\n      <span class=\"opt\">2. \u304f\u308f\u3048\u308b</span>\n      <span class=\"opt\">3. \u3064\u305f\u3048\u308b</span>\n      <span class=\"opt\">4. \u304b\u3048\u308b</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u9ed2\u3044<ruby>\u5b50<rt>\u3053</rt></ruby><ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3092<u>\u62fe\u3063\u305f</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Saya memungut (menemukan) anak kucing berwarna hitam.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3055\u308f\u3063\u305f</span>\n      <span class=\"opt\">2. \u3072\u308d\u3063\u305f</span>\n      <span class=\"opt\">3. \u307e\u3082\u3063\u305f</span>\n      <span class=\"opt\">4. \u304b\u3063\u305f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\"><ruby>\u643a<rt>\u3051\u3044</rt></ruby><ruby>\u5e2f<rt>\u305f\u3044</rt></ruby><ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u3092<u>\u76f4\u3059</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Memperbaiki telepon genggam.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304a\u3068\u3059</span>\n      <span class=\"opt\">2. \u308f\u305f\u3059</span>\n      <span class=\"opt\">3. \u304b\u3059</span>\n      <span class=\"opt\">4. \u306a\u304a\u3059</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\"><ruby>\u677e<rt>\u307e\u3064</rt></ruby><ruby>\u4e95<rt>\u3044</rt></ruby>\u3055\u3093\u3001\u3053\u3063\u3061\u3092<u>\u5411\u3044\u3066</u>\u304f\u3060\u3055\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Matsui-san, tolong menghadap ke sini.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3080\u3044\u3066</span>\n      <span class=\"opt\">2. \u3084\u3044\u3066</span>\n      <span class=\"opt\">3. \u307f\u304c\u3044\u3066</span>\n      <span class=\"opt\">4. \u306f\u3044\u3066</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\u3000\u2461 2\u3000\u2462 3\u3000\u2463 1\u3000\u2464 3\u3000\u2465 2\u3000\u2466 4\u3000\u2467 2\u3000\u2468 4\u3000\u2469 1</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-1-p71\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c1: Set 7 (Kata Sifat-i \u00b7 Hal. 68)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c1\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u306e\u8aad\u307f\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah cara baca yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u6c34\u66dc\u65e5\u306f<u>\u9762\u767d\u3044</u>\u30c6\u30ec\u30d3\u756a\u7d44\u304c\u3042\u308a\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Pada hari Rabu ada acara televisi yang menarik.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304a\u3082\u3044</span>\n      <span class=\"opt\">2. \u304a\u305d\u308d\u3057\u3044</span>\n      <span class=\"opt\">3. \u304a\u304b\u3057\u3044</span>\n      <span class=\"opt\">4. \u304a\u3082\u3057\u308d\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\"><ruby>\u65b0<rt>\u3057\u3093</rt></ruby><ruby>\u5e79<rt>\u304b\u3093</rt></ruby><ruby>\u7dda<rt>\u305b\u3093</rt></ruby>\u306f\u3068\u3066\u3082<u>\u901f\u3044</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Shinkansen sangat cepat.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305f\u304b\u3044</span>\n      <span class=\"opt\">2. \u3084\u3059\u3044</span>\n      <span class=\"opt\">3. \u3042\u3076\u306a\u3044</span>\n      <span class=\"opt\">4. \u306f\u3084\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u5f7c\u3068\u306f<u>\u89aa\u3057\u3044</u><ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Dia (laki-laki) adalah teman dekat (akrab) saya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3042\u3084\u3057\u3044</span>\n      <span class=\"opt\">2. \u3057\u305f\u3057\u3044</span>\n      <span class=\"opt\">3. \u3080\u305a\u304b\u3057\u3044</span>\n      <span class=\"opt\">4. \u306a\u3064\u304b\u3057\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><u>\u5bd2\u3044</u><ruby>\u5b63<rt>\u304d</rt></ruby><ruby>\u7bc0<rt>\u305b\u3064</rt></ruby>\u306b\u306a\u308a\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Sudah tiba musim yang dingin.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3059\u305a\u3057\u3044</span>\n      <span class=\"opt\">2. \u3055\u3080\u3044</span>\n      <span class=\"opt\">3. \u3042\u3064\u3044</span>\n      <span class=\"opt\">4. \u3042\u305f\u305f\u304b\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u5927\u4f1a\u306b\u51fa\u308b\u3053\u3068\u306f\u3068\u3066\u3082<u>\u96e3\u3057\u3044</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Tampil di turnamen (kejuaraan) adalah hal yang sangat sulit.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305f\u306e\u3057\u3044</span>\n      <span class=\"opt\">2. \u304d\u3073\u3057\u3044</span>\n      <span class=\"opt\">3. \u3080\u305a\u304b\u3057\u3044</span>\n      <span class=\"opt\">4. \u306f\u305a\u304b\u3057\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u308f\u305f\u3057\u306e\u5144\u306f\u3068\u3066\u3082<u>\u512a\u3057\u3044</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Kakak laki-laki saya sangat baik hati (lemah lembut).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3084\u3055\u3057\u3044</span>\n      <span class=\"opt\">2. \u304b\u308f\u3044\u3089\u3057\u3044</span>\n      <span class=\"opt\">3. \u3044\u305d\u304c\u3057\u3044</span>\n      <span class=\"opt\">4. \u304a\u3068\u306a\u3057\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u81ea\u8ee2\u8eca\u3067\u8ee2\u3093\u3067\u3001\u8db3\u304c<u>\u75db\u3044</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Karena jatuh dari sepeda, kaki saya terasa sakit.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3064\u3089\u3044</span>\n      <span class=\"opt\">2. \u304f\u3055\u3044</span>\n      <span class=\"opt\">3. \u304b\u3086\u3044</span>\n      <span class=\"opt\">4. \u3044\u305f\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u6628\u65e5\u8cb7\u3063\u305f\u8f9e\u66f8\u306f\u3068\u3066\u3082<u>\u539a\u3044</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Kamus yang saya beli kemarin sangat tebal.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3046\u3059\u3044</span>\n      <span class=\"opt\">2. \u3042\u3064\u3044</span>\n      <span class=\"opt\">3. \u3061\u3044\u3055\u3044</span>\n      <span class=\"opt\">4. \u305f\u304b\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u4eca\u904b\u3093\u3067\u3044\u308b\u8377\u7269\u306f<u>\u8efd\u3044</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Barang bawaan yang sedang saya angkut sekarang terasa ringan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3075\u3068\u3044</span>\n      <span class=\"opt\">2. \u304a\u3082\u3044</span>\n      <span class=\"opt\">3. \u304b\u308b\u3044</span>\n      <span class=\"opt\">4. \u307b\u305d\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\">\u660e\u65e5\u304b\u3089<u>\u65b0\u3057\u3044</u>\u751f\u6d3b\u304c\u59cb\u307e\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Mulai besok kehidupan yang baru akan dimulai.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u307e\u305a\u3057\u3044</span>\n      <span class=\"opt\">2. \u3055\u3073\u3057\u3044</span>\n      <span class=\"opt\">3. \u3042\u305f\u3089\u3057\u3044</span>\n      <span class=\"opt\">4. \u304f\u308b\u3057\u3044</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 4\u3000\u2461 4\u3000\u2462 2\u3000\u2463 2\u3000\u2464 3\u3000\u2465 1\u3000\u2466 4\u3000\u2467 2\u3000\u2468 3\u3000\u2469 3</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-1-p72\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c1: Set 8 (Kata Sifat-i &amp; Kata Sifat-na \u00b7 Hal. 69)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c1\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u306e\u8aad\u307f\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah cara baca yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u5bd2\u3044\u306e\u3067\u3001<u>\u6e29\u304b\u3044</u>\u98f2\u307f\u7269\u3092\u98f2\u3082\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Karena dingin, mari kita minum minuman yang hangat.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3053\u307e\u304b\u3044</span>\n      <span class=\"opt\">2. \u3042\u305f\u305f\u304b\u3044</span>\n      <span class=\"opt\">3. \u305f\u304b\u3044</span>\n      <span class=\"opt\">4. \u3084\u308f\u3089\u304b\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\"><u>\u6b32\u3057\u3044</u>\u7d75\u304c\u306a\u304b\u3063\u305f\u306e\u3067\u3001\u5e97\u3092\u51fa\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena tidak ada lukisan yang saya inginkan, saya keluar dari toko.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3081\u305a\u3089\u3057\u3044</span>\n      <span class=\"opt\">2. \u3042\u3084\u3057\u3044</span>\n      <span class=\"opt\">3. \u3059\u3070\u3089\u3057\u3044</span>\n      <span class=\"opt\">4. \u307b\u3057\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\"><u>\u6b63\u3057\u3044</u>\u7d50\u679c\u304c\u51fa\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Hasil yang benar telah keluar.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305f\u3060\u3057\u3044</span>\n      <span class=\"opt\">2. \u304f\u308f\u3057\u3044</span>\n      <span class=\"opt\">3. \u304f\u3084\u3057\u3044</span>\n      <span class=\"opt\">4. \u304b\u306a\u3057\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u3053\u306e\u5c71\u306f\u3001\u3042\u306e\u5c71\u3088\u308a\u3082<u>\u4f4e\u3044</u>\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Gunung ini lebih rendah daripada gunung itu.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304d\u305f\u306a\u3044</span>\n      <span class=\"opt\">2. \u3072\u308d\u3044</span>\n      <span class=\"opt\">3. \u305b\u307e\u3044</span>\n      <span class=\"opt\">4. \u3072\u304f\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u59b9\u304c<u>\u53ef\u611b\u304f\u3066</u>\u4ed5\u65b9\u304c\u306a\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Adik perempuan saya sangat imut (menggemaskan) sampai tidak tertahankan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304b\u308f\u3044\u304f\u3066</span>\n      <span class=\"opt\">2. \u3053\u3044\u3057\u304f\u3066</span>\n      <span class=\"opt\">3. \u3046\u3089\u3084\u307e\u3057\u304f\u3066</span>\n      <span class=\"opt\">4. \u3046\u3064\u304f\u3057\u304f\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u5f7c\u5973\u306f\u52c9\u5f37<u>\u71b1\u5fc3</u>\u306a\u751f\u5f92\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Dia (perempuan) adalah siswa yang tekun (rajin) belajar.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u306d\u3064\u3058\u3093</span>\n      <span class=\"opt\">2. \u306d\u3063\u3058\u3093</span>\n      <span class=\"opt\">3. \u306d\u3063\u3057\u3093</span>\n      <span class=\"opt\">4. \u306d\u3064\u3057\u3093</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\"><u>\u5927\u4e8b</u>\u306a\u3086\u3073\u308f\u3092\u306a\u304f\u3057\u3066\u3057\u307e\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya kehilangan cincin yang berharga (penting).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3060\u3044\u3057</span>\n      <span class=\"opt\">2. \u305f\u3044\u3057</span>\n      <span class=\"opt\">3. \u305f\u3044\u3058</span>\n      <span class=\"opt\">4. \u3060\u3044\u3058</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u5bb6\u306e\u8fd1\u304f\u306b\u30b3\u30f3\u30d3\u30cb\u304c\u306a\u304f\u3066<u>\u4e0d\u4fbf</u>\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Karena tidak ada minimarket di dekat rumah, jadi tidak praktis.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3075\u3079\u3093</span>\n      <span class=\"opt\">2. \u3075\u3078\u3093</span>\n      <span class=\"opt\">3. \u3075\u3046\u3079\u3093</span>\n      <span class=\"opt\">4. \u3075\u3046\u3078\u3093</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u6628\u65e5\u306e\u8a66\u5408\u306f<u>\u6b8b\u5ff5</u>\u306a\u7d50\u679c\u306b\u306a\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Pertandingan kemarin berakhir dengan hasil yang mengecewakan (disayangkan).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3058\u3083\u3093\u306d\u3093</span>\n      <span class=\"opt\">2. \u3056\u3093\u306d\u3093</span>\n      <span class=\"opt\">3. \u3055\u3093\u306d\u3093</span>\n      <span class=\"opt\">4. \u3058\u3083\u306d\u3093</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\">\u6bcd\u304b\u3089<u>\u7c21\u5358</u>\u306a\u6599\u7406\u3092\u6559\u3048\u3066\u3082\u3089\u3044\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya diajari masakan yang mudah (sederhana) oleh ibu.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304b\u3093\u305f\u3093</span>\n      <span class=\"opt\">2. \u304b\u305f\u3093</span>\n      <span class=\"opt\">3. \u304b\u3093\u305f</span>\n      <span class=\"opt\">4. \u304b\u305f</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 4\u3000\u2462 1\u3000\u2463 4\u3000\u2464 1\u3000\u2465 3\u3000\u2466 4\u3000\u2467 1\u3000\u2468 2\u3000\u2469 1</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-1-p73\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c1: Set 9 (Kata Sifat-na \u00b7 Hal. 70)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c1\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u306e\u8aad\u307f\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah cara baca yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u5f7c\u5973\u306b<u>\u6b63\u76f4</u>\u306a\u6c17\u6301\u3061\u3092\u4f1d\u3048\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Menyampaikan perasaan yang jujur kepadanya (perempuan).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3057\u3087\u3046\u3061\u3087\u304f</span>\n      <span class=\"opt\">2. \u3057\u3087\u3061\u3087\u304f</span>\n      <span class=\"opt\">3. \u3057\u3087\u3058\u304d</span>\n      <span class=\"opt\">4. \u3057\u3087\u3046\u3058\u304d</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u65c5\u884c\u306b<u>\u5fc5\u8981</u>\u306a\u3082\u306e\u3092\u8cb7\u3044\u306b\u884c\u304d\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Ayo pergi membeli barang-barang yang diperlukan untuk perjalanan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3072\u3064\u3058\u3087\u3046</span>\n      <span class=\"opt\">2. \u3072\u3064\u3058\u3087</span>\n      <span class=\"opt\">3. \u3072\u3064\u3088\u3046</span>\n      <span class=\"opt\">4. \u3072\u3064\u3088</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\"><ruby>\u5148<rt>\u305b\u3093</rt></ruby><ruby>\u8f29<rt>\u3071\u3044</rt></ruby>\u306b<u>\u5931\u793c</u>\u306a\u3053\u3068\u3092\u3057\u3066\u3057\u307e\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya telah melakukan hal yang tidak sopan kepada senior.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3057\u3064\u308c\u3044</span>\n      <span class=\"opt\">2. \u3057\u3063\u308c\u3044</span>\n      <span class=\"opt\">3. \u3057\u3064\u308c</span>\n      <span class=\"opt\">4. \u3057\u3063\u308c</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><u>\u82e6\u624b</u>\u306a\u98df\u3079\u7269\u306f\u306b\u3093\u3058\u3093\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Makanan yang tidak saya sukai (kurang pandai makan) adalah wortel.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304f\u308b\u3066</span>\n      <span class=\"opt\">2. \u306b\u304c\u3057\u3085</span>\n      <span class=\"opt\">3. \u304f\u308b\u3057\u3085</span>\n      <span class=\"opt\">4. \u306b\u304c\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\"><u>\u81ea\u7531</u>\u306b\u6587\u7ae0\u3092\u66f8\u3044\u3066\u307f\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Mari kita coba menulis karangan dengan bebas.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3058\u3086</span>\n      <span class=\"opt\">2. \u3058\u3086\u3046</span>\n      <span class=\"opt\">3. \u3057\u3086</span>\n      <span class=\"opt\">4. \u3057\u3086\u3046</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\"><u>\u4e0d\u8981</u>\u306a\u3082\u306e\u306f\u8cb7\u308f\u306a\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Barang yang tidak perlu tidak saya beli.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3075\u3088</span>\n      <span class=\"opt\">2. \u3075\u308a\u3087</span>\n      <span class=\"opt\">3. \u3075\u3088\u3046</span>\n      <span class=\"opt\">4. \u3075\u308a\u3087\u3046</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\"><u>\u5b89\u5168</u>\u306a\u5834\u6240\u3067<ruby>\u904a<rt>\u3042\u305d</rt></ruby>\u3073\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Mari bermain di tempat yang aman.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3042\u305c\u3093</span>\n      <span class=\"opt\">2. \u3042\u3093\u305b\u3044</span>\n      <span class=\"opt\">3. \u3042\u3093\u305b\u3093</span>\n      <span class=\"opt\">4. \u3042\u3093\u305c\u3093</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u4e00\u4eba\u3067\u3059\u308b\u306b\u306f<u>\u5927\u5909</u>\u306a\u4ed5\u4e8b\u3067\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Itu adalah pekerjaan yang berat (sulit) untuk dikerjakan sendirian.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305f\u3044\u3079\u3093</span>\n      <span class=\"opt\">2. \u305f\u3044\u3078\u3093</span>\n      <span class=\"opt\">3. \u3060\u3044\u3078\u3093</span>\n      <span class=\"opt\">4. \u3060\u3044\u3079\u3093</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u4eca\u65e5\u306f\u4f11\u307f\u3060\u3063\u305f\u306e\u3067<u>\u5341\u5206</u>\u306b\u5bdd\u308b\u3053\u3068\u304c\u3067\u304d\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena hari ini libur, saya bisa tidur dengan cukup.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3058\u3085\u3046\u3075\u3093</span>\n      <span class=\"opt\">2. \u3058\u3085\u3075\u3093</span>\n      <span class=\"opt\">3. \u3058\u3085\u3046\u3076\u3093</span>\n      <span class=\"opt\">4. \u3058\u3085\u3076\u3093</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\">\u4eca\u56de\u306e\u4f1a\u8b70\u306f<u>\u4e3b\u8981</u>\u306a\u30e1\u30f3\u30d0\u30fc\u3067\u884c\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Rapat kali ini akan diadakan oleh anggota inti (utama).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3057\u3085\u3088\u3046</span>\n      <span class=\"opt\">2. \u3057\u3085\u3088</span>\n      <span class=\"opt\">3. \u3057\u3085\u3046\u3088\u3046</span>\n      <span class=\"opt\">4. \u3057\u3085\u3046\u3088</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 4\u3000\u2461 3\u3000\u2462 1\u3000\u2463 4\u3000\u2464 2\u3000\u2465 3\u3000\u2466 4\u3000\u2467 2\u3000\u2468 3\u3000\u2469 1</div>\n</div>\n\n</div><!-- /#mondai-1 -->\n\n\n\n<div class=\"mondai-section\" id=\"mondai-2\">\n\n  <h3>\u554f\u984c2\u3000\u8868\u8a18: Penulisan Kanji</h3>\n\n  <div class=\"example-box\">\n\n    <h4>\u3007 Contoh Soal \u554f\u984c2 (\u554f\u984c2 \u4f8b \u00b7 Hal. 71)</h4>\n\n    <div class=\"q-instruction\">\n\n      <div class=\"q-inst-jp\">\u554f\u984c2\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u3092\u6f22\u5b57\u3067\u66f8\u304f\u3068\u304d\u3001\u6700\u3082\u3088\u3044\u3082\u306e\u30921\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n\n      <div class=\"q-inst-id\">Pilihlah penulisan kanji yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n\n    </div>\n\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u30d1\u30fc\u30c6\u30a3\u30fc\u3092<u>\u3057\u3093\u3053\u3046</u>\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Memandu (melangsungkan) jalannya pesta.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u9032\u884c</span>\n      <span class=\"opt\">2. \u63a8\u884c</span>\n      <span class=\"opt\">3. \u9032\u5f8c</span>\n      <span class=\"opt\">4. \u63a8\u5f8c</span>\n    </div>\n  </div>\n\n    <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> 1<div class=\"answer-note\"><strong>Catatan Kanji:</strong> \u9032\u884c (\u3057\u3093\u3053\u3046) = melangsungkan/memajukan jalannya acara; pilihan 2, 3, 4 bukan kata bahasa Jepang yang baku.</div></div>\n\n  </div>\n\n\n\n  <div class=\"strategy-box\">\n\n    <h4>Strategi &amp; Tips \u554f\u984c2 (Penulisan Kanji)</h4>\n\n    <p class=\"jp-quote\"><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>2\u3067\u306f\u3001<ruby>\u6f22<rt>\u304b\u3093</rt></ruby><ruby>\u5b57<rt>\u3058</rt></ruby>\u306e<ruby>\u5f62<rt>\u304b\u305f\u3061</rt></ruby>\u3092<ruby>\u7b54<rt>\u3053\u305f</rt></ruby>\u3048\u308b<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u304c6<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\u306e<ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u306b\u306f\u3001<ruby>\u4f3c<rt>\u306b</rt></ruby>\u3066\u3044\u308b<ruby>\u5f62<rt>\u304b\u305f\u3061</rt></ruby>\u306e<ruby>\u6f22<rt>\u304b\u3093</rt></ruby><ruby>\u5b57<rt>\u3058</rt></ruby>\u3084<ruby>\u8aad<rt>\u3088</rt></ruby>\u307f<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058\u3067<ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby>\u304c<ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3046<ruby>\u6f22<rt>\u304b\u3093</rt></ruby><ruby>\u5b57<rt>\u3058</rt></ruby>\u304c\u3088\u304f<ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002\u304d\u3061\u3093\u3068<ruby>\u6f22<rt>\u304b\u3093</rt></ruby><ruby>\u5b57<rt>\u3058</rt></ruby>\u306e<ruby>\u5f62<rt>\u304b\u305f\u3061</rt></ruby>\u3068<ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby>\u3092<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u307e\u3057\u3087\u3046\u3002</p>\n\n    <p>Pada <strong>Mondai 2</strong>, akan keluar <strong>6 soal</strong> yang menanyakan bentuk penulisan kanji yang benar. Di dalam pilihan jawabannya, sering muncul kanji yang bentuknya mirip atau kanji yang cara bacanya sama (homofon) tetapi artinya berbeda. Pastikan Anda menghafalkan bentuk serta arti setiap kanji dengan tepat.</p>\n\n  </div>\n\n<div class=\"exercise-set\" id=\"mondai-2-p75\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c2: Set 1 (Kanji 1 Huruf \u00b7 Hal. 72)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c2\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u3092\u6f22\u5b57\u3067\u66f8\u304f\u3068\u304d\u3001\u6700\u3082\u3088\u3044\u3082\u306e\u30921\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah penulisan kanji yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u6d77\u306b\u5c0f\u3055\u3044<u>\u3075\u306d</u>\u304c\u3001\u307d\u3064\u3093\u3068<ruby>\u6d6e<rt>\u3046</rt></ruby>\u304b\u3093\u3067\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Di laut tampak sebuah perahu kecil mengapung sendirian.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u8229</span>\n      <span class=\"opt\">2. \u822c</span>\n      <span class=\"opt\">3. \u8239</span>\n      <span class=\"opt\">4. \u822a</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u306f\u305a\u304b\u3057\u304f\u3066<u>\u304b\u304a</u>\u304c\u8d64\u304f\u306a\u3063\u3066\u3057\u307e\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena malu, wajah saya menjadi merah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u982d</span>\n      <span class=\"opt\">2. \u9854</span>\n      <span class=\"opt\">3. \u984d</span>\n      <span class=\"opt\">4. \u9858</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u7a7a\u6c17\u3092\u5165\u308c\u304b\u3048\u308b\u305f\u3081\u306b\u3001<u>\u307e\u3069</u>\u3092\u958b\u3051\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya membuka jendela untuk mengganti udara.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u7a93</span>\n      <span class=\"opt\">2. \u7a7a</span>\n      <span class=\"opt\">3. \u7a74</span>\n      <span class=\"opt\">4. \u7a76</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><ruby>\u6751<rt>\u3080\u3089</rt></ruby><ruby>\u4e0a<rt>\u304b\u307f</rt></ruby>\u3055\u3093\u306e<u>\u3088\u3053</u>\u306b\u306f<ruby>\u4f50<rt>\u3055</rt></ruby><ruby>\u85e4<rt>\u3068\u3046</rt></ruby>\u3055\u3093\u304c\u3059\u308f\u3063\u3066\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Di sebelah Murakami-san duduk Sato-san.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6838</span>\n      <span class=\"opt\">2. \u683c</span>\n      <span class=\"opt\">3. \u6905</span>\n      <span class=\"opt\">4. \u6a2a</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\"><u>\u305f\u307e\u3054</u>\u306f\u3001<ruby>\u713c<rt>\u3084</rt></ruby>\u3044\u3066\u3082\u751f\u3067\u98df\u3079\u3066\u3082\u304a\u3044\u3057\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Telur itu enak baik digoreng maupun dimakan mentah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u53e9</span>\n      <span class=\"opt\">2. \u5370</span>\n      <span class=\"opt\">3. \u5375</span>\n      <span class=\"opt\">4. \u5373</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u4eca\u56de\u306e\u30a4\u30d9\u30f3\u30c8\u306f\u3001<u>\u3084\u304f</u>\u4e00\u4e07\u4eba\u304c<ruby>\u53c2<rt>\u3055\u3093</rt></ruby><ruby>\u52a0<rt>\u304b</rt></ruby>\u3059\u308b\u305d\u3046\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Kabarnya acara kali ini akan dihadiri oleh sekitar sepuluh ribu orang.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u7d50</span>\n      <span class=\"opt\">2. \u7d42</span>\n      <span class=\"opt\">3. \u7d66</span>\n      <span class=\"opt\">4. \u7d04</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u5144\u306f\u3001\u6d77\u5916\u306e<u>\u304d\u3087\u304f</u>\u3092\u3088\u304f\u304d\u3044\u3066\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Kakak laki-laki saya sering mendengarkan lagu luar negeri.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u66ff</span>\n      <span class=\"opt\">2. \u66f2</span>\n      <span class=\"opt\">3. \u5192</span>\n      <span class=\"opt\">4. \u66f4</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u4eca\u9031\u306f\u3001\u4ed5\u4e8b\u306e<u>\u308a\u3087\u3046</u>\u304c\u591a\u304f\u3066\u65e9\u304f\u5e30\u308b\u3053\u3068\u304c\u3067\u304d\u306a\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Minggu ini volume (jumlah) pekerjaan banyak sehingga saya tidak bisa pulang cepat.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u91cd</span>\n      <span class=\"opt\">2. \u91cf</span>\n      <span class=\"opt\">3. \u91cc</span>\n      <span class=\"opt\">4. \u91ce</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u7740\u7269\u306e<u>\u304a\u3073</u>\u3092\u4e00\u4eba\u3067\u7d50\u3076\u3053\u3068\u306f\u3001\u3068\u3066\u3082\u96e3\u3057\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Mengikat obi kimono seorang diri itu sangat sulit.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u5e0c</span>\n      <span class=\"opt\">2. \u5e03</span>\n      <span class=\"opt\">3. \u5e55</span>\n      <span class=\"opt\">4. \u5e2f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\">\u9577\u3044\u6642\u9593\u8d70\u3063\u3066\u3044\u308b\u3068<u>\u3044\u304d</u>\u304c\u82e6\u3057\u304f\u306a\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Jika berlari dalam waktu lama, napas akan terasa sesak.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u60a3</span>\n      <span class=\"opt\">2. \u5fd7</span>\n      <span class=\"opt\">3. \u606f</span>\n      <span class=\"opt\">4. \u6075</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\u3000\u2461 2\u3000\u2462 1\u3000\u2463 4\u3000\u2464 3\u3000\u2465 4\u3000\u2466 2\u3000\u2467 2\u3000\u2468 4\u3000\u2469 3\n    <div class=\"answer-note\"><strong>Catatan Kanji:</strong> \u2460 \u8239 (perahu/kapal); \u2461 \u9854 (wajah; bedakan dgn \u982d=kepala, \u984d=dahi, \u9858=harapan); \u2462 \u7a93 (jendela); \u2463 \u6a2a (samping); \u2464 \u5375 (telur); \u2465 \u7d04 (sekitar/kira-kira); \u2466 \u66f2 (lagu); \u2467 \u91cf (jumlah/volume; bedakan dgn \u91cd=berat); \u2468 \u5e2f (obi/ikat pinggang); \u2469 \u606f (napas).</div></div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-2-p76\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c2: Set 2 (Kanji Gabungan 2 Huruf \u00b7 Hal. 73)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c2\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u3092\u6f22\u5b57\u3067\u66f8\u304f\u3068\u304d\u3001\u6700\u3082\u3088\u3044\u3082\u306e\u30921\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah penulisan kanji yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u5e73\u65e5\u306e\u671d\u306f\u3001\u3069\u306e\u96fb\u8eca\u3082<u>\u307e\u3093\u3044\u3093</u>\u3067\u5e2d\u306b\u5ea7\u308b\u3053\u3068\u304c\u3067\u304d\u306a\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Pada pagi hari kerja, semua kereta penuh sesak sehingga tidak bisa duduk di kursi.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u4e07\u9662</span>\n      <span class=\"opt\">2. \u6e80\u54e1</span>\n      <span class=\"opt\">3. \u4e07\u54e1</span>\n      <span class=\"opt\">4. \u6e80\u9662</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u308f\u305f\u3057\u306e\u4ed5\u4e8b\u306f\u3001\u4e16\u754c\u306e\u65b0\u3057\u3044\u51fa\u6765\u4e8b\u3092<u>\u304d\u3058</u>\u306b\u3059\u308b\u3053\u3068\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Pekerjaan saya adalah menulis berita (artikel) tentang peristiwa-peristiwa baru di dunia.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u8a18\u4e8b</span>\n      <span class=\"opt\">2. \u8a8c\u4e8b</span>\n      <span class=\"opt\">3. \u8a18\u5730</span>\n      <span class=\"opt\">4. \u8a8c\u5730</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u30ec\u30b8\u306e<u>\u304d\u304b\u3044</u>\u304c\u3053\u308f\u308c\u3066\u3057\u307e\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Mesin kasirnya rusak.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6a4b\u68b0</span>\n      <span class=\"opt\">2. \u6982\u68b0</span>\n      <span class=\"opt\">3. \u6a5f\u68b0</span>\n      <span class=\"opt\">4. \u6975\u68b0</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><u>\u304b\u3044\u3060\u3093</u>\u3092\u306e\u307c\u3063\u305f\u5148\u306b\u306f\u3001\u304d\u308c\u3044\u306a<ruby>\u666f\u8272<rt>\u3051\u3057\u304d</rt></ruby>\u304c\u5e83\u304c\u3063\u3066\u3044\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Di ujung setelah menaiki tangga, terbentang pemandangan yang indah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u968e\u6bb5</span>\n      <span class=\"opt\">2. \u958b\u56e3</span>\n      <span class=\"opt\">3. \u968e\u56e3</span>\n      <span class=\"opt\">4. \u958b\u6bb5</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u5929\u6c17<u>\u3088\u307b\u3046</u>\u3067\u306f<ruby>\u6674<rt>\u306f</rt></ruby>\u308c\u3060\u3063\u305f\u306e\u306b\u3001\u96e8\u304c<ruby>\u964d<rt>\u3075</rt></ruby>\u3063\u3066\u304d\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Di prakiraan cuaca disebutkan cerah, tetapi malah turun hujan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u9810\u5831</span>\n      <span class=\"opt\">2. \u4e88\u6cd5</span>\n      <span class=\"opt\">3. \u9810\u6cd5</span>\n      <span class=\"opt\">4. \u4e88\u5831</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\"><u>\u305a\u3064\u3046</u>\u304c\u7d9a\u3044\u3066\u3044\u308b\u306e\u3067\u3001<ruby>\u85ac<rt>\u304f\u3059\u308a</rt></ruby>\u3092\u98f2\u307f\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena sakit kepala terus berlanjut, saya minum obat.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u982d\u75c7</span>\n      <span class=\"opt\">2. \u982d\u75b2</span>\n      <span class=\"opt\">3. \u982d\u75db</span>\n      <span class=\"opt\">4. \u982d\u75c5</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\"><u>\u307c\u3046\u3048\u304d</u>\u306b\u3088\u3063\u3066\u3001\u6d77\u5916\u306e\u3082\u306e\u3092\u624b\u306b\u5165\u308c\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Melalui perdagangan (luar negeri), kita dapat memperoleh barang-barang dari luar negeri.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u8cbf\u662f</span>\n      <span class=\"opt\">2. \u8cc3\u662f</span>\n      <span class=\"opt\">3. \u8cbf\u6613</span>\n      <span class=\"opt\">4. \u8cc3\u6613</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\"><ruby>\u9234<rt>\u3059\u305a</rt></ruby><ruby>\u6728<rt>\u304d</rt></ruby>\u3055\u3093\u306f\u3001\u307f\u3093\u306a\u306b\u512a\u3057\u304f\u3066<u>\u305b\u3044\u304b\u304f</u>\u304c\u3044\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Suzuki-san baik kepada semua orang dan berkepribadian baik.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u751f\u5404</span>\n      <span class=\"opt\">2. \u6027\u5404</span>\n      <span class=\"opt\">3. \u751f\u683c</span>\n      <span class=\"opt\">4. \u6027\u683c</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u3053\u306e\u9ce5\u306f\u3001\u30bb\u30ad\u30bb\u30a4\u30a4\u30f3\u30b3\u3068\u3044\u3046<u>\u3057\u3085\u308b\u3044</u>\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Burung ini termasuk jenis yang disebut parkit (sekisei inko).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u7a0e\u985e</span>\n      <span class=\"opt\">2. \u7a2e\u985e</span>\n      <span class=\"opt\">3. \u7a4d\u985e</span>\n      <span class=\"opt\">4. \u7a0b\u985e</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\"><u>\u3057\u3087\u3046\u305b\u3064</u>\u3092\u8aad\u3093\u3067\u3044\u308b\u6642\u9593\u304c\u4e00\u756a\u597d\u304d\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Waktu saat membaca novel adalah waktu yang paling saya sukai.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u5c0f\u8a2d</span>\n      <span class=\"opt\">2. \u5c11\u8aac</span>\n      <span class=\"opt\">3. \u5c0f\u8aac</span>\n      <span class=\"opt\">4. \u5c11\u8a2d</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 1\u3000\u2462 3\u3000\u2463 1\u3000\u2464 4\u3000\u2465 3\u3000\u2466 3\u3000\u2467 4\u3000\u2468 2\u3000\u2469 3\n    <div class=\"answer-note\"><strong>Catatan Kanji:</strong> \u2460 \u6e80\u54e1 (penuh sesak); \u2461 \u8a18\u4e8b (artikel); \u2462 \u6a5f\u68b0 (mesin); \u2463 \u968e\u6bb5 (tangga); \u2464 \u4e88\u5831 (prakiraan; bedakan dgn \u9810=titip); \u2465 \u982d\u75db (sakit kepala); \u2466 \u8cbf\u6613 (perdagangan); \u2467 \u6027\u683c (sifat/kepribadian); \u2468 \u7a2e\u985e (jenis); \u2469 \u5c0f\u8aac (novel).</div></div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-2-p77\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c2: Set 3 (Kanji Gabungan 2-3 Huruf \u00b7 Hal. 74)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c2\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u3092\u6f22\u5b57\u3067\u66f8\u304f\u3068\u304d\u3001\u6700\u3082\u3088\u3044\u3082\u306e\u30921\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah penulisan kanji yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u6bce\u6708\u3001\u6c34\u9053\u306e<u>\u3057\u3088\u3046\u308a\u3087\u3046</u>\u304c\u9ad8\u304f\u306a\u3063\u3066\u3057\u307e\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Setiap bulan biaya pemakaian air menjadi mahal.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u4f7f\u89d2\u6599</span>\n      <span class=\"opt\">2. \u4ed5\u7528\u6599</span>\n      <span class=\"opt\">3. \u4ed5\u89d2\u6599</span>\n      <span class=\"opt\">4. \u4f7f\u7528\u6599</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u6728\u66dc\u65e5\u306f<u>\u3066\u3044\u304d\u3085\u3046\u3073</u>\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Hari Kamis adalah hari libur tetap.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u7a0b\u4f11\u65e5</span>\n      <span class=\"opt\">2. \u7a0b\u4f53\u65e5</span>\n      <span class=\"opt\">3. \u5b9a\u4f11\u65e5</span>\n      <span class=\"opt\">4. \u5b9a\u4f53\u65e5</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u597d\u304d\u306a\u4eba\u306e<u>\u308c\u3093\u3089\u304f\u3055\u304d</u>\u3092\u6559\u3048\u3066\u3082\u3089\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya diberi tahu informasi kontak orang yang saya sukai.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u9023\u7d1a\u5148</span>\n      <span class=\"opt\">2. \u9023\u7d61\u5148</span>\n      <span class=\"opt\">3. \u7df4\u7d1a\u5148</span>\n      <span class=\"opt\">4. \u7df4\u7d61\u5148</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><u>\u3042\u304b\u3057\u3093\u3054\u3046</u>\u306e\u3068\u304d\u306b<ruby>\u6e21<rt>\u308f\u305f</rt></ruby>\u3063\u3066\u306f\u3044\u3051\u307e\u305b\u3093\u3002</span></div>\n    <div class=\"q-id-trans\">Tidak boleh menyeberang saat lampu merah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u8d64\u500d\u8003</span>\n      <span class=\"opt\">2. \u8d64\u500d\u53f7</span>\n      <span class=\"opt\">3. \u8d64\u4fe1\u8003</span>\n      <span class=\"opt\">4. \u8d64\u4fe1\u53f7</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u5f7c\u5973\u306f\u3001\u30c8\u30e9\u30c3\u30af\u306e<u>\u3046\u3093\u3066\u3093\u3057\u3085</u>\u3092\u3057\u3066\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Dia (perempuan) bekerja sebagai pengemudi truk.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u904b\u8ee2\u624b</span>\n      <span class=\"opt\">2. \u9045\u8ed2\u624b</span>\n      <span class=\"opt\">3. \u904b\u8ed2\u624b</span>\n      <span class=\"opt\">4. \u9045\u8ee2\u624b</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u4f1a\u793e\u304b\u3089\u793e\u54e1\u306b\u304a\u91d1\u3092<u>\u3057\u304d\u3085\u3046</u>\u3057\u3066\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Perusahaan memberikan (membayarkan) uang kepada karyawan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u652f\u7d66</span>\n      <span class=\"opt\">2. \u652f\u7dad</span>\n      <span class=\"opt\">3. \u652f\u7e3e</span>\n      <span class=\"opt\">4. \u652f\u7d61</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u3048\u3044\u3088\u3046\u3092<u>\u3044\u3057\u304d</u>\u3057\u3066\u3001\u91ce\u83dc\u3092\u305f\u304f\u3055\u3093\u98df\u3079\u3066\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Saya memperhatikan gizi secara sadar dan banyak makan sayuran.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u610f\u8077</span>\n      <span class=\"opt\">2. \u610f\u7e54</span>\n      <span class=\"opt\">3. \u610f\u8b58</span>\n      <span class=\"opt\">4. \u610f\u5e5f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\"><ruby>\u6771<rt>\u3068\u3046</rt></ruby><ruby>\u4eac<rt>\u304d\u3087\u3046</rt></ruby>\u304b\u3089<ruby>\u5927<rt>\u304a\u304a</rt></ruby><ruby>\u962a<rt>\u3055\u304b</rt></ruby>\u307e\u3067\u8eca\u3067<u>\u3044\u3069\u3046</u>\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Berpindah (bepergian) dari Tokyo ke Osaka naik mobil.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u79d1\u52d5</span>\n      <span class=\"opt\">2. \u79fb\u52d5</span>\n      <span class=\"opt\">3. \u7a4d\u52d5</span>\n      <span class=\"opt\">4. \u7a0e\u52d5</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u6765\u6708\u306b\u884c\u3046\u30a4\u30d9\u30f3\u30c8\u306e<u>\u3058\u3085\u3093\u3073</u>\u3092\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Melakukan persiapan untuk acara yang akan diadakan bulan depan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u9806\u65e5</span>\n      <span class=\"opt\">2. \u6e96\u65e5</span>\n      <span class=\"opt\">3. \u9806\u5099</span>\n      <span class=\"opt\">4. \u6e96\u5099</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\">\u9053\u3092<u>\u304a\u3046\u3060\u3093</u>\u3059\u308b\u3068\u304d\u306f\u3001\u8eca\u306b\u6c17\u3092\u3064\u3051\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Saat menyeberang jalan, berhati-hatilah terhadap mobil.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6a2a\u6bb5</span>\n      <span class=\"opt\">2. \u5fdc\u6bb5</span>\n      <span class=\"opt\">3. \u5fdc\u65ad</span>\n      <span class=\"opt\">4. \u6a2a\u65ad</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 4\u3000\u2461 3\u3000\u2462 2\u3000\u2463 4\u3000\u2464 1\u3000\u2465 1\u3000\u2466 3\u3000\u2467 2\u3000\u2468 4\u3000\u2469 4\n    <div class=\"answer-note\"><strong>Catatan Kanji:</strong> \u2460 \u4f7f\u7528\u6599 (biaya pemakaian); \u2461 \u5b9a\u4f11\u65e5 (hari libur tetap); \u2462 \u9023\u7d61\u5148 (kontak); \u2463 \u8d64\u4fe1\u53f7 (lampu merah); \u2464 \u904b\u8ee2\u624b (sopir); \u2465 \u652f\u7d66 (pemberian/tunjangan); \u2466 \u610f\u8b58 (kesadaran); \u2467 \u79fb\u52d5 (berpindah); \u2468 \u6e96\u5099 (persiapan); \u2469 \u6a2a\u65ad (menyeberang).</div></div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-2-p78\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c2: Set 4 (Kata Kerja Suru &amp; Kata Kerja Umum \u00b7 Hal. 75)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c2\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u3092\u6f22\u5b57\u3067\u66f8\u304f\u3068\u304d\u3001\u6700\u3082\u3088\u3044\u3082\u306e\u30921\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah penulisan kanji yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u30a2\u30ca\u30a6\u30f3\u30b5\u30fc\u304c\u6620\u753b\u306e\u5185\u5bb9\u3092<u>\u304b\u3044\u305b\u3064</u>\u3057\u3066\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Penyiar sedang mengulas (menjelaskan) isi film.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u958b\u8a2d</span>\n      <span class=\"opt\">2. \u89e3\u8aac</span>\n      <span class=\"opt\">3. \u958b\u8aac</span>\n      <span class=\"opt\">4. \u89e3\u8a2d</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u98df\u3079\u7269\u306e\u7a2e\u985e\u3092<u>\u3076\u3093\u308b\u3044</u>\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Mengelompokkan (mengklasifikasikan) jenis-jenis makanan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u5206\u985e</span>\n      <span class=\"opt\">2. \u5206\u982d</span>\n      <span class=\"opt\">3. \u5206\u9854</span>\n      <span class=\"opt\">4. \u5206\u9858</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u591c\u3054\u98ef\u306b\u4f7f\u3046\u6750\u6599\u3092<u>\u3088\u3046\u3044</u>\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Menyiapkan bahan-bahan yang akan dipakai untuk makan malam.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u5bb9\u6613</span>\n      <span class=\"opt\">2. \u5bb9\u610f</span>\n      <span class=\"opt\">3. \u7528\u6613</span>\n      <span class=\"opt\">4. \u7528\u610f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u9031\u672b\u306b\u306f\u3001\u4f1a\u793e\u306e\u5236\u670d\u3092<u>\u305b\u3093\u305f\u304f</u>\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Pada akhir pekan, saya mencuci seragam perusahaan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6cbb\u6fef</span>\n      <span class=\"opt\">2. \u6ce8\u6fef</span>\n      <span class=\"opt\">3. \u6d41\u6fef</span>\n      <span class=\"opt\">4. \u6d17\u6fef</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\"><ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u3068\u4f1a\u3046\u5834\u6240\u3092<u>\u3057\u3066\u3044</u>\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Menentukan tempat untuk bertemu dengan teman.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6307\u5b97</span>\n      <span class=\"opt\">2. \u4f7f\u5b97</span>\n      <span class=\"opt\">3. \u6307\u5b9a</span>\n      <span class=\"opt\">4. \u4f7f\u5b9a</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u72ac\u306f\u3001\u3046\u308c\u3057\u3044\u3068\u304d\u3001\u304f\u308b\u304f\u308b\u3068<u>\u307e\u308f\u308a</u>\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Anjing saat senang akan berputar-putar.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u8d70\u308a</span>\n      <span class=\"opt\">2. \u56de\u308a</span>\n      <span class=\"opt\">3. \u53bb\u308a</span>\n      <span class=\"opt\">4. \u5ea7\u308a</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u65e5\u672c\u3067\u306f\u3001<ruby>\u4e8c\u5341\u6b73<rt>\u306f\u305f\u3061</rt></ruby>\u304b\u3089\u306f\u304a<ruby>\u9152<rt>\u3055\u3051</rt></ruby>\u3092\u98f2\u3080\u3053\u3068\u304c<u>\u3086\u308b\u3055\u308c\u308b</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Di Jepang, sejak usia 20 tahun diperbolehkan minum minuman beralkohol.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u8a08\u3055\u308c\u308b</span>\n      <span class=\"opt\">2. \u8a2d\u3055\u308c\u308b</span>\n      <span class=\"opt\">3. \u8a31\u3055\u308c\u308b</span>\n      <span class=\"opt\">4. \u8a18\u3055\u308c\u308b</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u6587\u7ae0\u3092\u5168\u90e8<u>\u3051\u3057\u3066</u>\u3001\u6700\u521d\u304b\u3089\u66f8\u304d\u76f4\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya menghapus seluruh kalimatnya, lalu menulis ulang dari awal.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6c5a\u3057\u3066</span>\n      <span class=\"opt\">2. \u6ed1\u3057\u3066</span>\n      <span class=\"opt\">3. \u6e05\u3057\u3066</span>\n      <span class=\"opt\">4. \u6d88\u3057\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u3042\u306e\u8d64\u3061\u3083\u3093\u306f\u4eca\u306b\u3082<u>\u3053\u308d\u3073\u305d\u3046</u>\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Bayi itu terlihat seperti hampir terjatuh sekarang juga.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u8efd\u3073\u305d\u3046</span>\n      <span class=\"opt\">2. \u8f38\u3073\u305d\u3046</span>\n      <span class=\"opt\">3. \u8ee2\u3073\u305d\u3046</span>\n      <span class=\"opt\">4. \u8ef8\u3073\u305d\u3046</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\">\u308f\u305f\u3057\u306f\u3001\u5f7c\u306b\u597d\u304d\u3060\u3068\u3044\u3046\u6c17\u6301\u3061\u3092\u624b\u7d19\u3067<u>\u3064\u305f\u3048\u305f</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Saya menyampaikan perasaan suka kepadanya (laki-laki) melalui surat.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u4f4d\u3048\u305f</span>\n      <span class=\"opt\">2. \u4efb\u3048\u305f</span>\n      <span class=\"opt\">3. \u4ed5\u3048\u305f</span>\n      <span class=\"opt\">4. \u4f1d\u3048\u305f</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 1\u3000\u2462 4\u3000\u2463 4\u3000\u2464 3\u3000\u2465 2\u3000\u2466 3\u3000\u2467 4\u3000\u2468 3\u3000\u2469 4\n    <div class=\"answer-note\"><strong>Catatan Kanji:</strong> \u2460 \u89e3\u8aac (penjelasan/ulasan; bedakan dgn \u958b\u8a2d=pendirian); \u2461 \u5206\u985e (klasifikasi); \u2462 \u7528\u610f (persiapan; bedakan dgn \u5bb9\u6613=mudah); \u2463 \u6d17\u6fef (mencuci baju); \u2464 \u6307\u5b9a (penentuan); \u2465 \u56de\u308a (berputar); \u2466 \u8a31\u3055\u308c\u308b (diizinkan); \u2467 \u6d88\u3057\u3066 (menghapus); \u2468 \u8ee2\u3073\u305d\u3046 (hampir jatuh); \u2469 \u4f1d\u3048\u305f (menyampaikan).</div></div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-2-p79\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c2: Set 5 (Kata Kerja &amp; Kata Sifat-i \u00b7 Hal. 76)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c2\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u3092\u6f22\u5b57\u3067\u66f8\u304f\u3068\u304d\u3001\u6700\u3082\u3088\u3044\u3082\u306e\u30921\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah penulisan kanji yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u5927\u5b66\u306e<ruby>\u5165<rt>\u306b\u3085\u3046</rt></ruby><ruby>\u5b66<rt>\u304c\u304f</rt></ruby><ruby>\u8a66<rt>\u3057</rt></ruby><ruby>\u9a13<rt>\u3051\u3093</rt></ruby>\u306b<u>\u304a\u3061\u3066</u>\u3057\u307e\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya gagal (tidak lulus) dalam ujian masuk universitas.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u843d\u3061\u3066</span>\n      <span class=\"opt\">2. \u82e6\u3061\u3066</span>\n      <span class=\"opt\">3. \u85ac\u3061\u3066</span>\n      <span class=\"opt\">4. \u8584\u3061\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u5165\u9662\u3057\u3066\u3044\u308b<ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u304c\u65e9\u304f\u5143\u6c17\u306b\u306a\u308b\u3053\u3068\u3092<u>\u306d\u304c\u3063\u3066</u>\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Saya berdoa (berharap) agar nenek yang sedang dirawat di rumah sakit cepat sembuh.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u9811\u3063\u3066</span>\n      <span class=\"opt\">2. \u9858\u3063\u3066</span>\n      <span class=\"opt\">3. \u9806\u3063\u3066</span>\n      <span class=\"opt\">4. \u9810\u3063\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u308f\u304c\u5bb6\u306f\u3001\u6b63\u6708\u3092<u>\u3080\u304b\u3048\u308b</u>\u6e96\u5099\u3067\u5927\u3044\u305d\u304c\u3057\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Keluarga kami sangat sibuk mempersiapkan diri untuk menyambut Tahun Baru.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u904e\u3048\u308b</span>\n      <span class=\"opt\">2. \u8ff7\u3048\u308b</span>\n      <span class=\"opt\">3. \u901a\u3048\u308b</span>\n      <span class=\"opt\">4. \u8fce\u3048\u308b</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u81ea\u5206\u306e\u60aa\u3044\u3068\u3053\u308d\u3092\u3001\u304d\u3061\u3093\u3068<u>\u306a\u304a\u3057\u3066</u>\u3044\u304d\u305f\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Saya ingin memperbaiki bagian buruk dari diri saya dengan sungguh-sungguh.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6b63\u3057\u3066</span>\n      <span class=\"opt\">2. \u76f4\u3057\u3066</span>\n      <span class=\"opt\">3. \u80b2\u3057\u3066</span>\n      <span class=\"opt\">4. \u6559\u3057\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u672c\u306b\u51fa\u3066\u304d\u305f\u3001\u308f\u304b\u3089\u306a\u3044\u6f22\u5b57\u306e\u610f\u5473\u3092<u>\u3057\u3089\u3079\u308b</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Mencari tahu arti kanji yang tidak dipahami yang muncul dalam buku.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u8abf\u3079\u308b</span>\n      <span class=\"opt\">2. \u8a3c\u3079\u308b</span>\n      <span class=\"opt\">3. \u8a2a\u3079\u308b</span>\n      <span class=\"opt\">4. \u8a71\u3079\u308b</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u4eca\u65e5\u306f\u5929\u6c17\u304c<u>\u308f\u308b\u3044</u>\u306e\u3067\u3001\u5bb6\u3067<ruby>\u904e<rt>\u3059</rt></ruby>\u3054\u3059\u3053\u3068\u306b\u3057\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena hari ini cuacanya buruk, saya memutuskan untuk menghabiskan waktu di rumah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6b8b\u3044</span>\n      <span class=\"opt\">2. \u4e0d\u3044</span>\n      <span class=\"opt\">3. \u60aa\u3044</span>\n      <span class=\"opt\">4. \u60b2\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u5931\u6557\u3070\u304b\u308a\u3057\u3066\u3044\u308b\u81ea\u5206\u3092<u>\u306a\u3055\u3051\u306a\u304f</u>\u601d\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Saya merasa menyedihkan (malu pada diri sendiri) karena selalu berbuat salah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u60c5\u3051\u306a\u304f</span>\n      <span class=\"opt\">2. \u614e\u3051\u306a\u304f</span>\n      <span class=\"opt\">3. \u5fd9\u3051\u306a\u304f</span>\n      <span class=\"opt\">4. \u60a9\u3051\u306a\u304f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u4eca\u56de\u306e\u30c6\u30b9\u30c8\u306e\u554f\u984c\u306f\u3068\u3066\u3082<u>\u3084\u3055\u3057\u3044</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Soal tes kali ini sangat mudah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u5358\u3057\u3044</span>\n      <span class=\"opt\">2. \u5b89\u3057\u3044</span>\n      <span class=\"opt\">3. \u5bb9\u3057\u3044</span>\n      <span class=\"opt\">4. \u6613\u3057\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u4eca\u65e5\u306f\u3001<u>\u3042\u305f\u305f\u304b\u304f\u3066</u>\u3061\u3087\u3046\u3069\u3044\u3044\u6c17\u6e29\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Hari ini suhunya hangat dan pas sekali.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u71b1\u304b\u304f\u3066</span>\n      <span class=\"opt\">2. \u6696\u304b\u304f\u3066</span>\n      <span class=\"opt\">3. \u6691\u304b\u304f\u3066</span>\n      <span class=\"opt\">4. \u71c3\u304b\u304f\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\">\u6d77\u306f\u3001<u>\u3075\u304b\u304f\u3066</u>\u5730\u306b\u8db3\u304c\u3064\u304b\u306a\u3044\u306e\u3067\u3053\u308f\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Laut itu dalam sehingga kaki tidak menyentuh dasar, jadi menakutkan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6d45\u304f\u3066</span>\n      <span class=\"opt\">2. \u4f4e\u304f\u3066</span>\n      <span class=\"opt\">3. \u6df1\u304f\u3066</span>\n      <span class=\"opt\">4. \u9ad8\u304f\u3066</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 1\u3000\u2461 2\u3000\u2462 4\u3000\u2463 2\u3000\u2464 1\u3000\u2465 3\u3000\u2466 1\u3000\u2467 4\u3000\u2468 2\u3000\u2469 3\n    <div class=\"answer-note\"><strong>Catatan Kanji:</strong> \u2460 \u843d\u3061\u3066 (jatuh/gagal); \u2461 \u9858\u3063\u3066 (berharap/berdoa); \u2462 \u8fce\u3048\u308b (menyambut); \u2463 \u76f4\u3057\u3066 (memperbaiki; bedakan dgn \u6b63\u3057\u3066=meluruskan); \u2464 \u8abf\u3079\u308b (memeriksa); \u2465 \u60aa\u3044 (buruk); \u2466 \u60c5\u3051\u306a\u304f (menyedihkan); \u2467 \u6613\u3057\u3044 (mudah; bedakan dgn \u512a\u3057\u3044=baik hati); \u2468 \u6696\u304b\u304f\u3066 (hangat suhu/cuaca); \u2469 \u6df1\u304f\u3066 (dalam).</div></div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-2-p80\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c2: Set 6 (Kata Sifat-i &amp; Kata Kerja \u00b7 Hal. 77)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c2\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u3092\u6f22\u5b57\u3067\u66f8\u304f\u3068\u304d\u3001\u6700\u3082\u3088\u3044\u3082\u306e\u30921\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah penulisan kanji yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\"><ruby>\u5b6b<rt>\u307e\u3054</rt></ruby>\u306e\u7b11\u9854\u306f\u3001\u3068\u3066\u3082<u>\u3044\u3068\u3057\u3044</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Senyuman cucu sangat menggemaskan (amat disayangi).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u7d20\u3057\u3044</span>\n      <span class=\"opt\">2. \u611b\u3057\u3044</span>\n      <span class=\"opt\">3. \u604b\u3057\u3044</span>\n      <span class=\"opt\">4. \u597d\u3057\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u308f\u304b\u3057\u305f\u3070\u304b\u308a\u306e\u304a\u6e6f\u3067\u5165\u308c\u305f\u304a\u8336\u306f<u>\u3042\u3064\u3044</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Teh yang diseduh dengan air panas yang baru mendidih terasa panas.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u7126\u3044</span>\n      <span class=\"opt\">2. \u7167\u3044</span>\n      <span class=\"opt\">3. \u71c3\u3044</span>\n      <span class=\"opt\">4. \u71b1\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u9577\u3044<ruby>\u8ddd<rt>\u304d\u3087</rt></ruby><ruby>\u96e2<rt>\u308a</rt></ruby>\u3092\u8d70\u308b\u3068\u3001\u3044\u304d\u304c<u>\u304f\u308b\u3057\u304f</u>\u306a\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Jika berlari jarak jauh, napas menjadi sesak (berat).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u5207\u3057\u304f</span>\n      <span class=\"opt\">2. \u8f9b\u3057\u304f</span>\n      <span class=\"opt\">3. \u82e6\u3057\u304f</span>\n      <span class=\"opt\">4. \u547c\u3057\u304f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u4fe1\u53f7\u3092\u898b\u3066<ruby>\u6e21<rt>\u308f\u305f</rt></ruby>\u3089\u306a\u3044\u3068<u>\u3042\u3076\u306a\u3044</u>\u3067\u3059\u3088\u3002</span></div>\n    <div class=\"q-id-trans\">Kalau tidak menyeberang sambil melihat lampu lalu lintas, berbahaya lho.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u5bb3\u306a\u3044</span>\n      <span class=\"opt\">2. \u967a\u306a\u3044</span>\n      <span class=\"opt\">3. \u5371\u306a\u3044</span>\n      <span class=\"opt\">4. \u7591\u306a\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u5f7c\u304b\u3089\u3082\u3089\u3063\u305f\u3086\u3073\u308f\u3092<u>\u306a\u304f\u3057\u3066</u>\u3057\u307e\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya telah menghilangkan cincin yang diberikan olehnya (laki-laki).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u843d\u304f\u3057\u3066</span>\n      <span class=\"opt\">2. \u53bb\u304f\u3057\u3066</span>\n      <span class=\"opt\">3. \u5fd8\u304f\u3057\u3066</span>\n      <span class=\"opt\">4. \u7121\u304f\u3057\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u305d\u308d\u305d\u308d\u3001\u65b0\u3057\u3044\u8eca\u304c<u>\u307b\u3057\u3044</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Sudah saatnya saya menginginkan mobil baru.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6b32\u3057\u3044</span>\n      <span class=\"opt\">2. \u6b27\u3057\u3044</span>\n      <span class=\"opt\">3. \u6b53\u3057\u3044</span>\n      <span class=\"opt\">4. \u6b3a\u3057\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u5f7c\u5973\u306f\u3001\u3044\u3064\u3082<u>\u304b\u308f\u3044\u3089\u3057\u3044</u>\u6d0b\u670d\u3092\u7740\u3066\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Dia (perempuan) selalu memakai pakaian yang manis (imut).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u679c\u611b\u3089\u3057\u3044</span>\n      <span class=\"opt\">2. \u53ef\u611b\u3089\u3057\u3044</span>\n      <span class=\"opt\">3. \u679c\u604b\u3089\u3057\u3044</span>\n      <span class=\"opt\">4. \u53ef\u604b\u3089\u3057\u3044</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u5b9f\u5bb6\u306e<ruby>\u7551<rt>\u306f\u305f\u3051</rt></ruby>\u3067<ruby>\u63a1<rt>\u3068</rt></ruby>\u308c\u308b\u306b\u3093\u3058\u3093\u306f\u3001<u>\u3075\u3068\u304f\u3066</u>\u3042\u307e\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Wortel yang dipanen dari ladang rumah orang tua besar-besar dan manis.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u592b\u304f\u3066</span>\n      <span class=\"opt\">2. \u592a\u304f\u3066</span>\n      <span class=\"opt\">3. \u5927\u304f\u3066</span>\n      <span class=\"opt\">4. \u5929\u304f\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u51ac\u306b\u306a\u308b\u3068\u3001\u5915\u65b9\u306e5\u6642\u306b\u306f\u592a\u967d\u304c\u843d\u3061\u3066<u>\u304f\u3089\u304f</u>\u306a\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Saat musim dingin, jam 5 sore matahari sudah terbenam dan hari menjadi gelap.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6620\u304f</span>\n      <span class=\"opt\">2. \u6669\u304f</span>\n      <span class=\"opt\">3. \u6697\u304f</span>\n      <span class=\"opt\">4. \u662d\u304f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\">\u65e5\u672c\u306f8\u6708\u306e\u521d\u3081\u304c\u4e00\u756a\u6c17\u6e29\u304c\u9ad8\u304f\u3066<u>\u3042\u3064\u3044</u>\u3002</span></div>\n    <div class=\"q-id-trans\">Di Jepang, awal bulan Agustus suhunya paling tinggi dan paling panas.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u66ae\u3044</span>\n      <span class=\"opt\">2. \u6607\u3044</span>\n      <span class=\"opt\">3. \u666f\u3044</span>\n      <span class=\"opt\">4. \u6691\u3044</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 4\u3000\u2462 3\u3000\u2463 3\u3000\u2464 4\u3000\u2465 1\u3000\u2466 2\u3000\u2467 2\u3000\u2468 3\u3000\u2469 4\n    <div class=\"answer-note\"><strong>Catatan Kanji:</strong> \u2460 \u611b\u3057\u3044 (tersayang/menggemaskan; \u604b\u3057\u3044=\u3053\u3044\u3057\u3044); \u2461 \u71b1\u3044 (panas benda/cairan); \u2462 \u82e6\u3057\u304f (sesak/sulit); \u2463 \u5371\u306a\u3044 (berbahaya); \u2464 \u7121\u304f\u3057\u3066 (menghilangkan/kehilangan); \u2465 \u6b32\u3057\u3044 (ingin); \u2466 \u53ef\u611b\u3089\u3057\u3044 (imut/manis); \u2467 \u592a\u304f\u3066 (tebal/besar); \u2468 \u6697\u304f (gelap); \u2469 \u6691\u3044 (panas cuaca).</div></div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-2-p81\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c2: Set 7 (Kata Keterangan / Fukushi \u00b7 Hal. 78)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c2\u3000<u>\u3000\u3000\u3000</u>\u306e\u3053\u3068\u3070\u3092\u6f22\u5b57\u3067\u66f8\u304f\u3068\u304d\u3001\u6700\u3082\u3088\u3044\u3082\u306e\u30921\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah penulisan kanji yang paling tepat untuk kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u3053\u3053\u306e\u30ec\u30b9\u30c8\u30e9\u30f3\u306e\u6599\u7406\u306f\u3001<u>\u3051\u3063\u3053\u3046</u>\u304a\u3044\u3057\u304b\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Masakan di restoran ini lumayan (cukup) enak.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6c7a\u69cb</span>\n      <span class=\"opt\">2. \u6c7a\u8b1b</span>\n      <span class=\"opt\">3. \u7d50\u8b1b</span>\n      <span class=\"opt\">4. \u7d50\u69cb</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u307f\u3093\u306a\u306e\u3053\u3068\u306f<u>\u3051\u3063\u3057\u3066</u>\u5fd8\u308c\u307e\u305b\u3093\u3002</span></div>\n    <div class=\"q-id-trans\">Saya sekali-kali tidak akan melupakan kalian semua.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u5fc5\u3057\u3066</span>\n      <span class=\"opt\">2. \u65ad\u3057\u3066</span>\n      <span class=\"opt\">3. \u6c7a\u3057\u3066</span>\n      <span class=\"opt\">4. \u78ba\u3057\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u65b0\u3057\u304f\u767a\u58f2\u3057\u305f\u5546\u54c1\u304c<u>\u3064\u304e\u3064\u304e</u>\u306b\u58f2\u308c\u3066\u3044\u304f\u3002</span></div>\n    <div class=\"q-id-trans\">Produk yang baru dirilis terjual satu demi satu (berturut-turut).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u6b21\u3005</span>\n      <span class=\"opt\">2. \u6b20\u3005</span>\n      <span class=\"opt\">3. \u6b3d\u3005</span>\n      <span class=\"opt\">4. \u6b32\u3005</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u5931\u3063\u3066<u>\u306f\u3058\u3081\u3066</u>\u6c17\u3065\u304f\u3053\u3068\u304c\u3042\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Ada hal yang baru disadari untuk pertama kalinya setelah kehilangan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u7d42\u3081\u3066</span>\n      <span class=\"opt\">2. \u65b0\u3081\u3066</span>\n      <span class=\"opt\">3. \u521d\u3081\u3066</span>\n      <span class=\"opt\">4. \u7d50\u3081\u3066</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u554f\u984c\u306e\u610f\u5473\u304c<u>\u307e\u3063\u305f\u304f</u>\u308f\u304b\u3089\u306a\u304b\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya sama sekali tidak mengerti maksud soalnya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u7d50\u304f</span>\n      <span class=\"opt\">2. \u5168\u304f</span>\n      <span class=\"opt\">3. \u5b8c\u304f</span>\n      <span class=\"opt\">4. \u8a73\u304f</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u3042\u306e\u5f7c\u304c\u6ce3\u304f\u306e\u3060\u304b\u3089\u3001<u>\u305d\u3046\u3068\u3046</u>\u3046\u308c\u3057\u304b\u3063\u305f\u306e\u3060\u308d\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Sampai dia menangis seperti itu, pasti sangat senang sekali.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u76f8\u7b54</span>\n      <span class=\"opt\">2. \u60f3\u7b54</span>\n      <span class=\"opt\">3. \u76f8\u5f53</span>\n      <span class=\"opt\">4. \u60f3\u5f53</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\"><u>\u305f\u3068\u3048\u3070</u>\u3001\u30e9\u30fc\u30e1\u30f3\u3084\u3059\u3057\u3092\u98df\u3079\u305f\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Misalnya, saya ingin makan ramen atau sushi.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u4f34\u3048\u3070</span>\n      <span class=\"opt\">2. \u4f3c\u3048\u3070</span>\n      <span class=\"opt\">3. \u4fc3\u3048\u3070</span>\n      <span class=\"opt\">4. \u4f8b\u3048\u3070</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u5f7c\u5973\u3092<u>\u304b\u306a\u3089\u305a</u>\u5e78\u305b\u306b\u3059\u308b\u3068\u7d04\u675f\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya berjanji pasti akan membahagiakannya (perempuan).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u5fdc\u305a</span>\n      <span class=\"opt\">2. \u6065\u305a</span>\n      <span class=\"opt\">3. \u5fc5\u305a</span>\n      <span class=\"opt\">4. \u5fc3\u305a</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\"><ruby>\u6cb9<rt>\u3042\u3076\u3089</rt></ruby>\u304c\u591a\u3044\u6599\u7406\u306f\u3001<u>\u3044\u3061\u3069\u306b</u>\u98df\u3079\u308b\u3053\u3068\u304c\u3067\u304d\u306a\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Makanan yang banyak minyak tidak bisa dimakan sekaligus.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u4e00\u5e8f\u306b</span>\n      <span class=\"opt\">2. \u4e00\u5ea6\u306b</span>\n      <span class=\"opt\">3. \u4e00\u5eab\u306b</span>\n      <span class=\"opt\">4. \u4e00\u5eb7\u306b</span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">10</span> <span class=\"q-text\"><u>\u305f\u3057\u304b</u>\u3053\u3053\u306e\u30b9\u30fc\u30d1\u30fc\u306f\u6bce\u670829\u65e5\u306b\u304a\u8089\u304c\u5b89\u304f\u306a\u308b\u306f\u305a\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Kalau tidak salah, di supermarket ini setiap tanggal 29 daging menjadi murah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u7834\u304b</span>\n      <span class=\"opt\">2. \u7814\u304b</span>\n      <span class=\"opt\">3. \u78ba\u304b</span>\n      <span class=\"opt\">4. \u786c\u304b</span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 4\u3000\u2461 3\u3000\u2462 1\u3000\u2463 3\u3000\u2464 2\u3000\u2465 3\u3000\u2466 4\u3000\u2467 3\u3000\u2468 2\u3000\u2469 3\n    <div class=\"answer-note\"><strong>Catatan Kanji:</strong> \u2460 \u7d50\u69cb (lumayan/cukup); \u2461 \u6c7a\u3057\u3066 (sekali-kali tidak); \u2462 \u6b21\u3005 (berturut-turut); \u2463 \u521d\u3081\u3066 (pertama kali); \u2464 \u5168\u304f (sama sekali tidak); \u2465 \u76f8\u5f53 (sangat/cukup); \u2466 \u4f8b\u3048\u3070 (misalnya); \u2467 \u5fc5\u305a (pasti); \u2468 \u4e00\u5ea6\u306b (sekaligus); \u2469 \u78ba\u304b (kalau tidak salah).</div></div>\n</div>\n\n</div><!-- /#mondai-2 -->\n\n\n\n<div class=\"mondai-section\" id=\"mondai-3\">\n\n  <h3>\u554f\u984c3\u3000\u6587\u8108\u898f\u5b9a: Konteks Kalimat</h3>\n\n  <div class=\"example-box\">\n\n    <h4>\u3007 Contoh Soal \u554f\u984c3 (\u554f\u984c3 \u4f8b \u00b7 Hal. 79)</h4>\n\n    <div class=\"q-instruction\">\n\n      <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n\n      <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n\n    </div>\n\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u5f37\u3044\u98a8\u3067\u843d\u3061\u305f\u685c\u306e\u82b1\u304c\u5ddd\u306e\u4e0a\u306b\uff08\u3000\u3000\u3000\uff09\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Bunga sakura yang gugur tertiup angin kencang mengapung di atas sungai.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u88ab<rt>\u304b\u3076</rt></ruby>\u3063\u3066 <small>(memakai di kepala / tertutupi)</small></span>\n      <span class=\"opt\">2. <ruby>\u5012<rt>\u305f\u304a</rt></ruby>\u308c\u3066 <small>(tumbang / roboh)</small></span>\n      <span class=\"opt\">3. <ruby>\u6eb6<rt>\u3068</rt></ruby>\u3051\u3066 <small>(meleleh / larut)</small></span>\n      <span class=\"opt\">4. <ruby>\u6d6e<rt>\u3046</rt></ruby>\u3044\u3066 <small>(mengapung)</small></span>\n    </div>\n  </div>\n\n    <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> 4</div>\n\n  </div>\n\n\n\n  <div class=\"strategy-box\">\n\n    <h4>Strategi &amp; Tips \u554f\u984c3 (Konteks Kalimat)</h4>\n\n    <p class=\"jp-quote\"><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>3\u3067\u306f\u3001\uff08\u3000\u3000\u3000\uff09\u306e<ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u306b\u3074\u3063\u305f\u308a<ruby>\u5f53<rt>\u3042</rt></ruby>\u3066\u306f\u307e\u308b<ruby>\u8a00<rt>\u3053\u3068</rt></ruby><ruby>\u8449<rt>\u3070</rt></ruby>\u3092<ruby>\u9078<rt>\u3048\u3089</rt></ruby>\u3076<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u304c11<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u30024\u3064\u306e<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\u306f<ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby>\u304c<ruby>\u4f3c<rt>\u306b</rt></ruby>\u3066\u3044\u308b<ruby>\u8a00<rt>\u3053\u3068</rt></ruby><ruby>\u8449<rt>\u3070</rt></ruby>\u306b\u306a\u3063\u3066\u3044\u308b\u3053\u3068\u304c<ruby>\u591a<rt>\u304a\u304a</rt></ruby>\u3044\u3067\u3059\u3002<ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby><ruby>\u4e00<rt>\u3072\u3068</rt></ruby>\u3064<ruby>\u4e00<rt>\u3072\u3068</rt></ruby>\u3064\u306e<ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby>\u3092\u3057\u3063\u304b\u308a\u3068<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3057\u3066\u304a\u304d\u307e\u3057\u3087\u3046\u3002</p>\n\n    <p>Pada <strong>Mondai 3</strong>, akan keluar <strong>11 soal</strong> yang meminta Anda memilih kata yang paling pas untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09. Keempat pilihan jawabannya sering kali merupakan kata-kata yang artinya mirip atau berdekatan. Oleh karena itu, pahami dengan baik arti dan nuansa penggunaan masing-masing kosakata satu per satu.</p>\n\n  </div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p83\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 1 (Kata Benda 1 \u00b7 Hal. 80)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u590f\u4f11\u307f\u306e<ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby><ruby>\u8ab2<rt>\u304b</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u3067\u306f\u3001<ruby>\u7f8e<rt>\u3073</rt></ruby><ruby>\u8853<rt>\u3058\u3085\u3064</rt></ruby><ruby>\u9928<rt>\u304b\u3093</rt></ruby>\u3078\u884c\u3063\u305f\uff08\u3000\u3000\u3000\uff09\u3092\u66f8\u3044\u3066<ruby>\u63d0<rt>\u3066\u3044</rt></ruby><ruby>\u51fa<rt>\u3057\u3085\u3064</rt></ruby>\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Pada tugas bebas liburan musim panas, saya menulis kesan setelah pergi ke museum seni lalu mengumpulkannya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u76f8<rt>\u305d\u3046</rt></ruby><ruby>\u8ac7<rt>\u3060\u3093</rt></ruby> <small>(konsultasi / diskusi)</small></span>\n      <span class=\"opt\">2. <ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u6a19<rt>\u3072\u3087\u3046</rt></ruby> <small>(target / tujuan)</small></span>\n      <span class=\"opt\">3. <ruby>\u89e3<rt>\u304b\u3044</rt></ruby><ruby>\u8aac<rt>\u305b\u3064</rt></ruby> <small>(penjelasan / ulasan)</small></span>\n      <span class=\"opt\">4. <ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u60f3<rt>\u305d\u3046</rt></ruby> <small>(kesan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u6700\u8fd1\u5e30\u308a\u304c<ruby>\u9045<rt>\u304a\u305d</rt></ruby>\u3044\u7236\u306f\u3001\u306a\u3093\u3060\u304b<ruby>\u75b2<rt>\u3064\u304b</rt></ruby>\u308c\u3066\u3044\u308b\uff08\u3000\u3000\u3000\uff09\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Ayah yang akhir-akhir ini pulangnya larut, entah mengapa tampak kelelahan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u69d8<rt>\u3088\u3046</rt></ruby><ruby>\u5b50<rt>\u3059</rt></ruby> <small>(keadaan / tampak)</small></span>\n      <span class=\"opt\">2. <ruby>\u4f53<rt>\u305f\u3044</rt></ruby><ruby>\u64cd<rt>\u305d\u3046</rt></ruby> <small>(senam)</small></span>\n      <span class=\"opt\">3. <ruby>\u5408<rt>\u3042\u3044</rt></ruby><ruby>\u56f3<rt>\u305a</rt></ruby> <small>(isyarat / tanda)</small></span>\n      <span class=\"opt\">4. <ruby>\u8abf<rt>\u3061\u3087\u3046</rt></ruby><ruby>\u5b50<rt>\u3057</rt></ruby> <small>(kondisi)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u30d0\u30ca\u30ca\u306b\u306f\u3001\u3055\u307e\u3056\u307e\u306a\uff08\u3000\u3000\u3000\uff09\u304c\u3042\u308b\u305f\u3081\u3001\u6bce\u65e5\u98df\u3079\u308b\u3068\u3044\u3044\u305d\u3046\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Pisang memiliki beragam nutrisi, sehingga katanya baik dimakan setiap hari.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6280<rt>\u304e</rt></ruby><ruby>\u8853<rt>\u3058\u3085\u3064</rt></ruby> <small>(teknologi / keahlian)</small></span>\n      <span class=\"opt\">2. <ruby>\u7814<rt>\u3051\u3093</rt></ruby><ruby>\u7a76<rt>\u304d\u3085\u3046</rt></ruby> <small>(penelitian)</small></span>\n      <span class=\"opt\">3. <ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby> <small>(nutrisi / gizi)</small></span>\n      <span class=\"opt\">4. <ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6e90<rt>\u3052\u3093</rt></ruby> <small>(sumber daya)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u97f3\u697d\u304c\u597d\u304d\u306a\u7236\u306f\u3001\u697d\u5668\u306b\u3064\u3044\u3066\u306e\uff08\u3000\u3000\u3000\uff09\u304c\u3042\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Ayah yang menyukai musik memiliki pengetahuan mengenai alat musik.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u8b58<rt>\u3057\u304d</rt></ruby> <small>(kesadaran)</small></span>\n      <span class=\"opt\">2. <ruby>\u77e5<rt>\u3061</rt></ruby><ruby>\u8b58<rt>\u3057\u304d</rt></ruby> <small>(pengetahuan)</small></span>\n      <span class=\"opt\">3. <ruby>\u4e2d<rt>\u306a\u304b</rt></ruby><ruby>\u8eab<rt>\u307f</rt></ruby> <small>(isi / bagian dalam)</small></span>\n      <span class=\"opt\">4. <ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby> <small>(isi / konten)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\uff08\u3000\u3000\u3000\uff09\u3070\u304b\u308a\u8a00\u3063\u3066\u306a\u3044\u3067\u3001\u5c11\u3057\u306f<ruby>\u9811<rt>\u304c\u3093</rt></ruby><ruby>\u5f35<rt>\u3070</rt></ruby>\u3063\u3066\u307f\u3088\u3046\u3088\u3002</span></div>\n    <div class=\"q-id-trans\">Jangan hanya mengeluh terus, ayo coba berusaha sedikit!</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u8a00<rt>\u3053\u3068</rt></ruby><ruby>\u8449<rt>\u3070</rt></ruby> <small>(kata / ucapan)</small></span>\n      <span class=\"opt\">2. <ruby>\u6587<rt>\u3082\u3093</rt></ruby><ruby>\u53e5<rt>\u304f</rt></ruby> <small>(keluhan / gerutu)</small></span>\n      <span class=\"opt\">3. <ruby>\u79d8<rt>\u3072</rt></ruby><ruby>\u5bc6<rt>\u307f\u3064</rt></ruby> <small>(rahasia)</small></span>\n      <span class=\"opt\">4. <ruby>\u8a00<rt>\u3052\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby> <small>(bahasa)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u4eca\u56de\u306e\u8a66\u5408\u3067\u8ca0\u3051\u305f\u306e\u306f\u3001\u96c6\u4e2d\u529b\u304c\u5207\u308c\u305f\u4e8b\u304c\uff08\u3000\u3000\u3000\uff09\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Penyebab kekalahan dalam pertandingan kali ini adalah hilangnya konsentrasi.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u57fa<rt>\u304d</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby> <small>(dasar)</small></span>\n      <span class=\"opt\">2. <ruby>\u539f<rt>\u3052\u3093</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby> <small>(bahan mentah)</small></span>\n      <span class=\"opt\">3. <ruby>\u6750<rt>\u3056\u3044</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby> <small>(bahan)</small></span>\n      <span class=\"opt\">4. <ruby>\u539f<rt>\u3052\u3093</rt></ruby><ruby>\u56e0<rt>\u3044\u3093</rt></ruby> <small>(penyebab)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u521d\u3081\u3066\u6d77\u5916\u3078\u884c\u3063\u305f\u3068\u304d\u304b\u3089\u3001\u3044\u308d\u3093\u306a\u56fd\u306e\u6587\u5316\u306b\uff08\u3000\u3000\u3000\uff09\u3092\u6301\u3064\u3088\u3046\u306b\u306a\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Sejak pertama kali pergi ke luar negeri, saya mulai memiliki ketertarikan pada budaya berbagai negara.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5f79<rt>\u3084\u304f</rt></ruby><ruby>\u5272<rt>\u308f\u308a</rt></ruby> <small>(peran)</small></span>\n      <span class=\"opt\">2. <ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby> <small>(alasan)</small></span>\n      <span class=\"opt\">3. <ruby>\u8208<rt>\u304d\u3087\u3046</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby> <small>(minat / ketertarikan)</small></span>\n      <span class=\"opt\">4. <ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(tujuan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u4eca\u65e5\u306f\uff08\u3000\u3000\u3000\uff09\u304c\u60aa\u3044\u306e\u3067\u3001\u307e\u305f\u4eca\u5ea6<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b\u3054\u98ef\u3092\u98df\u3079\u306b\u3044\u304d\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Karena hari ini saya sedang tidak bisa (ada keperluan), lain kali saja kita pergi makan bersama.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6027<rt>\u305b\u3044</rt></ruby><ruby>\u683c<rt>\u304b\u304f</rt></ruby> <small>(kepribadian)</small></span>\n      <span class=\"opt\">2. <ruby>\u59ff<rt>\u3057</rt></ruby><ruby>\u52e2<rt>\u305b\u3044</rt></ruby> <small>(postur / sikap)</small></span>\n      <span class=\"opt\">3. <ruby>\u90fd<rt>\u3064</rt></ruby><ruby>\u5408<rt>\u3054\u3046</rt></ruby> <small>(keadaan / jadwal)</small></span>\n      <span class=\"opt\">4. <ruby>\u5370<rt>\u3044\u3093</rt></ruby><ruby>\u8c61<rt>\u3057\u3087\u3046</rt></ruby> <small>(kesan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\"><ruby>\u51fa<rt>\u3057\u3085\u3063</rt></ruby><ruby>\u5f35<rt>\u3061\u3087\u3046</rt></ruby><ruby>\u5148<rt>\u3055\u304d</rt></ruby>\u3067\u305f\u304f\u3055\u3093\u306e\u4eba\u3068\uff08\u3000\u3000\u3000\uff09\u3092<ruby>\u4ea4<rt>\u3053\u3046</rt></ruby><ruby>\u63db<rt>\u304b\u3093</rt></ruby>\u3057\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Di tempat dinas luar kota saya bertukar kartu nama dengan banyak orang.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u540d<rt>\u3081\u3044</rt></ruby><ruby>\u523a<rt>\u3057</rt></ruby> <small>(kartu nama)</small></span>\n      <span class=\"opt\">2. <ruby>\u770b<rt>\u304b\u3093</rt></ruby><ruby>\u677f<rt>\u3070\u3093</rt></ruby> <small>(papan reklame / papan nama)</small></span>\n      <span class=\"opt\">3. <ruby>\u6c0f<rt>\u3057</rt></ruby><ruby>\u540d<rt>\u3081\u3044</rt></ruby> <small>(nama lengkap)</small></span>\n      <span class=\"opt\">4. <ruby>\u4f01<rt>\u304d</rt></ruby><ruby>\u696d<rt>\u304e\u3087\u3046</rt></ruby> <small>(perusahaan)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 4\u3000\u2461 1\u3000\u2462 3\u3000\u2463 2\u3000\u2464 2\u3000\u2465 4\u3000\u2466 3\u3000\u2467 3\u3000\u2468 1</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p84\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 2 (Kata Benda 2 \u00b7 Hal. 81)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u308f\u305f\u3057\u306e\u50cd\u3044\u3066\u3044\u308b\u670d\u5c4b\u306f\u30014\u670810\u65e5\u304b\u308917\u65e5\u306e\uff08\u3000\u3000\u3000\uff09\u3067\u30bb\u30fc\u30eb\u3092\u884c\u3046\u4e88\u5b9a\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Toko pakaian tempat saya bekerja berencana mengadakan obral selama periode tanggal 10 sampai 17 April.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u671f<rt>\u304d</rt></ruby><ruby>\u9650<rt>\u3052\u3093</rt></ruby> <small>(batas waktu / tenggat)</small></span>\n      <span class=\"opt\">2. <ruby>\u671f<rt>\u304d</rt></ruby><ruby>\u9593<rt>\u304b\u3093</rt></ruby> <small>(periode / jangka waktu)</small></span>\n      <span class=\"opt\">3. <ruby>\u5ef6<rt>\u3048\u3093</rt></ruby><ruby>\u671f<rt>\u304d</rt></ruby> <small>(penundaan)</small></span>\n      <span class=\"opt\">4. <ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u6642<rt>\u3058</rt></ruby> <small>(waktu yang sama)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u30c6\u30b9\u30c8\u306e\u70b9\u304c\u3088\u304b\u3063\u305f\u306e\u3067\uff08\u3000\u3000\u3000\uff09\u304c\u4e0a\u304c\u308a\u3001\u6bcd\u306b<ruby>\u8912<rt>\u307b</rt></ruby>\u3081\u3089\u308c\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena nilai tesnya bagus, nilai prestasi saya naik dan saya dipuji oleh ibu.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u9032<rt>\u3057\u3093</rt></ruby><ruby>\u5b66<rt>\u304c\u304f</rt></ruby> <small>(melanjutkan sekolah)</small></span>\n      <span class=\"opt\">2. <ruby>\u6210<rt>\u305b\u3044</rt></ruby><ruby>\u529f<rt>\u3053\u3046</rt></ruby> <small>(keberhasilan / sukses)</small></span>\n      <span class=\"opt\">3. <ruby>\u6210<rt>\u305b\u3044</rt></ruby><ruby>\u7e3e<rt>\u305b\u304d</rt></ruby> <small>(nilai / prestasi)</small></span>\n      <span class=\"opt\">4. <ruby>\u9032<rt>\u3057\u3093</rt></ruby><ruby>\u6b69<rt>\u307d</rt></ruby> <small>(kemajuan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u30c0\u30f3\u30b9\u306e\uff08\u3000\u3000\u3000\uff09\u3092\u5b66\u3073\u306b\u3001\u30a2\u30e1\u30ea\u30ab\u3078\u7559\u5b66\u3059\u308b\u3053\u3068\u306b\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya memutuskan untuk belajar ke luar negeri ke Amerika guna mempelajari dasar-dasar tari.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby> <small>(jawaban benar)</small></span>\n      <span class=\"opt\">2. <ruby>\u57fa<rt>\u304d</rt></ruby><ruby>\u790e<rt>\u305d</rt></ruby> <small>(dasar / fondasi)</small></span>\n      <span class=\"opt\">3. <ruby>\u4e2d<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u5fc3<rt>\u3057\u3093</rt></ruby> <small>(pusat)</small></span>\n      <span class=\"opt\">4. <ruby>\u898b<rt>\u307f</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby> <small>(contoh / sampel)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u6c34\u3068\u96fb\u6c17\u306e\u4f7f\u3044\u3059\u304e\u306b\u6ce8\u610f\u3057\u3001\uff08\u3000\u3000\u3000\uff09\u306b\u512a\u3057\u3044\u751f\u6d3b\u3092\u3057\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Mari kita berhati-hati agar tidak berlebihan memakai air dan listrik, serta menjalani hidup yang ramah terhadap lingkungan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5927<rt>\u304a\u304a</rt></ruby><ruby>\u5bb6<rt>\u3084</rt></ruby> <small>(pemilik kos / tuan tanah)</small></span>\n      <span class=\"opt\">2. <ruby>\u5b63<rt>\u304d</rt></ruby><ruby>\u7bc0<rt>\u305b\u3064</rt></ruby> <small>(musim)</small></span>\n      <span class=\"opt\">3. <ruby>\u74b0<rt>\u304b\u3093</rt></ruby><ruby>\u5883<rt>\u304d\u3087\u3046</rt></ruby> <small>(lingkungan)</small></span>\n      <span class=\"opt\">4. <ruby>\u76f8<rt>\u3042\u3044</rt></ruby><ruby>\u624b<rt>\u3066</rt></ruby> <small>(lawan bicara / pihak lain)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">17\u6642\u307e\u3067\u306b\u3001\u660e\u5f8c\u65e5\u306e<ruby>\u8b1b<rt>\u3053\u3046</rt></ruby><ruby>\u6f14<rt>\u3048\u3093</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u306e\uff08\u3000\u3000\u3000\uff09\u3092\u4f5c\u3089\u306a\u3051\u308c\u3070\u306a\u308a\u307e\u305b\u3093\u3002</span></div>\n    <div class=\"q-id-trans\">Sebelum pukul 17.00, saya harus membuat dokumen untuk acara ceramah lusa.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u66f8<rt>\u3057\u3087</rt></ruby><ruby>\u985e<rt>\u308b\u3044</rt></ruby> <small>(dokumen / berkas)</small></span>\n      <span class=\"opt\">2. <ruby>\u8f9e<rt>\u3058</rt></ruby><ruby>\u66f8<rt>\u3057\u3087</rt></ruby> <small>(kamus)</small></span>\n      <span class=\"opt\">3. <ruby>\u5370<rt>\u3044\u3093</rt></ruby><ruby>\u5237<rt>\u3055\u3064</rt></ruby> <small>(pencetakan)</small></span>\n      <span class=\"opt\">4. <ruby>\u8a18<rt>\u304d</rt></ruby><ruby>\u9332<rt>\u308d\u304f</rt></ruby> <small>(catatan / rekaman)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\"><ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u7236<rt>\u3075</rt></ruby>\u306e\u5b50\u3069\u3082\u306e\uff08\u3000\u3000\u3000\uff09\u306f\u3001\u30a2\u30a4\u30b9\u30af\u30ea\u30fc\u30e0\u304c10\u5186\u3067\u8cb7\u3048\u305f\u305d\u3046\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Konon pada zaman kakek masih kecil, es krim bisa dibeli seharga 10 yen.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u90fd<rt>\u3068</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby> <small>(kota besar)</small></span>\n      <span class=\"opt\">2. <ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby> <small>(dunia)</small></span>\n      <span class=\"opt\">3. <ruby>\u793e<rt>\u3057\u3083</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby> <small>(masyarakat)</small></span>\n      <span class=\"opt\">4. <ruby>\u6642<rt>\u3058</rt></ruby><ruby>\u4ee3<rt>\u3060\u3044</rt></ruby> <small>(zaman / masa)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u308f\u305f\u3057\u306f\u3001\u82f1\u8a9e\u3092\u8a71\u3059\u3053\u3068\u3088\u308a\u3082\u8aad\u3080\u3053\u3068\u306e\u65b9\u304c\uff08\u3000\u3000\u3000\uff09\u304c\u3042\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Saya lebih memiliki rasa percaya diri dalam membaca bahasa Inggris daripada berbicara bahasa Inggris.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u4fe1<rt>\u3057\u3093</rt></ruby> <small>(kepercayaan diri)</small></span>\n      <span class=\"opt\">2. <ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby> <small>(indera / perasaan)</small></span>\n      <span class=\"opt\">3. <ruby>\u52b9<rt>\u3053\u3046</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby> <small>(efek / dampak)</small></span>\n      <span class=\"opt\">4. <ruby>\u7279<rt>\u3068\u304f</rt></ruby><ruby>\u5fb4<rt>\u3061\u3087\u3046</rt></ruby> <small>(ciri khas)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u8eca\u306b\u4e57\u3063\u3066\u3001\u5bb6\u304b\u3089\u5b66\u6821\u307e\u3067\u306e\uff08\u3000\u3000\u3000\uff09\u3092\u78ba\u304b\u3081\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Naik mobil untuk memastikan jarak dari rumah ke sekolah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6642<rt>\u3058</rt></ruby><ruby>\u5dee<rt>\u3055</rt></ruby> <small>(perbedaan waktu)</small></span>\n      <span class=\"opt\">2. <ruby>\u9593<rt>\u304b\u3093</rt></ruby><ruby>\u9694<rt>\u304b\u304f</rt></ruby> <small>(interval / selang)</small></span>\n      <span class=\"opt\">3. <ruby>\u6210<rt>\u305b\u3044</rt></ruby><ruby>\u9577<rt>\u3061\u3087\u3046</rt></ruby> <small>(pertumbuhan)</small></span>\n      <span class=\"opt\">4. <ruby>\u8ddd<rt>\u304d\u3087</rt></ruby><ruby>\u96e2<rt>\u308a</rt></ruby> <small>(jarak)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u308f\u305f\u3057\u304c\u4f4f\u3093\u3067\u3044\u308b\u30a2\u30d1\u30fc\u30c8\u306e\uff08\u3000\u3000\u3000\uff09\u306f\u6bce\u67087\u4e07\u5186\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Biaya sewa apartemen yang saya tinggali adalah 70.000 yen per bulan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u73fe<rt>\u3052\u3093</rt></ruby><ruby>\u91d1<rt>\u304d\u3093</rt></ruby> <small>(uang tunai)</small></span>\n      <span class=\"opt\">2. <ruby>\u5bb6<rt>\u3084</rt></ruby><ruby>\u8cc3<rt>\u3061\u3093</rt></ruby> <small>(biaya sewa rumah)</small></span>\n      <span class=\"opt\">3. <ruby>\u7d66<rt>\u304d\u3085\u3046</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby> <small>(gaji)</small></span>\n      <span class=\"opt\">4. <ruby>\u7269<rt>\u3076\u3063</rt></ruby><ruby>\u4fa1<rt>\u304b</rt></ruby> <small>(harga barang)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 3\u3000\u2462 2\u3000\u2463 3\u3000\u2464 1\u3000\u2465 4\u3000\u2466 1\u3000\u2467 4\u3000\u2468 2</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p85\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 3 (Kata Kerja Suru 1 \u00b7 Hal. 82)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u4eca\u65e5\u306e\u8a66\u5408\u306b\u52dd\u3063\u3066\u3001\u512a\u52dd\u3059\u308b\u3053\u3068\u3092\uff08\u3000\u3000\u3000\uff09\u3057\u3066\u3044\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Saya berharap dapat memenangkan pertandingan hari ini dan menjadi juara.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u7528<rt>\u3088\u3046</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby> <small>(persiapan)</small></span>\n      <span class=\"opt\">2. <ruby>\u671f<rt>\u304d</rt></ruby><ruby>\u5f85<rt>\u305f\u3044</rt></ruby> <small>(harapan / menantikan)</small></span>\n      <span class=\"opt\">3. <ruby>\u4e88<rt>\u3088</rt></ruby><ruby>\u7d04<rt>\u3084\u304f</rt></ruby> <small>(reservasi)</small></span>\n      <span class=\"opt\">4. <ruby>\u89e3<rt>\u304b\u3044</rt></ruby><ruby>\u6c7a<rt>\u3051\u3064</rt></ruby> <small>(penyelesaian)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\"><ruby>\u5c06<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u6765<rt>\u3089\u3044</rt></ruby>\u306f\u3001\u82f1\u8a9e\u3092\uff08\u3000\u3000\u3000\uff09\u3059\u308b\u4ed5\u4e8b\u3067\u4e16\u754c\u4e2d\u3092\u56de\u308a\u305f\u3044\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Di masa depan, saya ingin berkeliling dunia dengan pekerjaan menerjemahkan (menjadi juru bahasa) bahasa Inggris.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5171<rt>\u304d\u3087\u3046</rt></ruby><ruby>\u901a<rt>\u3064\u3046</rt></ruby> <small>(kesamaan / umum)</small></span>\n      <span class=\"opt\">2. <ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby> <small>(arti / makna)</small></span>\n      <span class=\"opt\">3. <ruby>\u901a<rt>\u3064\u3046</rt></ruby><ruby>\u8a33<rt>\u3084\u304f</rt></ruby> <small>(penerjemahan lisan)</small></span>\n      <span class=\"opt\">4. <ruby>\u4f1d<rt>\u3067\u3093</rt></ruby><ruby>\u8a00<rt>\u3054\u3093</rt></ruby> <small>(pesan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u5f7c\u306f\u3001\u30c6\u30b9\u30c8\u3067\u3044\u3044\u70b9\u3092\u3068\u3063\u305f\u3053\u3068\u3092\u307f\u3093\u306a\u306b\uff08\u3000\u3000\u3000\uff09\u3057\u3066\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Dia (laki-laki) membanggakan kepada semua orang bahwa ia mendapat nilai bagus dalam tes.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u7533<rt>\u3057\u3093</rt></ruby><ruby>\u8acb<rt>\u305b\u3044</rt></ruby> <small>(pengajuan / permohonan)</small></span>\n      <span class=\"opt\">2. <ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u898b<rt>\u3051\u3093</rt></ruby> <small>(pendapat)</small></span>\n      <span class=\"opt\">3. <ruby>\u5ba3<rt>\u305b\u3093</rt></ruby><ruby>\u4f1d<rt>\u3067\u3093</rt></ruby> <small>(promosi / iklan)</small></span>\n      <span class=\"opt\">4. <ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u6162<rt>\u307e\u3093</rt></ruby> <small>(membanggakan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u6700\u8fd1\u592a\u3063\u3066\u304d\u305f\u306e\u3067\u3001\u6bce\u65e5\uff08\u3000\u3000\u3000\uff09\u3059\u308b\u305f\u3081\u306b\u65b0\u3057\u3044<ruby>\u9774<rt>\u304f\u3064</rt></ruby>\u3092\u8cb7\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena akhir-akhir ini berat badan bertambah, saya membeli sepatu baru untuk berolahraga setiap hari.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u904b<rt>\u3046\u3093</rt></ruby><ruby>\u52d5<rt>\u3069\u3046</rt></ruby> <small>(olahraga)</small></span>\n      <span class=\"opt\">2. <ruby>\u5b9f<rt>\u3058\u3063</rt></ruby><ruby>\u9a13<rt>\u3051\u3093</rt></ruby> <small>(eksperimen)</small></span>\n      <span class=\"opt\">3. <ruby>\u79fb<rt>\u3044</rt></ruby><ruby>\u52d5<rt>\u3069\u3046</rt></ruby> <small>(berpindah)</small></span>\n      <span class=\"opt\">4. <ruby>\u5b9f<rt>\u3058\u3063</rt></ruby><ruby>\u884c<rt>\u3053\u3046</rt></ruby> <small>(pelaksanaan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\"><ruby>\u4fee<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u5b66<rt>\u304c\u304f</rt></ruby><ruby>\u65c5<rt>\u308a\u3087</rt></ruby><ruby>\u884c<rt>\u3053\u3046</rt></ruby>\u3067\u3001\u6709\u540d\u306a\u30d1\u30f3\u5de5\u5834\u3092\uff08\u3000\u3000\u3000\uff09\u3059\u308b\u4e88\u5b9a\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Pada karyawisata sekolah, kami berencana mengunjungi (meninjau) pabrik roti yang terkenal.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6559<rt>\u304d\u3087\u3046</rt></ruby><ruby>\u80b2<rt>\u3044\u304f</rt></ruby> <small>(pendidikan)</small></span>\n      <span class=\"opt\">2. <ruby>\u898b<rt>\u3051\u3093</rt></ruby><ruby>\u5b66<rt>\u304c\u304f</rt></ruby> <small>(kunjungan studi / meninjau)</small></span>\n      <span class=\"opt\">3. <ruby>\u767a<rt>\u306f\u3063</rt></ruby><ruby>\u898b<rt>\u3051\u3093</rt></ruby> <small>(penemuan)</small></span>\n      <span class=\"opt\">4. <ruby>\u5c31<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u8077<rt>\u3057\u3087\u304f</rt></ruby> <small>(mendapat pekerjaan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\"><ruby>\u7530<rt>\u305f</rt></ruby><ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u3055\u3093\u306e<ruby>\u8a95<rt>\u305f\u3093</rt></ruby><ruby>\u751f<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u65e5<rt>\u3073</rt></ruby>\u30d1\u30fc\u30c6\u30a3\u30fc\u3092\u3053\u3063\u305d\u308a\uff08\u3000\u3000\u3000\uff09\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Merencanakan pesta ulang tahun Tanaka-san secara diam-diam.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby> <small>(merawat / mengurus)</small></span>\n      <span class=\"opt\">2. <ruby>\u7d4c<rt>\u3051\u3044</rt></ruby><ruby>\u55b6<rt>\u3048\u3044</rt></ruby> <small>(mengelola bisnis)</small></span>\n      <span class=\"opt\">3. <ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby> <small>(hubungan)</small></span>\n      <span class=\"opt\">4. <ruby>\u8a08<rt>\u3051\u3044</rt></ruby><ruby>\u753b<rt>\u304b\u304f</rt></ruby> <small>(merencanakan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u4eca\u56de\u306e<ruby>\u5bbf<rt>\u3057\u3085\u304f</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u306f\u3001\u5bb6\u3067\u690d\u7269\u306e\u6210\u9577\u3092\uff08\u3000\u3000\u3000\uff09\u3057\u3066\u8a18\u9332\u3059\u308b\u3053\u3068\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">PR kali ini adalah mengamati dan mencatat pertumbuhan tanaman di rumah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u8a3c<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u660e<rt>\u3081\u3044</rt></ruby> <small>(membuktikan)</small></span>\n      <span class=\"opt\">2. <ruby>\u8a18<rt>\u304d</rt></ruby><ruby>\u5ff5<rt>\u306d\u3093</rt></ruby> <small>(peringatan / kenangan)</small></span>\n      <span class=\"opt\">3. <ruby>\u89b3<rt>\u304b\u3093</rt></ruby><ruby>\u5bdf<rt>\u3055\u3064</rt></ruby> <small>(mengamati / observasi)</small></span>\n      <span class=\"opt\">4. <ruby>\u898b<rt>\u3051\u3093</rt></ruby><ruby>\u7269<rt>\u3076\u3064</rt></ruby> <small>(melihat-lihat / tamasya)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u65b0\u5165\u793e\u54e1\u3092\uff08\u3000\u3000\u3000\uff09\u3059\u308b\u4f1a\u304c\u958b\u304b\u308c\u3001\u305f\u304f\u3055\u3093\u304a<ruby>\u9152<rt>\u3055\u3051</rt></ruby>\u3092\u98f2\u3093\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Acara penyambutan karyawan baru diadakan, dan kami banyak minum minuman beralkohol.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u7dad<rt>\u3044</rt></ruby><ruby>\u6301<rt>\u3058</rt></ruby> <small>(mempertahankan)</small></span>\n      <span class=\"opt\">2. <ruby>\u5b89<rt>\u3042\u3093</rt></ruby><ruby>\u5fc3<rt>\u3057\u3093</rt></ruby> <small>(lega / tenang)</small></span>\n      <span class=\"opt\">3. <ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u6fc0<rt>\u3052\u304d</rt></ruby> <small>(terharu)</small></span>\n      <span class=\"opt\">4. <ruby>\u6b53<rt>\u304b\u3093</rt></ruby><ruby>\u8fce<rt>\u3052\u3044</rt></ruby> <small>(menyambut)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u6d77\u306e\u6c34\u3092\uff08\u3000\u3000\u3000\uff09\u3057\u305f\u3068\u3053\u308d\u3001\u6628\u5e74\u3088\u308a\u3082<ruby>\u6c5a<rt>\u3088\u3054</rt></ruby>\u308c\u3066\u3044\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Setelah meneliti (memeriksa) air laut, ternyata lebih kotor dibandingkan tahun lalu.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5de5<rt>\u304f</rt></ruby><ruby>\u592b<rt>\u3075\u3046</rt></ruby> <small>(upaya kreatif / akal)</small></span>\n      <span class=\"opt\">2. <ruby>\u4eee<rt>\u304b</rt></ruby><ruby>\u5b9a<rt>\u3066\u3044</rt></ruby> <small>(asumsi / pengandaian)</small></span>\n      <span class=\"opt\">3. <ruby>\u8abf<rt>\u3061\u3087\u3046</rt></ruby><ruby>\u67fb<rt>\u3055</rt></ruby> <small>(penyelidikan / survei)</small></span>\n      <span class=\"opt\">4. <ruby>\u6307<rt>\u3057</rt></ruby><ruby>\u5b9a<rt>\u3066\u3044</rt></ruby> <small>(penunjukan / penetapan)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 3\u3000\u2462 4\u3000\u2463 1\u3000\u2464 2\u3000\u2465 4\u3000\u2466 3\u3000\u2467 4\u3000\u2468 3</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p86\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 4 (Kata Kerja Suru &amp; Kata Benda \u00b7 Hal. 83)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u3044\u3064\u304b\u65e5\u672c\u306b\u884c\u3063\u305f\u3089\u3001<ruby>\u4eac<rt>\u304d\u3087\u3046</rt></ruby><ruby>\u90fd<rt>\u3068</rt></ruby>\u3068<ruby>\u5927<rt>\u304a\u304a</rt></ruby><ruby>\u962a<rt>\u3055\u304b</rt></ruby>\u3092\uff08\u3000\u3000\u3000\uff09\u3057\u305f\u3044\u3068\u601d\u3063\u3066\u3044\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Jika suatu saat pergi ke Jepang, saya ingin berwisata ke Kyoto dan Osaka.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u4f4d<rt>\u3044</rt></ruby><ruby>\u7f6e<rt>\u3061</rt></ruby> <small>(posisi / letak)</small></span>\n      <span class=\"opt\">2. <ruby>\u96c6<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u4e2d<rt>\u3061\u3085\u3046</rt></ruby> <small>(konsentrasi)</small></span>\n      <span class=\"opt\">3. <ruby>\u89b3<rt>\u304b\u3093</rt></ruby><ruby>\u5149<rt>\u3053\u3046</rt></ruby> <small>(berwisata)</small></span>\n      <span class=\"opt\">4. <ruby>\u5165<rt>\u306b\u3085\u3046</rt></ruby><ruby>\u9580<rt>\u3082\u3093</rt></ruby> <small>(pengantar / pemula)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u50cd\u304f\u4eba\u304c\u8db3\u308a\u306a\u3044\u306e\u3067\u3001\u30a2\u30eb\u30d0\u30a4\u30c8\u3092\uff08\u3000\u3000\u3000\uff09\u3059\u308b\u3053\u3068\u306b\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena kekurangan tenaga kerja, diputuskan untuk merekrut pekerja paruh waktu.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u52df<rt>\u307c</rt></ruby><ruby>\u96c6<rt>\u3057\u3085\u3046</rt></ruby> <small>(perekrutan / lowongan)</small></span>\n      <span class=\"opt\">2. <ruby>\u4ea4<rt>\u3053\u3046</rt></ruby><ruby>\u63db<rt>\u304b\u3093</rt></ruby> <small>(pertukaran)</small></span>\n      <span class=\"opt\">3. <ruby>\u6301<rt>\u3058</rt></ruby><ruby>\u53c2<rt>\u3055\u3093</rt></ruby> <small>(membawa sendiri)</small></span>\n      <span class=\"opt\">4. <ruby>\u56de<rt>\u304b\u3044</rt></ruby><ruby>\u53ce<rt>\u3057\u3085\u3046</rt></ruby> <small>(pengumpulan kembali)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u6628\u65e5\u3001\u5a18\u306e<ruby>\u4fdd<rt>\u307b</rt></ruby><ruby>\u80b2<rt>\u3044\u304f</rt></ruby><ruby>\u5712<rt>\u3048\u3093</rt></ruby>\u3092\uff08\u3000\u3000\u3000\uff09\u3057\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Kemarin saya mengunjungi taman penitipan anak (hoikuen) milik putri saya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u901a<rt>\u3064\u3046</rt></ruby><ruby>\u884c<rt>\u3053\u3046</rt></ruby> <small>(melintas / lalu lintas)</small></span>\n      <span class=\"opt\">2. <ruby>\u8a2a<rt>\u307b\u3046</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby> <small>(mengunjungi)</small></span>\n      <span class=\"opt\">3. <ruby>\u958b<rt>\u304b\u3044</rt></ruby><ruby>\u5712<rt>\u3048\u3093</rt></ruby> <small>(pembukaan taman)</small></span>\n      <span class=\"opt\">4. <ruby>\u53d7<rt>\u3058\u3085</rt></ruby><ruby>\u9a13<rt>\u3051\u3093</rt></ruby> <small>(mengikuti ujian)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><ruby>\u6df7<rt>\u3053\u3093</rt></ruby><ruby>\u96d1<rt>\u3056\u3064</rt></ruby>\u3092<ruby>\u9632<rt>\u3075\u305b</rt></ruby>\u3050\u305f\u3081\u3001\u5e97\u306b\u5165\u308c\u308b\u4eba\u6570\u3092\uff08\u3000\u3000\u3000\uff09\u3057\u3066\u3044\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Untuk mencegah kerumunan, jumlah orang yang boleh masuk ke toko dibatasi.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u4e3b<rt>\u3057\u3085</rt></ruby><ruby>\u5f35<rt>\u3061\u3087\u3046</rt></ruby> <small>(menegaskan pendapat)</small></span>\n      <span class=\"opt\">2. <ruby>\u547d<rt>\u3081\u3044</rt></ruby><ruby>\u4ee4<rt>\u308c\u3044</rt></ruby> <small>(perintah)</small></span>\n      <span class=\"opt\">3. <ruby>\u5236<rt>\u305b\u3044</rt></ruby><ruby>\u9650<rt>\u3052\u3093</rt></ruby> <small>(pembatasan)</small></span>\n      <span class=\"opt\">4. <ruby>\u7981<rt>\u304d\u3093</rt></ruby><ruby>\u6b62<rt>\u3057</rt></ruby> <small>(pelarangan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u3053\u3093\u306a\u306b\u58f2\u308c\u308b\u306a\u3093\u3066\u3001\uff08\u3000\u3000\u3000\uff09\u3057\u3066\u3044\u307e\u305b\u3093\u3067\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya sama sekali tidak menyangka (memperkirakan) akan laku sebanyak ini.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u4e88<rt>\u3088</rt></ruby><ruby>\u5831<rt>\u307b\u3046</rt></ruby> <small>(prakiraan)</small></span>\n      <span class=\"opt\">2. <ruby>\u6ce8<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby> <small>(perhatian)</small></span>\n      <span class=\"opt\">3. <ruby>\u7d04<rt>\u3084\u304f</rt></ruby><ruby>\u675f<rt>\u305d\u304f</rt></ruby> <small>(janji)</small></span>\n      <span class=\"opt\">4. <ruby>\u4e88<rt>\u3088</rt></ruby><ruby>\u60f3<rt>\u305d\u3046</rt></ruby> <small>(perkiraan / dugaan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u9053\u3067<ruby>\u8ff7<rt>\u307e\u3088</rt></ruby>\u3063\u3066\u3044\u308b\u4eba\u3092\u3001\u99c5\u307e\u3067\uff08\u3000\u3000\u3000\uff09\u3057\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya memandu (mengantar) orang yang tersesat di jalan sampai ke stasiun.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6307<rt>\u3057</rt></ruby><ruby>\u5c0e<rt>\u3069\u3046</rt></ruby> <small>(bimbingan)</small></span>\n      <span class=\"opt\">2. <ruby>\u6848<rt>\u3042\u3093</rt></ruby><ruby>\u5185<rt>\u306a\u3044</rt></ruby> <small>(memandu / mengantar)</small></span>\n      <span class=\"opt\">3. <ruby>\u53d7<rt>\u3046\u3051</rt></ruby><ruby>\u4ed8<rt>\u3064\u3051</rt></ruby> <small>(penerimaan / resepsionis)</small></span>\n      <span class=\"opt\">4. <ruby>\u7d39<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u4ecb<rt>\u304b\u3044</rt></ruby> <small>(perkenalan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\"><ruby>\u5c71<rt>\u3084\u307e</rt></ruby><ruby>\u7530<rt>\u3060</rt></ruby>\u3055\u3093\u306f\u4eca\u6708\u3067\u4f1a\u793e\u3092<ruby>\u8f9e<rt>\u3084</rt></ruby>\u3081\u3066\u3001\u30a2\u30e1\u30ea\u30ab\u3078\u7559\u5b66\u3059\u308b\u3068\u3044\u3046\uff08\u3000\u3000\u3000\uff09\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Ada rumor (kabar burung) bahwa Yamada-san akan berhenti dari perusahaan bulan ini dan kuliah ke Amerika.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u901a<rt>\u3068\u304a</rt></ruby>\u308a <small>(jalan / sesuai)</small></span>\n      <span class=\"opt\">2. <ruby>\u6271<rt>\u3042\u3064\u304b</rt></ruby>\u3044 <small>(perlakuan)</small></span>\n      <span class=\"opt\">3. \u3046\u308f\u3055 <small>(rumor / desas-desus)</small></span>\n      <span class=\"opt\">4. \u3046\u305d <small>(kebohongan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u6628\u65e5\u3001\u53cb\u4eba\u3068\uff08\u3000\u3000\u3000\uff09\u3057\u3066\u3057\u307e\u3044\u3001\u6c17\u5206\u304c\u60aa\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Kemarin saya bertengkar dengan teman, sehingga suasana hati saya buruk.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6e1b<rt>\u3052\u3093</rt></ruby><ruby>\u5c11<rt>\u3057\u3087\u3046</rt></ruby> <small>(pengurangan)</small></span>\n      <span class=\"opt\">2. \u306a\u3063\u3068\u304f <small>(puas / mengerti)</small></span>\n      <span class=\"opt\">3. <ruby>\u6d88<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u8cbb<rt>\u3072</rt></ruby> <small>(konsumsi)</small></span>\n      <span class=\"opt\">4. \u3051\u3093\u304b <small>(bertengkar)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u5de5\u5834\u3067\uff08\u3000\u3000\u3000\uff09\u3057\u305f\u304a\u8089\u3092\u3001\u30b9\u30fc\u30d1\u30fc\u3067\u58f2\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Menjual daging yang telah diolah di pabrik di supermarket.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5909<rt>\u3078\u3093</rt></ruby><ruby>\u5316<rt>\u304b</rt></ruby> <small>(perubahan)</small></span>\n      <span class=\"opt\">2. <ruby>\u52a0<rt>\u304b</rt></ruby><ruby>\u5de5<rt>\u3053\u3046</rt></ruby> <small>(pengolahan / pemrosesan)</small></span>\n      <span class=\"opt\">3. <ruby>\u8abf<rt>\u3061\u3087\u3046</rt></ruby><ruby>\u7bc0<rt>\u305b\u3064</rt></ruby> <small>(penyetelan / penyesuaian)</small></span>\n      <span class=\"opt\">4. <ruby>\u5fdc<rt>\u304a\u3046</rt></ruby><ruby>\u7528<rt>\u3088\u3046</rt></ruby> <small>(penerapan)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\u3000\u2461 1\u3000\u2462 2\u3000\u2463 3\u3000\u2464 4\u3000\u2465 2\u3000\u2466 3\u3000\u2467 4\u3000\u2468 2</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p87\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 5 (Kata Kerja 1 \u00b7 Hal. 84)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\"><ruby>\u9774<rt>\u304f\u3064</rt></ruby>\u3072\u3082\u3092\u3057\u3063\u304b\u308a\uff08\u3000\u3000\u3000\uff09\u304b\u3089\u6b69\u304d\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Mari kita berjalan setelah mengikat tali sepatu dengan kencang.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3064\u3064\u3093\u3067 <small>(membungkus)</small></span>\n      <span class=\"opt\">2. <ruby>\u7d44<rt>\u304f</rt></ruby>\u3093\u3067 <small>(menyusun / menyilangkan)</small></span>\n      <span class=\"opt\">3. <ruby>\u7d50<rt>\u3080\u3059</rt></ruby>\u3093\u3067 <small>(mengikat)</small></span>\n      <span class=\"opt\">4. \u305f\u305f\u3093\u3067 <small>(melipat)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u53cb\u4eba\u304c\u6025\u306b\u5927\u304d\u306a\u58f0\u3092\u51fa\u3057\u305f\u306e\u3067\u3001\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Karena teman tiba-tiba bersuara keras, saya terkejut.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3042\u3053\u304c\u308c\u305f <small>(mengagumi / mendambakan)</small></span>\n      <span class=\"opt\">2. \u304a\u3069\u308d\u3044\u305f <small>(terkejut / kaget)</small></span>\n      <span class=\"opt\">3. \u304f\u305f\u3073\u308c\u305f <small>(kelelahan)</small></span>\n      <span class=\"opt\">4. \u3042\u304d\u3089\u3081\u305f <small>(menyerah)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\"><ruby>\u968e<rt>\u304b\u3044</rt></ruby><ruby>\u6bb5<rt>\u3060\u3093</rt></ruby>\u304b\u3089\u843d\u3061\u3066\u3001\u304b\u3051\u3066\u3044\u305f\u30e1\u30ac\u30cd\u304c\uff08\u3000\u3000\u3000\uff09\u3057\u307e\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena jatuh dari tangga, kacamata yang saya pakai jadi bengkok.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u8ee2<rt>\u3053\u308d</rt></ruby>\u3093\u3067 <small>(terjatuh / terguling)</small></span>\n      <span class=\"opt\">2. <ruby>\u623b<rt>\u3082\u3069</rt></ruby>\u3063\u3066 <small>(kembali)</small></span>\n      <span class=\"opt\">3. <ruby>\u66f2<rt>\u307e</rt></ruby>\u304c\u3063\u3066 <small>(bengkok / melengkung)</small></span>\n      <span class=\"opt\">4. <ruby>\u964d<rt>\u3075</rt></ruby>\u3063\u3066 <small>(turun (hujan/salju))</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u6d77\u3092\u6b69\u3044\u3066\u3044\u305f\u3089\u3001\u5927\u304d\u3044\u8c9d\u3092\uff08\u3000\u3000\u3000\uff09\u3051\u304c\u3092\u3057\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saat berjalan di pantai, saya menginjak kerang besar lalu terluka.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304a\u3055\u3048\u3066 <small>(menahan / menekan)</small></span>\n      <span class=\"opt\">2. \u3075\u3093\u3067 <small>(menginjak)</small></span>\n      <span class=\"opt\">3. \u3046\u3063\u3066 <small>(memukul / mengetuk)</small></span>\n      <span class=\"opt\">4. \u307b\u3063\u3066 <small>(menggali)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u6700\u8fd1\u306f\u3001\u671d\u304b\u3089\u591c\u307e\u3067\u4e88\u5b9a\u304c\uff08\u3000\u3000\u3000\uff09\u3044\u3066<ruby>\u5fd9<rt>\u3044\u305d\u304c</rt></ruby>\u3057\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Akhir-akhir ini jadwal terisi penuh dari pagi sampai malam sehingga sibuk.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u307e\u3068\u307e\u3063\u3066 <small>(terangkum / rapi)</small></span>\n      <span class=\"opt\">2. \u305f\u307e\u3063\u3066 <small>(menumpuk)</small></span>\n      <span class=\"opt\">3. <ruby>\u6b8b<rt>\u306e\u3053</rt></ruby>\u3063\u3066 <small>(tersisa)</small></span>\n      <span class=\"opt\">4. <ruby>\u57cb<rt>\u3046</rt></ruby>\u307e\u3063\u3066 <small>(terisi penuh)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\"><ruby>\u5098<rt>\u304b\u3055</rt></ruby>\u3092\u4e8c\u672c\u6301\u3063\u3066\u3044\u305f\u306e\u3067\u3001<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u306b\u5927\u304d\u3044\u65b9\u3092\uff08\u3000\u3000\u3000\uff09\u3042\u3052\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena membawa dua payung, saya meminjamkan yang lebih besar kepada teman.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u639b<rt>\u304b</rt></ruby>\u3051\u3066 <small>(menggantungkan / memakai)</small></span>\n      <span class=\"opt\">2. <ruby>\u6301<rt>\u3082</rt></ruby>\u3063\u3066 <small>(membawa / memegang)</small></span>\n      <span class=\"opt\">3. <ruby>\u8cb8<rt>\u304b</rt></ruby>\u3057\u3066 <small>(meminjamkan)</small></span>\n      <span class=\"opt\">4. <ruby>\u6271<rt>\u3042\u3064\u304b</rt></ruby>\u3063\u3066 <small>(memperlakukan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\"><ruby>\u5148<rt>\u305b\u3093</rt></ruby><ruby>\u8f29<rt>\u3071\u3044</rt></ruby>\u304b\u3089\u591c\u3054\u98ef\u306b<ruby>\u8a98<rt>\u3055\u305d</rt></ruby>\u308f\u308c\u305f\u304c\u3001\u660e\u65e5\u306f\u65e9\u304f\u8d77\u304d\u306a\u3051\u308c\u3070\u3044\u3051\u306a\u3044\u306e\u3067\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Saya diajak makan malam oleh senior, tetapi karena besok harus bangun pagi, saya menolaknya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3042\u3084\u307e\u3063\u305f <small>(meminta maaf)</small></span>\n      <span class=\"opt\">2. <ruby>\u65ad<rt>\u3053\u3068\u308f</rt></ruby>\u3063\u305f <small>(menolak)</small></span>\n      <span class=\"opt\">3. <ruby>\u9006<rt>\u3055\u304b</rt></ruby>\u3089\u3063\u305f <small>(melawan / membangkang)</small></span>\n      <span class=\"opt\">4. \u305f\u3057\u304b\u3081\u305f <small>(memastikan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u6628\u65e5\u306e\u5f37\u3044\u53f0\u98a8\u3067\u3001\u5927\u304d\u306a\u6728\u304c\uff08\u3000\u3000\u3000\uff09\u3057\u307e\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Akibat topan kencang kemarin, pohon besar tumbang.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5012<rt>\u305f\u304a</rt></ruby>\u308c\u3066 <small>(tumbang / roboh)</small></span>\n      <span class=\"opt\">2. <ruby>\u964d<rt>\u3075</rt></ruby>\u3063\u3066 <small>(turun (hujan/salju))</small></span>\n      <span class=\"opt\">3. <ruby>\u751f<rt>\u306f</rt></ruby>\u3048\u3066 <small>(tumbuh)</small></span>\n      <span class=\"opt\">4. <ruby>\u5f15<rt>\u3072</rt></ruby>\u3044\u3066 <small>(menarik)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u9280\u884c\u306b\u884c\u3063\u3066\u3001\u4eca\u6708\u306e<ruby>\u5bb6<rt>\u3084</rt></ruby><ruby>\u8cc3<rt>\u3061\u3093</rt></ruby>\u3068\u96fb\u6c17\u4ee3\u3092\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Pergi ke bank untuk membayar uang sewa rumah dan tagihan listrik bulan ini.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u983c<rt>\u305f\u306e</rt></ruby>\u3080 <small>(meminta / memesan)</small></span>\n      <span class=\"opt\">2. <ruby>\u6255<rt>\u306f\u3089</rt></ruby>\u3046 <small>(membayar)</small></span>\n      <span class=\"opt\">3. <ruby>\u6e21<rt>\u308f\u305f</rt></ruby>\u3059 <small>(menyerahkan)</small></span>\n      <span class=\"opt\">4. <ruby>\u4f1d<rt>\u3064\u305f</rt></ruby>\u3048\u308b <small>(menyampaikan)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\u3000\u2461 2\u3000\u2462 3\u3000\u2463 2\u3000\u2464 4\u3000\u2465 3\u3000\u2466 2\u3000\u2467 1\u3000\u2468 2</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p88\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 6 (Kata Kerja 2 \u00b7 Hal. 85)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u30d0\u30b9\u30b1\u30c3\u30c8\u30dc\u30fc\u30eb\u306e\u8a66\u5408\u3067\u8ca0\u3051\u3066\u3057\u307e\u3063\u305f\u53cb\u4eba\u3092\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Menghibur teman yang kalah dalam pertandingan bola basket.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u624b<rt>\u3066</rt></ruby><ruby>\u4f1d<rt>\u3064\u3060</rt></ruby>\u3046 <small>(membantu)</small></span>\n      <span class=\"opt\">2. \u305f\u3088\u308b <small>(mengandalkan)</small></span>\n      <span class=\"opt\">3. <ruby>\u6cbb<rt>\u306a\u304a</rt></ruby>\u3059 <small>(menyembuhkan)</small></span>\n      <span class=\"opt\">4. \u306a\u3050\u3055\u3081\u308b <small>(menghibur)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u5ddd\u3067\uff08\u3000\u3000\u3000\uff09\u5b50\u72ac\u3092\u52a9\u3051\u3066\u3001\u75c5\u9662\u306b\u9023\u308c\u3066\u884c\u304d\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya menolong anak anjing yang hampir tenggelam di sungai, lalu membawanya ke rumah sakit.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u63fa<rt>\u3086</rt></ruby>\u308c\u3066\u3044\u305f <small>(bergoyang)</small></span>\n      <span class=\"opt\">2. \u3042\u3075\u308c\u3066\u3044\u305f <small>(meluap)</small></span>\n      <span class=\"opt\">3. \u304a\u307c\u308c\u3066\u3044\u305f <small>(tenggelam (gelagapan di air))</small></span>\n      <span class=\"opt\">4. <ruby>\u6c88<rt>\u3057\u305a</rt></ruby>\u3093\u3067\u3044\u305f <small>(tenggelam ke dasar)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u305d\u3063\u3068<ruby>\u9589<rt>\u3057</rt></ruby>\u3081\u306a\u3044\u3068\u3001\u30c9\u30a2\u304c\uff08\u3000\u3000\u3000\uff09\u3057\u307e\u3044\u307e\u3059\u3088\u3002</span></div>\n    <div class=\"q-id-trans\">Kalau tidak ditutup pelan-pelan, pintunya nanti rusak lho.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u98fd<rt>\u3042</rt></ruby>\u304d\u3066 <small>(bosan)</small></span>\n      <span class=\"opt\">2. <ruby>\u75b2<rt>\u3064\u304b</rt></ruby>\u308c\u3066 <small>(lelah)</small></span>\n      <span class=\"opt\">3. <ruby>\u58ca<rt>\u3053\u308f</rt></ruby>\u308c\u3066 <small>(rusak)</small></span>\n      <span class=\"opt\">4. <ruby>\u6eb6<rt>\u3068</rt></ruby>\u3051\u3066 <small>(meleleh)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u307f\u3093\u306a<ruby>\u75b2<rt>\u3064\u304b</rt></ruby>\u308c\u3066\u3044\u308b<ruby>\u69d8<rt>\u3088\u3046</rt></ruby><ruby>\u5b50<rt>\u3059</rt></ruby>\u3060\u3063\u305f\u306e\u3067\u3001\u793e\u54e1\u5168\u54e1\u306b3\u65e5\u9593\u306e\u4f11\u65e5\u3092\uff08\u3000\u3000\u3000\uff09\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena semuanya tampak kelelahan, perusahaan memberikan libur selama 3 hari kepada seluruh karyawan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u4e0e<rt>\u3042\u305f</rt></ruby>\u3048 <small>(memberikan)</small></span>\n      <span class=\"opt\">2. <ruby>\u6e21<rt>\u308f\u305f</rt></ruby>\u3057 <small>(menyerahkan)</small></span>\n      <span class=\"opt\">3. <ruby>\u914d<rt>\u304f\u3070</rt></ruby>\u308a <small>(membagikan)</small></span>\n      <span class=\"opt\">4. <ruby>\u7f6e<rt>\u304a</rt></ruby>\u304d <small>(meletakkan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\"><ruby>\u6c5a<rt>\u3088\u3054</rt></ruby>\u308c\u3066\u3044\u308b\u673a\u3092\uff08\u3000\u3000\u3000\uff09\u304d\u308c\u3044\u306b\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Mengelap meja yang kotor hingga menjadi bersih.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3057\u307c\u3063\u3066 <small>(memeras)</small></span>\n      <span class=\"opt\">2. <ruby>\u62ed<rt>\u3075</rt></ruby>\u3044\u3066 <small>(mengelap)</small></span>\n      <span class=\"opt\">3. \u305f\u305f\u3044\u3066 <small>(mengetuk / memukul)</small></span>\n      <span class=\"opt\">4. <ruby>\u5f3e<rt>\u3072</rt></ruby>\u3044\u3066 <small>(memetik / memainkan musik)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u8fd1\u304f\u306b\u3042\u3063\u305f<ruby>\u4ea4<rt>\u3053\u3046</rt></ruby><ruby>\u756a<rt>\u3070\u3093</rt></ruby>\u3067\u99c5\u307e\u3067\u306e\u9053\u3092\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Saya menanyakan jalan menuju stasiun di pos polisi yang ada di dekat situ.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u958b<rt>\u3072\u3089</rt></ruby>\u3044\u305f <small>(membuka)</small></span>\n      <span class=\"opt\">2. <ruby>\u52e7<rt>\u3059\u3059</rt></ruby>\u3081\u305f <small>(menyarankan / menawarkan)</small></span>\n      <span class=\"opt\">3. <ruby>\u9078<rt>\u3048\u3089</rt></ruby>\u3093\u3060 <small>(memilih)</small></span>\n      <span class=\"opt\">4. <ruby>\u5c0b<rt>\u305f\u305a</rt></ruby>\u306d\u305f <small>(bertanya / menanyakan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u5b66\u6821\u306e\u6388\u696d\u3067\u3001\u82f1\u8a9e\u3092\uff08\u3000\u3000\u3000\uff09\u7df4\u7fd2\u3092\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Di pelajaran sekolah, melakukan latihan menyimak (menangkap pendengaran) bahasa Inggris.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u805e<rt>\u304d</rt></ruby>\u304d<ruby>\u53d6<rt>\u3068</rt></ruby>\u308b <small>(menangkap pendengaran / menyimak)</small></span>\n      <span class=\"opt\">2. <ruby>\u53d7<rt>\u3046</rt></ruby>\u3051<ruby>\u53d6<rt>\u3068</rt></ruby>\u308b <small>(menerima)</small></span>\n      <span class=\"opt\">3. \u3075\u304d<ruby>\u53d6<rt>\u3068</rt></ruby>\u308b <small>(mengelap bersih)</small></span>\n      <span class=\"opt\">4. \u304d\u308a<ruby>\u53d6<rt>\u3068</rt></ruby>\u308b <small>(menggunting / memotong)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u30ab\u30ec\u30f3\u30c0\u30fc\u3092\u898b\u3066\u3001\u4eca\u591c\u306e\u5927\u4e8b\u306a\u4e88\u5b9a\u3092\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Setelah melihat kalender, saya teringat kembali jadwal penting malam ini.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u4f5c<rt>\u3064\u304f</rt></ruby>\u308a<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057\u305f <small>(menciptakan)</small></span>\n      <span class=\"opt\">2. <ruby>\u5f15<rt>\u3072</rt></ruby>\u304d<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057\u305f <small>(menarik keluar)</small></span>\n      <span class=\"opt\">3. <ruby>\u8cb8<rt>\u304b</rt></ruby>\u3057<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057\u305f <small>(meminjamkan keluar)</small></span>\n      <span class=\"opt\">4. <ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3044<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057\u305f <small>(teringat)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u5165\u5b66\u5f0f\u3067\u3001\u751f\u5f92\u3092\u4ee3\u8868\u3057\u3066\u304a\u795d\u3044\u306e\u8a00\u8449\u3092\u8a00\u3046<ruby>\u5f79<rt>\u3084\u304f</rt></ruby><ruby>\u5272<rt>\u308f\u308a</rt></ruby>\u3092\uff08\u3000\u3000\u3000\uff09\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Pada upacara penerimaan siswa baru, saya menerima (mengemban) peran menyampaikan kata sambutan selamat mewakili para siswa.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5f15<rt>\u3072</rt></ruby>\u3063<ruby>\u5f35<rt>\u3071</rt></ruby>\u308a <small>(menarik paksa)</small></span>\n      <span class=\"opt\">2. <ruby>\u53d6<rt>\u3068</rt></ruby>\u308a<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057 <small>(mengambil keluar)</small></span>\n      <span class=\"opt\">3. <ruby>\u5f15<rt>\u3072</rt></ruby>\u304d<ruby>\u53d7<rt>\u3046</rt></ruby>\u3051 <small>(menerima / mengemban)</small></span>\n      <span class=\"opt\">4. <ruby>\u53d6<rt>\u3068</rt></ruby>\u308a<ruby>\u8fbc<rt>\u3053</rt></ruby>\u307f <small>(memasukkan / sibuk)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 4\u3000\u2461 3\u3000\u2462 3\u3000\u2463 1\u3000\u2464 2\u3000\u2465 4\u3000\u2466 1\u3000\u2467 4\u3000\u2468 3</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p89\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 7 (Kata Kerja Majemuk \u00b7 Hal. 86)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u9031\u672b\u306f\u3001\u65b0\u3057\u304f\u8cb7\u3063\u305f\u30ed\u30dc\u30c3\u30c8\u3092\uff08\u3000\u3000\u3000\uff09\u3001<ruby>\u606f\u5b50<rt>\u3080\u3059\u3053</rt></ruby>\u3068<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b<ruby>\u904a<rt>\u3042\u305d</rt></ruby>\u3076\u4e88\u5b9a\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Akhir pekan ini saya berencana merakit robot yang baru dibeli, lalu bermain bersama putra saya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u639b<rt>\u304b</rt></ruby>\u3051<ruby>\u76f4<rt>\u306a\u304a</rt></ruby>\u3057\u3066 <small>(menelepon balik)</small></span>\n      <span class=\"opt\">2. <ruby>\u7d44<rt>\u304f</rt></ruby>\u307f<ruby>\u7acb<rt>\u305f</rt></ruby>\u3066\u3066 <small>(merakit)</small></span>\n      <span class=\"opt\">3. <ruby>\u5207<rt>\u304d</rt></ruby>\u308a<ruby>\u66ff<rt>\u304b</rt></ruby>\u3048\u3066 <small>(mengalihkan / mengganti)</small></span>\n      <span class=\"opt\">4. <ruby>\u898b<rt>\u307f</rt></ruby>\u3066<ruby>\u56de<rt>\u307e\u308f</rt></ruby>\u3063\u3066 <small>(berkeliling melihat)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u601d\u3063\u305f\u3088\u308a\u3082<ruby>\u5fdc<rt>\u304a\u3046</rt></ruby><ruby>\u52df<rt>\u307c</rt></ruby><ruby>\u8005<rt>\u3057\u3083</rt></ruby>\u304c\u591a\u304b\u3063\u305f\u306e\u3067\u3001\u660e\u65e5\u3067\uff08\u3000\u3000\u3000\uff09\u3053\u3068\u306b\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena jumlah pelamar lebih banyak dari yang diduga, diputuskan untuk menutup pendaftaran besok.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u98f2<rt>\u306e</rt></ruby>\u307f<ruby>\u5207<rt>\u304d</rt></ruby>\u308b <small>(menghabiskan minuman)</small></span>\n      <span class=\"opt\">2. <ruby>\u8a00<rt>\u3044</rt></ruby>\u3044<ruby>\u5207<rt>\u304d</rt></ruby>\u308b <small>(mengatakan tegas)</small></span>\n      <span class=\"opt\">3. <ruby>\u8d70<rt>\u306f\u3057</rt></ruby>\u308a<ruby>\u5207<rt>\u304d</rt></ruby>\u308b <small>(berlari hingga akhir)</small></span>\n      <span class=\"opt\">4. <ruby>\u7de0<rt>\u3057</rt></ruby>\u3081<ruby>\u5207<rt>\u304d</rt></ruby>\u308b <small>(menutup pendaftaran / tenggat)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">7\u6708\u306e\u65c5\u884c\u306b\u3064\u3044\u3066\u3001\u672c\u3084\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u3067\u8abf\u3079\u306a\u304c\u3089\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Berdiskusi mengenai perjalanan bulan Juli sambil mencarinya di buku dan internet.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5411<rt>\u3080</rt></ruby>\u304b\u3044<ruby>\u5408<rt>\u3042</rt></ruby>\u3046 <small>(saling berhadapan)</small></span>\n      <span class=\"opt\">2. <ruby>\u8a71<rt>\u306f\u306a</rt></ruby>\u3057<ruby>\u5408<rt>\u3042</rt></ruby>\u3046 <small>(berdiskusi / bermusyawarah)</small></span>\n      <span class=\"opt\">3. <ruby>\u898b<rt>\u307f</rt></ruby>\u3064\u3081<ruby>\u5408<rt>\u3042</rt></ruby>\u3046 <small>(saling menatap)</small></span>\n      <span class=\"opt\">4. <ruby>\u639b<rt>\u304b</rt></ruby>\u3051<ruby>\u5408<rt>\u3042</rt></ruby>\u3046 <small>(bernegosiasi)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><ruby>\u8ca1<rt>\u3055\u3044</rt></ruby><ruby>\u5e03<rt>\u3075</rt></ruby>\u3068<ruby>\u643a<rt>\u3051\u3044</rt></ruby><ruby>\u5e2f<rt>\u305f\u3044</rt></ruby><ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u3060\u3051\u306f\u3001\u3044\u3064\u3082\uff08\u3000\u3000\u3000\uff09\u3088\u3046\u306b\u3057\u3066\u3044\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Saya selalu berusaha membawa dompet dan telepon genggam saja ke mana-mana.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5f85<rt>\u307e</rt></ruby>\u3061<ruby>\u7d9a<rt>\u3064\u3065</rt></ruby>\u3051\u308b <small>(terus menunggu)</small></span>\n      <span class=\"opt\">2. <ruby>\u6301<rt>\u3082</rt></ruby>\u3061<ruby>\u66ff<rt>\u304b</rt></ruby>\u3048\u308b <small>(memindahkan pegangan)</small></span>\n      <span class=\"opt\">3. <ruby>\u5f85<rt>\u307e</rt></ruby>\u3061<ruby>\u5408<rt>\u3042</rt></ruby>\u308f\u305b\u308b <small>(berjanji bertemu)</small></span>\n      <span class=\"opt\">4. <ruby>\u6301<rt>\u3082</rt></ruby>\u3061<ruby>\u6b69<rt>\u3042\u308b</rt></ruby>\u304f <small>(membawa ke mana-mana)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\"><ruby>\u5c71<rt>\u3084\u307e</rt></ruby><ruby>\u672c<rt>\u3082\u3068</rt></ruby>\u3055\u3093\u306a\u3089\u3001\u5148\u9031<ruby>\u5bb6<rt>\u304b</rt></ruby><ruby>\u65cf<rt>\u305e\u304f</rt></ruby>\u3067<ruby>\u6771<rt>\u3068\u3046</rt></ruby><ruby>\u4eac<rt>\u304d\u3087\u3046</rt></ruby>\u306b\uff08\u3000\u3000\u3000\uff09\u307e\u3057\u305f\u3088\u3002</span></div>\n    <div class=\"q-id-trans\">Kalau Yamamoto-san, minggu lalu sudah pindah ke Tokyo bersama keluarganya lho.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5f15<rt>\u3072</rt></ruby>\u3063<ruby>\u639b<rt>\u304b</rt></ruby>\u3051 <small>(tersangkut / mengaitkan)</small></span>\n      <span class=\"opt\">2. <ruby>\u5f15<rt>\u3072</rt></ruby>\u3063<ruby>\u8d8a<rt>\u3053</rt></ruby>\u3057 <small>(pindah rumah)</small></span>\n      <span class=\"opt\">3. <ruby>\u98db<rt>\u3068</rt></ruby>\u3073<ruby>\u8d8a<rt>\u3053</rt></ruby>\u3057 <small>(melompati)</small></span>\n      <span class=\"opt\">4. <ruby>\u99c6<rt>\u304b</rt></ruby>\u3051<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057 <small>(mulai berlari)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u5b66\u6821\u306e\u5148\u751f\u305f\u3061\u304c\u3001\u30a4\u30f3\u30d5\u30eb\u30a8\u30f3\u30b6\u306e<ruby>\u4e88<rt>\u3088</rt></ruby><ruby>\u9632<rt>\u307c\u3046</rt></ruby>\u3092\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Para guru di sekolah mengimbau (menyerukan) pencegahan influenza.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u8a00<rt>\u3044</rt></ruby>\u3044\u304b\u3051\u308b <small>(hampir mengatakan)</small></span>\n      <span class=\"opt\">2. <ruby>\u554f<rt>\u3068</rt></ruby>\u3044\u304b\u3051\u308b <small>(bertanya / menanyai)</small></span>\n      <span class=\"opt\">3. <ruby>\u547c<rt>\u3088</rt></ruby>\u3073\u304b\u3051\u308b <small>(mengimbau / menyerukan)</small></span>\n      <span class=\"opt\">4. <ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3044\u304b\u3051\u308b <small>(mulai terpikir)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\"><ruby>\u4e2d<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u56fd<rt>\u3054\u304f</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092\u52c9\u5f37\u3059\u308b\u305f\u3081\u306b\u3001\u4f1a\u8a71\u306e\u30af\u30e9\u30b9\u306b\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Mendaftar ke kelas percakapan untuk belajar bahasa Mandarin.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u8aad<rt>\u3088</rt></ruby>\u307f<ruby>\u8fbc<rt>\u3053</rt></ruby>\u3080 <small>(membaca mendalam / memuat)</small></span>\n      <span class=\"opt\">2. <ruby>\u547c<rt>\u3088</rt></ruby>\u3073<ruby>\u8fbc<rt>\u3053</rt></ruby>\u3080 <small>(memanggil masuk)</small></span>\n      <span class=\"opt\">3. <ruby>\u66f8<rt>\u304b</rt></ruby>\u304d<ruby>\u8fbc<rt>\u3053</rt></ruby>\u3080 <small>(menulis masuk)</small></span>\n      <span class=\"opt\">4. <ruby>\u7533<rt>\u3082\u3046</rt></ruby>\u3057<ruby>\u8fbc<rt>\u3053</rt></ruby>\u3080 <small>(mendaftar / mengajukan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u3053\u306e\u8cc7\u6599\u306f\u3001\u6700\u521d\u304b\u3089\uff08\u3000\u3000\u3000\uff09\u5fc5\u8981\u304c\u3042\u308a\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Dokumen ini perlu dibuat ulang dari awal.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u4f5c<rt>\u3064\u304f</rt></ruby>\u308a<ruby>\u76f4<rt>\u306a\u304a</rt></ruby>\u3059 <small>(membuat ulang)</small></span>\n      <span class=\"opt\">2. <ruby>\u7e70<rt>\u304f</rt></ruby>\u308a<ruby>\u8fd4<rt>\u304b\u3048</rt></ruby>\u3059 <small>(mengulangi)</small></span>\n      <span class=\"opt\">3. <ruby>\u53d6<rt>\u3068</rt></ruby>\u308a<ruby>\u8fd4<rt>\u304b\u3048</rt></ruby>\u3059 <small>(mengambil kembali)</small></span>\n      <span class=\"opt\">4. <ruby>\u53d6<rt>\u3068</rt></ruby>\u308a<ruby>\u6d88<rt>\u3051</rt></ruby>\u3059 <small>(membatalkan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u5b66\u6821\u306b<ruby>\u9045<rt>\u3061</rt></ruby><ruby>\u523b<rt>\u3053\u304f</rt></ruby>\u3057\u305d\u3046\u3060\u3063\u305f\u306e\u3067\u3001\u96e8\u306e\u4e2d<ruby>\u5098<rt>\u304b\u3055</rt></ruby>\u3092\u5dee\u3055\u305a\u306b\u5bb6\u3092\uff08\u3000\u3000\u3000\uff09\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena hampir terlambat ke sekolah, saya berlari keluar rumah di tengah hujan tanpa memakai payung.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u8ffd<rt>\u304a</rt></ruby>\u3044<ruby>\u8d8a<rt>\u3053</rt></ruby>\u3057 <small>(mendahului / menyalip)</small></span>\n      <span class=\"opt\">2. <ruby>\u639b<rt>\u304b</rt></ruby>\u3051<ruby>\u76f4<rt>\u306a\u304a</rt></ruby>\u3057 <small>(menelepon ulang)</small></span>\n      <span class=\"opt\">3. <ruby>\u98db<rt>\u3068</rt></ruby>\u3073<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057 <small>(berlari keluar mendadak)</small></span>\n      <span class=\"opt\">4. <ruby>\u8d70<rt>\u306f\u3057</rt></ruby>\u308a<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057 <small>(mulai berlari)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 4\u3000\u2462 2\u3000\u2463 4\u3000\u2464 2\u3000\u2465 3\u3000\u2466 4\u3000\u2467 1\u3000\u2468 3</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p90\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 8 (Kata Sifat-i 1 \u00b7 Hal. 87)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u8cb7\u3044\u7269\u306b\u6765\u305f\u306e\u306b\u3001<ruby>\u8ca1<rt>\u3055\u3044</rt></ruby><ruby>\u5e03<rt>\u3075</rt></ruby>\u3092\u5fd8\u308c\u3066\uff08\u3000\u3000\u3000\uff09\u5bb6\u306b\u5e30\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Padahal sudah datang untuk berbelanja, karena lupa membawa dompet saya terpaksa pulang ke rumah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3060\u3089\u3057\u306a\u304f <small>(ceroboh / berantakan)</small></span>\n      <span class=\"opt\">2. <ruby>\u7533<rt>\u3082\u3046</rt></ruby>\u3057<ruby>\u8a33<rt>\u308f\u3051</rt></ruby>\u306a\u304f <small>(merasa bersalah)</small></span>\n      <span class=\"opt\">3. <ruby>\u4ed5<rt>\u3057</rt></ruby><ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u306a\u304f <small>(terpaksa / apa boleh buat)</small></span>\n      <span class=\"opt\">4. \u306b\u304f\u3089\u3057\u304f <small>(menyebalkan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u3075\u308b\u3055\u3068\u304c\uff08\u3000\u3000\u3000\uff09\u3001\u4e45\u3057\u3076\u308a\u306b\u4e2d\u5b66\u306e<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u306b\u96fb\u8a71\u3092\u304b\u3051\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena rindu kampung halaman, setelah sekian lama saya menelepon teman SMP.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u611b<rt>\u3044\u3068</rt></ruby>\u3057\u304f\u3066 <small>(sangat disayangi)</small></span>\n      <span class=\"opt\">2. <ruby>\u512a<rt>\u3084\u3055</rt></ruby>\u3057\u304f\u3066 <small>(baik hati)</small></span>\n      <span class=\"opt\">3. <ruby>\u7f8e<rt>\u3046\u3064\u304f</rt></ruby>\u3057\u304f\u3066 <small>(indah)</small></span>\n      <span class=\"opt\">4. <ruby>\u604b<rt>\u3053\u3044</rt></ruby>\u3057\u304f\u3066 <small>(rindu / kangen)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\"><ruby>\u6728<rt>\u304d</rt></ruby><ruby>\u6751<rt>\u3080\u3089</rt></ruby>\u3055\u3093\u306e\u30d4\u30a2\u30ce\u306e<ruby>\u6f14<rt>\u3048\u3093</rt></ruby><ruby>\u594f<rt>\u305d\u3046</rt></ruby>\u306f\u3001\u3068\u3066\u3082\uff08\u3000\u3000\u3000\uff09\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Permainan piano Kimura-san sangat luar biasa (mengagumkan).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3042\u3084\u3057\u304b\u3063\u305f <small>(mencurigakan)</small></span>\n      <span class=\"opt\">2. \u3059\u3070\u3089\u3057\u304b\u3063\u305f <small>(luar biasa / mengagumkan)</small></span>\n      <span class=\"opt\">3. \u3046\u3089\u3084\u307e\u3057\u304b\u3063\u305f <small>(iri)</small></span>\n      <span class=\"opt\">4. \u304a\u3044\u3057\u304b\u3063\u305f <small>(enak / lezat)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u30ec\u30b9\u30c8\u30e9\u30f3\u306b\u5165\u308b\u3068\u3001\u6614\u3088\u304f\u805e\u3044\u3066\u3044\u305f\u66f2\u304c\u5e97\u5185\u3067\u6d41\u308c\u3066\u3044\u3066\uff08\u3000\u3000\u3000\uff09\u6c17\u6301\u3061\u306b\u306a\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Ketika masuk restoran, lagu yang dulu sering saya dengarkan diputar di dalam toko sehingga timbul perasaan nostalgia.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6065<rt>\u306f</rt></ruby>\u305a\u304b\u3057\u3044 <small>(malu)</small></span>\n      <span class=\"opt\">2. <ruby>\u89aa<rt>\u3057\u305f</rt></ruby>\u3057\u3044 <small>(akrab)</small></span>\n      <span class=\"opt\">3. \u3057\u3087\u3046\u304c\u306a\u3044 <small>(tidak bisa diapa-apakan)</small></span>\n      <span class=\"opt\">4. \u306a\u3064\u304b\u3057\u3044 <small>(nostalgia / terkenang masa lalu)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u53f0\u98a8\u304c\u8fd1\u3065\u3044\u3066\u3044\u308b\u305b\u3044\u3067\u3001\u96e8\u3082\u98a8\u3082\uff08\u3000\u3000\u3000\uff09\u306a\u3063\u3066\u304d\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Gara-gara topan mendekat, hujan maupun angin semakin kencang (parah).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304b\u305f\u304f <small>(keras / kaku)</small></span>\n      <span class=\"opt\">2. <ruby>\u5fd9<rt>\u3044\u305d\u304c</rt></ruby>\u3057\u304f <small>(sibuk)</small></span>\n      <span class=\"opt\">3. \u3072\u3069\u304f <small>(parah / hebat)</small></span>\n      <span class=\"opt\">4. <ruby>\u82e6<rt>\u304f\u308b</rt></ruby>\u3057\u304f <small>(sesak / sulit)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u3053\u306e\u6642\u9593\u306b\u306a\u308b\u3068\u3001\u90e8\u5c4b\u306b\u592a\u967d\u306e\u5149\u304c<ruby>\u5f53<rt>\u3042</rt></ruby>\u305f\u3063\u3066\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Kalau sudah jam segini, cahaya matahari masuk mengenai ruangan sehingga terasa silau.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u307e\u3076\u3057\u3044 <small>(silau)</small></span>\n      <span class=\"opt\">2. \u3082\u3063\u305f\u3044\u306a\u3044 <small>(mubazir / sayang)</small></span>\n      <span class=\"opt\">3. \u3046\u308b\u3055\u3044 <small>(berisik)</small></span>\n      <span class=\"opt\">4. \u306c\u308b\u3044 <small>(suam-suam kuku)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u3053\u3053\u306e\u5ddd\u306f\uff08\u3000\u3000\u3000\uff09\u306e\u3067\u3001\u5c0f\u3055\u3044\u5b50\u3069\u3082\u3082\u5b89\u5fc3\u3057\u3066<ruby>\u904a<rt>\u3042\u305d</rt></ruby>\u3079\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Sungai di sini dangkal, sehingga anak kecil pun bisa bermain dengan tenang (aman).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u8584<rt>\u3046\u3059</rt></ruby>\u3044 <small>(tipis / hambar)</small></span>\n      <span class=\"opt\">2. <ruby>\u8ca7<rt>\u307e\u305a</rt></ruby>\u3057\u3044 <small>(miskin)</small></span>\n      <span class=\"opt\">3. <ruby>\u6d45<rt>\u3042\u3055</rt></ruby>\u3044 <small>(dangkal)</small></span>\n      <span class=\"opt\">4. <ruby>\u8efd<rt>\u304b\u308b</rt></ruby>\u3044 <small>(ringan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u5352\u696d\u3057\u305f\u3089\u3001\u307f\u3093\u306a\u306b\u6bce\u65e5\u4f1a\u3046\u3053\u3068\u304c\u3067\u304d\u306a\u304f\u306a\u308b\u306e\u3067\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Setelah lulus, kita tidak bisa bertemu semua orang setiap hari lagi, jadi terasa kesepian (sedih).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3042\u3076\u306a\u3044 <small>(berbahaya)</small></span>\n      <span class=\"opt\">2. \u304f\u3084\u3057\u3044 <small>(kesal / menyesal)</small></span>\n      <span class=\"opt\">3. \u306a\u3055\u3051\u306a\u3044 <small>(menyedihkan)</small></span>\n      <span class=\"opt\">4. \u3055\u3073\u3057\u3044 <small>(kesepian / sedih)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u4eca\u65e5\u306f\u305f\u304f\u3055\u3093\u98df\u3079\u308b\u4e88\u5b9a\u306a\u306e\u3067\u3001\u304a<ruby>\u8179<rt>\u306a\u304b</rt></ruby>\u306e<ruby>\u5468<rt>\u307e\u308f</rt></ruby>\u308a\u304c\uff08\u3000\u3000\u3000\uff09\u30ba\u30dc\u30f3\u3092<ruby>\u5c65<rt>\u306f</rt></ruby>\u3044\u3066\u304d\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena hari ini berencana makan banyak, saya memakai celana yang bagian pinggangnya (perutnya) longgar.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304d\u3073\u3057\u3044 <small>(ketat / keras)</small></span>\n      <span class=\"opt\">2. \u3084\u3055\u3057\u3044 <small>(baik / mudah)</small></span>\n      <span class=\"opt\">3. \u3086\u308b\u3044 <small>(longgar)</small></span>\n      <span class=\"opt\">4. \u3048\u3089\u3044 <small>(hebat)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\u3000\u2461 4\u3000\u2462 2\u3000\u2463 4\u3000\u2464 3\u3000\u2465 1\u3000\u2466 3\u3000\u2467 4\u3000\u2468 3</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p91\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 9 (Kata Sifat-i &amp; Kata Sifat-na \u00b7 Hal. 88)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\"><ruby>\u5f8c<rt>\u3053\u3046</rt></ruby><ruby>\u8f29<rt>\u306f\u3044</rt></ruby>\u304c\u4f5c\u3063\u3066\u304f\u308c\u305f<ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby>\u306b<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3044\u304c\u306a\u3044\u304b\uff08\u3000\u3000\u3000\uff09\u30c1\u30a7\u30c3\u30af\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Memeriksa dengan teliti (rinci) apakah ada kesalahan pada dokumen yang dibuat oleh junior.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6fc3<rt>\u3053</rt></ruby>\u304f <small>(pekat / kental)</small></span>\n      <span class=\"opt\">2. \u304d\u3064\u304f <small>(ketat / keras)</small></span>\n      <span class=\"opt\">3. <ruby>\u96e3<rt>\u3080\u305a\u304b</rt></ruby>\u3057\u304f <small>(sulit)</small></span>\n      <span class=\"opt\">4. \u3053\u307e\u304b\u304f <small>(teliti / rinci)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u3053\u306e\u30c9\u30e9\u30de\u306f\u304a\u3082\u3057\u308d\u3044\u3068\u805e\u3044\u3066\u3044\u305f\u3051\u3069\u3001<ruby>\u5b9f<rt>\u3058\u3063</rt></ruby><ruby>\u969b<rt>\u3055\u3044</rt></ruby>\u306f\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Saya dengar drama ini menarik, tetapi kenyataannya membosankan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3064\u307e\u3089\u306a\u304b\u3063\u305f <small>(membosankan)</small></span>\n      <span class=\"opt\">2. \u304a\u304b\u3057\u304b\u3063\u305f <small>(aneh / lucu)</small></span>\n      <span class=\"opt\">3. \u3081\u305a\u3089\u3057\u304b\u3063\u305f <small>(langka)</small></span>\n      <span class=\"opt\">4. \u3042\u304b\u308b\u304b\u3063\u305f <small>(terang / ceria)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u304a<ruby>\u83d3<rt>\u304b</rt></ruby><ruby>\u5b50<rt>\u3057</rt></ruby>\u3092\u98df\u3079<ruby>\u904e<rt>\u3059</rt></ruby>\u304e\u305f\u305b\u3044\u3067\u3001\u9854\u304c\uff08\u3000\u3000\u3000\uff09\u306a\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Gara-gara kebanyakan makan camilan, wajah saya menjadi bulat.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u304f <small>(luas)</small></span>\n      <span class=\"opt\">2. <ruby>\u4e38<rt>\u307e\u308b</rt></ruby>\u304f <small>(bulat)</small></span>\n      <span class=\"opt\">3. <ruby>\u72ed<rt>\u305b\u307e</rt></ruby>\u304f <small>(sempit)</small></span>\n      <span class=\"opt\">4. <ruby>\u539a<rt>\u3042\u3064</rt></ruby>\u304f <small>(tebal)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u3044\u3064\u3082<ruby>\u771f<rt>\u307e</rt></ruby><ruby>\u9762<rt>\u3058</rt></ruby><ruby>\u76ee<rt>\u3081</rt></ruby>\u306a<ruby>\u9234<rt>\u3059\u305a</rt></ruby><ruby>\u6728<rt>\u304d</rt></ruby>\u3055\u3093\u306f\u3001\uff08\u3000\u3000\u3000\uff09\u3053\u3068\u306b\u304a<ruby>\u9152<rt>\u3055\u3051</rt></ruby>\u304c\u5927\u597d\u304d\u3089\u3057\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Suzuki-san yang selalu serius itu, secara tidak terduga ternyata sangat menyukai minuman beralkohol.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u306a <small>(mahir / pandai)</small></span>\n      <span class=\"opt\">2. <ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u5916<rt>\u304c\u3044</rt></ruby>\u306a <small>(tidak terduga)</small></span>\n      <span class=\"opt\">3. <ruby>\u5927<rt>\u305f\u3044</rt></ruby><ruby>\u5909<rt>\u3078\u3093</rt></ruby>\u306a <small>(berat / sulit)</small></span>\n      <span class=\"opt\">4. <ruby>\u76f8<rt>\u305d\u3046</rt></ruby><ruby>\u5f53<rt>\u3068\u3046</rt></ruby>\u306a <small>(cukup besar)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u3053\u3053\u306f<ruby>\u904a<rt>\u3086\u3046</rt></ruby><ruby>\u5712<rt>\u3048\u3093</rt></ruby><ruby>\u5730<rt>\u3061</rt></ruby>\u3084\u6c34\u65cf\u9928\u304c\u3042\u308b\u3001\u3068\u3066\u3082\uff08\u3000\u3000\u3000\uff09\u753a\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Ini adalah kota yang sangat ramai, memiliki taman hiburan dan akuarium.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u306b\u304e\u3084\u304b\u306a <small>(ramai / meriah)</small></span>\n      <span class=\"opt\">2. <ruby>\u5e73<rt>\u3078\u3044</rt></ruby><ruby>\u6c17<rt>\u304d</rt></ruby>\u306a <small>(tenang / tidak masalah)</small></span>\n      <span class=\"opt\">3. <ruby>\u6d3e<rt>\u306f</rt></ruby><ruby>\u624b<rt>\u3067</rt></ruby>\u306a <small>(mencolok)</small></span>\n      <span class=\"opt\">4. \u305f\u3044\u304f\u3064\u306a <small>(membosankan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u6570\u5b66\u306f\u597d\u304d\u3060\u304c\u3001\uff08\u3000\u3000\u3000\uff09\u8a08\u7b97\u304c\u5c11\u3057\u82e6\u624b\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Saya suka matematika, tetapi agak lemah dalam hitungan yang rumit.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u78ba<rt>\u304b\u304f</rt></ruby><ruby>\u5b9f<rt>\u3058\u3064</rt></ruby>\u306a <small>(pasti)</small></span>\n      <span class=\"opt\">2. <ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u5e38<rt>\u3058\u3087\u3046</rt></ruby>\u306a <small>(normal)</small></span>\n      <span class=\"opt\">3. <ruby>\u8907<rt>\u3075\u304f</rt></ruby><ruby>\u96d1<rt>\u3056\u3064</rt></ruby>\u306a <small>(rumit / kompleks)</small></span>\n      <span class=\"opt\">4. <ruby>\u5371<rt>\u304d</rt></ruby><ruby>\u967a<rt>\u3051\u3093</rt></ruby>\u306a <small>(berbahaya)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u30b3\u30f3\u30d3\u30cb\u306f24\u6642\u9593\u958b\u3044\u3066\u3044\u3066\u3001\u306a\u3093\u3067\u3082\u58f2\u3063\u3066\u3044\u308b\u306e\u3067\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Minimarket buka 24 jam dan menjual apa saja sehingga sangat praktis.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u71b1<rt>\u306d\u3063</rt></ruby><ruby>\u5fc3<rt>\u3057\u3093</rt></ruby>\u3060 <small>(tekun / rajin)</small></span>\n      <span class=\"opt\">2. <ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u3060 <small>(praktis / nyaman)</small></span>\n      <span class=\"opt\">3. <ruby>\u4e0a<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u54c1<rt>\u3072\u3093</rt></ruby>\u3060 <small>(elegan / sopan)</small></span>\n      <span class=\"opt\">4. <ruby>\u65b0<rt>\u3057\u3093</rt></ruby><ruby>\u9bae<rt>\u305b\u3093</rt></ruby>\u3060 <small>(segar)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u4ed5\u4e8b\u306e\u5f8c\u306b\u6620\u753b\u3092\u307f\u306b\u884c\u3053\u3046\u3068\u601d\u3063\u3066\u3044\u305f\u304c\u3001\u6b8b\u696d\u306e\u305b\u3044\u3067\uff08\u3000\u3000\u3000\uff09\u3002</span></div>\n    <div class=\"q-id-trans\">Saya bermaksud pergi menonton film sepulang kerja, tetapi gara-gara lembur jadi tidak bisa (mustahil).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6b8b<rt>\u3056\u3093</rt></ruby><ruby>\u5ff5<rt>\u306d\u3093</rt></ruby>\u3060\u3063\u305f <small>(disayangkan)</small></span>\n      <span class=\"opt\">2. <ruby>\u8ff7<rt>\u3081\u3044</rt></ruby><ruby>\u60d1<rt>\u308f\u304f</rt></ruby>\u3060\u3063\u305f <small>(mengganggu)</small></span>\n      <span class=\"opt\">3. <ruby>\u4e0d<rt>\u3075</rt></ruby><ruby>\u5b89<rt>\u3042\u3093</rt></ruby>\u3060\u3063\u305f <small>(cemas)</small></span>\n      <span class=\"opt\">4. <ruby>\u7121<rt>\u3080</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby>\u3060\u3063\u305f <small>(tidak bisa / mustahil)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u5148\u751f\u306e\uff08\u3000\u3000\u3000\uff09\u8aac\u660e\u306e\u304a\u304b\u3052\u3067\u3001\u96e3\u3057\u3044\u554f\u984c\u3082\u89e3\u3051\u308b\u3088\u3046\u306b\u306a\u308a\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Berkat penjelasan guru yang terperinci (cermat), soal yang sulit pun menjadi bisa saya kerjakan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u91cd<rt>\u3058\u3085\u3046</rt></ruby><ruby>\u5927<rt>\u3060\u3044</rt></ruby>\u306a <small>(penting / serius)</small></span>\n      <span class=\"opt\">2. <ruby>\u53ef<rt>\u304b</rt></ruby><ruby>\u80fd<rt>\u306e\u3046</rt></ruby>\u306a <small>(mungkin)</small></span>\n      <span class=\"opt\">3. <ruby>\u4e01<rt>\u3066\u3044</rt></ruby><ruby>\u5be7<rt>\u306d\u3044</rt></ruby>\u306a <small>(terperinci / cermat / sopan)</small></span>\n      <span class=\"opt\">4. <ruby>\u9ad8<rt>\u3053\u3046</rt></ruby><ruby>\u4fa1<rt>\u304b</rt></ruby>\u306a <small>(mahal)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 4\u3000\u2461 1\u3000\u2462 2\u3000\u2463 2\u3000\u2464 1\u3000\u2465 3\u3000\u2466 2\u3000\u2467 4\u3000\u2468 3</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p92\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 10 (Kata Sifat-na &amp; Kata Keterangan \u00b7 Hal. 89)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u3053\u306e<ruby>\u4e8b<rt>\u3058</rt></ruby><ruby>\u4ef6<rt>\u3051\u3093</rt></ruby>\u306b\u3064\u3044\u3066\u3001\uff08\u3000\u3000\u3000\uff09\u60c5\u5831\u3092\u77e5\u308a\u305f\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Saya ingin mengetahui informasi yang pasti (akurat) mengenai kasus ini.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u76db<rt>\u3055\u304b</rt></ruby>\u3093\u306a <small>(giat / ramai)</small></span>\n      <span class=\"opt\">2. <ruby>\u6b63<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u76f4<rt>\u3058\u304d</rt></ruby>\u306a <small>(jujur)</small></span>\n      <span class=\"opt\">3. <ruby>\u78ba<rt>\u305f\u3057</rt></ruby>\u304b\u306a <small>(pasti / akurat)</small></span>\n      <span class=\"opt\">4. <ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u7d14<rt>\u3058\u3085\u3093</rt></ruby>\u306a <small>(sederhana)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u91ce\u83dc\u3092\u305f\u304f\u3055\u3093\u98df\u3079\u308b\u3053\u3068\u306f\u3001<ruby>\u5065<rt>\u3051\u3093</rt></ruby><ruby>\u5eb7<rt>\u3053\u3046</rt></ruby>\u306b\u3082\u30c0\u30a4\u30a8\u30c3\u30c8\u306b\u3082\uff08\u3000\u3000\u3000\uff09\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Banyak makan sayuran itu efektif baik untuk kesehatan maupun untuk diet.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5b9f<rt>\u3058\u3064</rt></ruby><ruby>\u7528<rt>\u3088\u3046</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(praktis / berguna)</small></span>\n      <span class=\"opt\">2. <ruby>\u52b9<rt>\u3053\u3046</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(efektif)</small></span>\n      <span class=\"opt\">3. <ruby>\u57fa<rt>\u304d</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(mendasar)</small></span>\n      <span class=\"opt\">4. <ruby>\u5168<rt>\u305c\u3093</rt></ruby><ruby>\u4f53<rt>\u305f\u3044</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(menyeluruh)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\"><ruby>\u6065<rt>\u306f</rt></ruby>\u305a\u304b\u3057\u304c\u3089\u305a\u3001\u3082\u3063\u3068\uff08\u3000\u3000\u3000\uff09\u306b\u610f\u898b\u3092\u51fa\u3057\u5408\u3044\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Jangan malu-malu, mari kita saling menyampaikan pendapat dengan lebih aktif (proaktif)!</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u57fa<rt>\u304d</rt></ruby><ruby>\u790e<rt>\u305d</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(bersifat dasar)</small></span>\n      <span class=\"opt\">2. <ruby>\u6d3b<rt>\u304b\u3064</rt></ruby><ruby>\u52d5<rt>\u3069\u3046</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(aktif bergerak)</small></span>\n      <span class=\"opt\">3. <ruby>\u7a4d<rt>\u305b\u3063</rt></ruby><ruby>\u6975<rt>\u304d\u3087\u304f</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(proaktif / antusias)</small></span>\n      <span class=\"opt\">4. <ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u822c<rt>\u3071\u3093</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(umum)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u65e5\u672c\u306e\u30bf\u30af\u30b7\u30fc\u306e\u30c9\u30a2\u306f\u3001\u81ea\u5206\u3067\u958b\u3051\u306a\u304f\u3066\u3082\uff08\u3000\u3000\u3000\uff09\u306b\u958b\u304d\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Pintu taksi di Jepang terbuka secara otomatis tanpa perlu dibuka sendiri.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6700<rt>\u3055\u3044</rt></ruby><ruby>\u7d42<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(pada akhirnya)</small></span>\n      <span class=\"opt\">2. <ruby>\u4eba<rt>\u3058\u3093</rt></ruby><ruby>\u5de5<rt>\u3053\u3046</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(buatan)</small></span>\n      <span class=\"opt\">3. <ruby>\u5177<rt>\u3050</rt></ruby><ruby>\u4f53<rt>\u305f\u3044</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(konkret)</small></span>\n      <span class=\"opt\">4. <ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u52d5<rt>\u3069\u3046</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(otomatis)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u308f\u305f\u3057\u306f\u5927\u5b66\u3067\u690d\u7269\u306b\u3064\u3044\u3066\u7814\u7a76\u3057\u305f\u306e\u3067\u3001\u8fb2\u696d\u306b\u3064\u3044\u3066\uff08\u3000\u3000\u3000\uff09\u306a\u77e5\u8b58\u304c\u3042\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Karena saya meneliti tentang tumbuhan di universitas, saya memiliki pengetahuan khusus (mendalam) mengenai pertanian.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u4ee3<rt>\u3060\u3044</rt></ruby><ruby>\u8868<rt>\u3072\u3087\u3046</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(representatif)</small></span>\n      <span class=\"opt\">2. <ruby>\u7d4c<rt>\u3051\u3044</rt></ruby><ruby>\u6e08<rt>\u3056\u3044</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(ekonomis)</small></span>\n      <span class=\"opt\">3. <ruby>\u6570<rt>\u3059\u3046</rt></ruby><ruby>\u5b66<rt>\u304c\u304f</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(matematis)</small></span>\n      <span class=\"opt\">4. <ruby>\u5c02<rt>\u305b\u3093</rt></ruby><ruby>\u9580<rt>\u3082\u3093</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby> <small>(khusus / spesialis)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u660e\u65e5\u3001\u307f\u3093\u306a\u306b\uff08\u3000\u3000\u3000\uff09\u304a\u77e5\u3089\u305b\u3092\u3059\u308b\u4e88\u5b9a\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Besok berencana menyampaikan pengumuman yang penting kepada semua orang.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u7acb<rt>\u308a\u3063</rt></ruby><ruby>\u6d3e<rt>\u3071</rt></ruby>\u306a <small>(megah / hebat)</small></span>\n      <span class=\"opt\">2. <ruby>\u91cd<rt>\u3058\u3085\u3046</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u306a <small>(penting)</small></span>\n      <span class=\"opt\">3. <ruby>\u5730<rt>\u3058</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby>\u306a <small>(sederhana / polos)</small></span>\n      <span class=\"opt\">4. <ruby>\u614e<rt>\u3057\u3093</rt></ruby><ruby>\u91cd<rt>\u3061\u3087\u3046</rt></ruby>\u306a <small>(hati-hati)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u9060\u3044\u5834\u6240\u306b\u4f4f\u3093\u3067\u3044\u308b\u604b\u4eba\u3068\u3001\u4e00\u5e74\u3076\u308a\u306b\uff08\u3000\u3000\u3000\uff09\u4f1a\u3048\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Akhirnya saya bisa bertemu dengan kekasih yang tinggal di tempat jauh setelah satu tahun tidak bertemu.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u306a\u304b\u306a\u304b <small>(susah / jarang)</small></span>\n      <span class=\"opt\">2. \u3044\u3064\u3067\u3082 <small>(kapan saja)</small></span>\n      <span class=\"opt\">3. \u3088\u3046\u3084\u304f <small>(akhirnya)</small></span>\n      <span class=\"opt\">4. \u306f\u3058\u3081\u3066 <small>(untuk pertama kalinya)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\uff08\u3000\u3000\u3000\uff09\u96e8\u304c<ruby>\u964d<rt>\u3075</rt></ruby>\u3063\u305f\u3089\u3001\u6d77\u3067\u306f\u306a\u304f\u30d7\u30fc\u30eb\u306b\u884c\u304d\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Seandainya hujan turun, mari kita pergi ke kolam renang saja, bukan ke laut.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u4eca<rt>\u3044\u307e</rt></ruby>\u306b\u3082 <small>(sebentar lagi / hampir)</small></span>\n      <span class=\"opt\">2. <ruby>\u78ba<rt>\u305f\u3057</rt></ruby>\u304b <small>(kalau tidak salah)</small></span>\n      <span class=\"opt\">3. \u3082\u3057 <small>(seandainya / jika)</small></span>\n      <span class=\"opt\">4. <ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\u306b <small>(sekaligus)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u4e8c\u6642\u307e\u3067\u306b\u3053\u306e\u4ed5\u4e8b\u304c\u7d42\u308f\u308b\u304b\u306f\u308f\u304b\u308a\u307e\u305b\u3093\u304c\u3001\uff08\u3000\u3000\u3000\uff09\u65e9\u304f\u7d42\u308f\u3089\u305b\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Saya tidak tahu apakah pekerjaan ini akan selesai sebelum jam dua, tetapi saya akan menyelesaikannya secepat mungkin (sebisa mungkin cepat).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u306a\u308b\u3079\u304f <small>(sebisa mungkin)</small></span>\n      <span class=\"opt\">2. <ruby>\u4e3b<rt>\u304a\u3082</rt></ruby>\u306b <small>(terutama)</small></span>\n      <span class=\"opt\">3. <ruby>\u6b21<rt>\u3057</rt></ruby><ruby>\u7b2c<rt>\u3060\u3044</rt></ruby>\u306b <small>(lama-kelamaan)</small></span>\n      <span class=\"opt\">4. \u3060\u3044\u305f\u3044 <small>(kurang lebih)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\u3000\u2461 2\u3000\u2462 3\u3000\u2463 4\u3000\u2464 4\u3000\u2465 2\u3000\u2466 3\u3000\u2467 3\u3000\u2468 1</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p93\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 11 (Kata Keterangan Umum \u00b7 Hal. 90)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u3060\u3081\u3060\u3068\u308f\u304b\u3063\u3066\u3044\u3066\u3082\u3001\uff08\u3000\u3000\u3000\uff09\u304a<ruby>\u83d3<rt>\u304b</rt></ruby><ruby>\u5b50<rt>\u3057</rt></ruby>\u3092\u98df\u3079<ruby>\u904e<rt>\u3059</rt></ruby>\u304e\u3066\u3057\u307e\u3044\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Walaupun tahu tidak boleh, tanpa sadar saya makan camilan terlalu banyak.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u307e\u305a <small>(pertama-tama)</small></span>\n      <span class=\"opt\">2. \u304d\u3061\u3093\u3068 <small>(dengan rapi)</small></span>\n      <span class=\"opt\">3. \u3064\u3044 <small>(tanpa sadar / kebablasan)</small></span>\n      <span class=\"opt\">4. \u3060\u3093\u3060\u3093 <small>(berangsur-angsur)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u305f\u304f\u3055\u3093\u52c9\u5f37\u3057\u305f\u304c\u3001\uff08\u3000\u3000\u3000\uff09\u8a66\u9a13\u306b\u5408\u683c\u3059\u308b\u3068\u306f<ruby>\u9650<rt>\u304b\u304e</rt></ruby>\u3089\u306a\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Walaupun sudah banyak belajar, belum tentu (tidak selalu) lulus ujian.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u4f8b<rt>\u305f\u3068</rt></ruby>\u3048\u3070 <small>(misalnya)</small></span>\n      <span class=\"opt\">2. <ruby>\u5fc5<rt>\u304b\u306a\u3089</rt></ruby>\u305a\u3057\u3082 <small>(belum tentu / tidak selalu)</small></span>\n      <span class=\"opt\">3. <ruby>\u591a<rt>\u305f</rt></ruby><ruby>\u5c11<rt>\u3057\u3087\u3046</rt></ruby> <small>(sedikit banyak)</small></span>\n      <span class=\"opt\">4. \u3044\u304f\u3089\u3067\u3082 <small>(sebanyak apa pun)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\"><ruby>\u652f<rt>\u3057</rt></ruby><ruby>\u6255<rt>\u306f\u3089</rt></ruby>\u3046<ruby>\u91d1<rt>\u304d\u3093</rt></ruby><ruby>\u984d<rt>\u304c\u304f</rt></ruby>\u3092\uff08\u3000\u3000\u3000\uff09\u51fa\u3059\u3053\u3068\u304c\u3067\u304d\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saya bisa mengeluarkan uang pas sesuai jumlah yang harus dibayar.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305d\u306e\u307e\u307e <small>(apa adanya)</small></span>\n      <span class=\"opt\">2. \u307e\u3063\u3059\u3050 <small>(lurus)</small></span>\n      <span class=\"opt\">3. \u305f\u3060 <small>(hanya / gratis)</small></span>\n      <span class=\"opt\">4. \u3061\u3087\u3046\u3069 <small>(pas / tepat)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><ruby>\u5272<rt>\u308f</rt></ruby>\u308c\u305f\u30b3\u30c3\u30d7\u306f\u3001\u5371\u306a\u3044\u306e\u3067\uff08\u3000\u3000\u3000\uff09<ruby>\u89e6<rt>\u3055\u308f</rt></ruby>\u3089\u306a\u3044\u3067\u304f\u3060\u3055\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Gelas yang pecah itu berbahaya, jadi jangan sekali-kali menyentuhnya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u5148<rt>\u3055\u304d</rt></ruby>\u306b <small>(terlebih dahulu)</small></span>\n      <span class=\"opt\">2. <ruby>\u7a81<rt>\u3068\u3064</rt></ruby><ruby>\u7136<rt>\u305c\u3093</rt></ruby> <small>(tiba-tiba)</small></span>\n      <span class=\"opt\">3. <ruby>\u7d76<rt>\u305c\u3063</rt></ruby><ruby>\u5bfe<rt>\u305f\u3044</rt></ruby> <small>(sama sekali / mutlak)</small></span>\n      <span class=\"opt\">4. <ruby>\u6700<rt>\u3082\u3063\u3068</rt></ruby>\u3082 <small>(paling)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u591a\u5206\u305d\u306e\u4f5c\u308a\u65b9\u3067\u5408\u3063\u3066\u3044\u307e\u3059\u304c\u3001\uff08\u3000\u3000\u3000\uff09\u78ba\u8a8d\u3057\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Sepertinya cara membuatnya sudah benar, tetapi mari kita periksa sekadar untuk memastikan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. <ruby>\u6b21<rt>\u3064\u304e</rt></ruby><ruby>\u3005<rt>\u3064\u304e</rt></ruby> <small>(berturut-turut)</small></span>\n      <span class=\"opt\">2. <ruby>\u7d50<rt>\u3051\u3063</rt></ruby><ruby>\u69cb<rt>\u3053\u3046</rt></ruby> <small>(lumayan / cukup)</small></span>\n      <span class=\"opt\">3. <ruby>\u76f8<rt>\u305d\u3046</rt></ruby><ruby>\u5f53<rt>\u3068\u3046</rt></ruby> <small>(cukup besar)</small></span>\n      <span class=\"opt\">4. <ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u5fdc<rt>\u304a\u3046</rt></ruby> <small>(sekadar jaga-jaga / sementara)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u305f\u304f\u3055\u3093\u898b\u305f\u3051\u3069\u3001\uff08\u3000\u3000\u3000\uff09\u6700\u521d\u306b\u884c\u3063\u305f\u304a\u5e97\u306e\u670d\u304c\u6b32\u3057\u3044\u306a\u3002</span></div>\n    <div class=\"q-id-trans\">Sudah melihat banyak, tetapi tetap saja saya ingin baju dari toko yang pertama kali saya kunjungi.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3084\u3063\u3068 <small>(akhirnya)</small></span>\n      <span class=\"opt\">2. \u3082\u3061\u308d\u3093 <small>(tentu saja)</small></span>\n      <span class=\"opt\">3. \u3084\u3063\u3071\u308a <small>(tetap saja / memang)</small></span>\n      <span class=\"opt\">4. \u305a\u3044\u3076\u3093 <small>(cukup banyak)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u5352\u696d\u3057\u3066\u304b\u3089\u4e00\u5ea6\u3082\u4f1a\u3063\u3066\u3044\u306a\u304b\u3063\u305f<ruby>\u4f50<rt>\u3055</rt></ruby><ruby>\u85e4<rt>\u3068\u3046</rt></ruby>\u3055\u3093\u3068\uff08\u3000\u3000\u3000\uff09\u99c5\u3067\u4f1a\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Di stasiun saya secara kebetulan bertemu Sato-san yang belum pernah saya temui sejak lulus.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304b\u306a\u308a <small>(lumayan / cukup)</small></span>\n      <span class=\"opt\">2. <ruby>\u5076<rt>\u3050\u3046</rt></ruby><ruby>\u7136<rt>\u305c\u3093</rt></ruby> <small>(secara kebetulan)</small></span>\n      <span class=\"opt\">3. \u305b\u3063\u304b\u304f <small>(mumpung / susah payah)</small></span>\n      <span class=\"opt\">4. <ruby>\u7d50<rt>\u3051\u3063</rt></ruby><ruby>\u5c40<rt>\u304d\u3087\u304f</rt></ruby> <small>(pada akhirnya)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\"><ruby>\u666e<rt>\u3075</rt></ruby><ruby>\u6bb5<rt>\u3060\u3093</rt></ruby>\u306f\u304a<ruby>\u9152<rt>\u3055\u3051</rt></ruby>\u3092\u98f2\u307e\u306a\u3044\u304c\u3001\uff08\u3000\u3000\u3000\uff09\u98f2\u3080\u3068\u304a\u3044\u3057\u304f\u611f\u3058\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Biasanya saya tidak minum minuman beralkohol, tetapi kalau sesekali minum terasa enak.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3059\u3050\u306b <small>(segera)</small></span>\n      <span class=\"opt\">2. \u3042\u307e\u308a <small>(tidak begitu)</small></span>\n      <span class=\"opt\">3. \u3082\u3063\u3068 <small>(lebih)</small></span>\n      <span class=\"opt\">4. \u305f\u307e\u306b <small>(sesekali)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u5927\u5b66\u751f\u306b\u306a\u3063\u3066\u304b\u3089\u3001\uff08\u3000\u3000\u3000\uff09\u5b9f\u5bb6\u306b\u5e30\u3063\u3066\u3044\u306a\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Sejak menjadi mahasiswa, sudah cukup lama saya tidak pulang ke rumah orang tua.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u307e\u308b\u3067 <small>(seolah-olah / sama sekali)</small></span>\n      <span class=\"opt\">2. <ruby>\u6642<rt>\u3068\u304d</rt></ruby><ruby>\u3005<rt>\u3069\u304d</rt></ruby> <small>(kadang-kadang)</small></span>\n      <span class=\"opt\">3. \u3057\u3070\u3089\u304f <small>(cukup lama / sementara waktu)</small></span>\n      <span class=\"opt\">4. \u305f\u3044\u3066\u3044 <small>(biasanya)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\u3000\u2461 2\u3000\u2462 4\u3000\u2463 3\u3000\u2464 4\u3000\u2465 3\u3000\u2466 2\u3000\u2467 4\u3000\u2468 3</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p94\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 12 (Kata Keterangan Onomatope \u00b7 Hal. 91)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\"><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u5f53<rt>\u3068\u3046</rt></ruby>\u306f\u3069\u3046\u601d\u3063\u3066\u3044\u308b\u306e\u304b\u3001\uff08\u3000\u3000\u3000\uff09\u8a00\u3063\u3066\u304f\u3060\u3055\u3044\u3002</span></div>\n    <div class=\"q-id-trans\">Sebenarnya apa yang Anda pikirkan, tolong katakan dengan jelas (terus terang).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u305d\u3063\u304f\u308a <small>(persis sekali)</small></span>\n      <span class=\"opt\">2. \u306f\u3063\u304d\u308a <small>(dengan jelas)</small></span>\n      <span class=\"opt\">3. \u3066\u3063\u304d\u308a <small>(mengira pasti)</small></span>\n      <span class=\"opt\">4. \u304d\u3063\u304b\u308a <small>(tepat)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\">\u4eca\u65e5\u306f\u6642\u9593\u304c\u306a\u3044\u304b\u3089\u3001\u307e\u305f\u4eca\u5ea6\uff08\u3000\u3000\u3000\uff09\u8a71\u3057\u307e\u3057\u3087\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Karena hari ini tidak ada waktu, lain kali saja kita mengobrol dengan santai.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3050\u3063\u3059\u308a <small>(tidur nyenyak)</small></span>\n      <span class=\"opt\">2. \u3055\u3063\u3068 <small>(dengan cepat / sekilas)</small></span>\n      <span class=\"opt\">3. \u305d\u3063\u3068 <small>(pelan-pelan / diam-diam)</small></span>\n      <span class=\"opt\">4. \u3086\u3063\u304f\u308a <small>(dengan santai)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\">\u307e\u3060\u672c\u3092\u8aad\u307f\u305f\u3044\u3051\u3069\u3001\u660e\u65e5\u3082\u65e9\u3044\u3057\uff08\u3000\u3000\u3000\uff09\u5bdd\u3088\u3046\u3002</span></div>\n    <div class=\"q-id-trans\">Masih ingin membaca buku, tetapi karena besok juga pagi-pagi, sudah waktunya tidur saja.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3053\u308d\u3053\u308d <small>(menggelinding)</small></span>\n      <span class=\"opt\">2. \u3054\u308d\u3054\u308d <small>(bersantai-santai)</small></span>\n      <span class=\"opt\">3. \u305d\u308d\u305d\u308d <small>(sudah waktunya)</small></span>\n      <span class=\"opt\">4. \u306e\u308d\u306e\u308d <small>(lambat-lambat)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\"><ruby>\u5742<rt>\u3055\u304b</rt></ruby><ruby>\u4e95<rt>\u3044</rt></ruby>\u3055\u3093\u306f\u30a2\u30e1\u30ea\u30ab\u306b\u7559\u5b66\u3057\u3066\u3044\u305f\u306e\u3067\u3001\u82f1\u8a9e\u304c\uff08\u3000\u3000\u3000\uff09\u8a71\u305b\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Karena Sakai-san pernah belajar ke luar negeri di Amerika, ia bisa berbicara bahasa Inggris dengan fasih.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3053\u3093\u3053\u3093 <small>(batuk / salju turun lebat)</small></span>\n      <span class=\"opt\">2. \u3046\u308d\u3046\u308d <small>(mondar-mandir)</small></span>\n      <span class=\"opt\">3. \u307a\u3089\u307a\u3089 <small>(fasih / lancar)</small></span>\n      <span class=\"opt\">4. \u3079\u3089\u3079\u3089 <small>(berbicara terus tanpa henti)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\uff08\u3000\u3000\u3000\uff09\u3057\u3066\u3001\u5927\u4e8b\u306a<ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby>\u3092\u5bb6\u306b\u5fd8\u308c\u3066\u304d\u3066\u3057\u307e\u3063\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena lengah (kelupaan), saya malah meninggalkan dokumen penting di rumah.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3059\u3063\u304b\u308a <small>(sepenuhnya)</small></span>\n      <span class=\"opt\">2. \u3073\u3063\u304f\u308a <small>(terkejut)</small></span>\n      <span class=\"opt\">3. \u304d\u3063\u3061\u308a <small>(rapi / tepat)</small></span>\n      <span class=\"opt\">4. \u3046\u3063\u304b\u308a <small>(lengah / kelupaan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u3053\u306e<ruby>\u76bf<rt>\u3055\u3089</rt></ruby>\u306f\u5927\u5207\u306a\u3082\u306e\u3060\u304b\u3089\u3001\u843d\u3068\u3055\u306a\u3044\u3088\u3046\u306b\uff08\u3000\u3000\u3000\uff09\u6301\u3063\u3066\u3044\u3066\u306d\u3002</span></div>\n    <div class=\"q-id-trans\">Piring ini barang penting, jadi pegang erat-erat (dengan kuat) supaya tidak jatuh ya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3059\u3063\u3068 <small>(dengan mulus / cepat)</small></span>\n      <span class=\"opt\">2. \u3074\u3063\u305f\u308a <small>(pas sekali)</small></span>\n      <span class=\"opt\">3. \u3057\u3063\u304b\u308a <small>(kuat / erat-erat)</small></span>\n      <span class=\"opt\">4. \u305d\u3063\u3068 <small>(pelan-pelan / hati-hati)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u6691\u3044\u4e2d\u4e00\u6642\u9593\u3082\u5c71\u3092\u6b69\u3044\u305f\u306e\u3067\u3001\u306e\u3069\u304c\uff08\u3000\u3000\u3000\uff09\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Karena berjalan di gunung selama satu jam di tengah cuaca panas, tenggorokan saya kering kerontang.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u304c\u3089\u304c\u3089 <small>(sepi / serak)</small></span>\n      <span class=\"opt\">2. \u3056\u3089\u3056\u3089 <small>(kasar)</small></span>\n      <span class=\"opt\">3. \u3055\u3089\u3055\u3089 <small>(halus / lancar)</small></span>\n      <span class=\"opt\">4. \u304b\u3089\u304b\u3089 <small>(kering kerontang)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\">\u671d\u304b\u3089\u4f55\u3082\u98df\u3079\u3066\u3044\u306a\u3044\u306e\u3067\u3001\u304a<ruby>\u8179<rt>\u306a\u304b</rt></ruby>\u304c\uff08\u3000\u3000\u3000\uff09\u3060\u3002</span></div>\n    <div class=\"q-id-trans\">Karena belum makan apa pun sejak pagi, perut saya sangat lapar (keroncongan).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3069\u304d\u3069\u304d <small>(berdebar-debar)</small></span>\n      <span class=\"opt\">2. \u307a\u308d\u307a\u308d <small>(menjilat-jilat)</small></span>\n      <span class=\"opt\">3. \u3044\u3089\u3044\u3089 <small>(kesal / jengkel)</small></span>\n      <span class=\"opt\">4. \u307a\u3053\u307a\u3053 <small>(lapar keroncongan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u5bb6\u306b\u7740\u3044\u305f\u3068\u305f\u3093\u3001\u4ed5\u4e8b\u306e<ruby>\u75b2<rt>\u3064\u304b</rt></ruby>\u308c\u304c\uff08\u3000\u3000\u3000\uff09\u51fa\u3066\u304d\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Begitu sampai di rumah, rasa lelah kerja langsung terasa sekaligus.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u3069\u3063\u3068 <small>(sekaligus datang mendadak)</small></span>\n      <span class=\"opt\">2. \u304e\u3063\u3057\u308a <small>(penuh sesak)</small></span>\n      <span class=\"opt\">3. \u3055\u3063\u3071\u308a <small>(segar / sama sekali tidak)</small></span>\n      <span class=\"opt\">4. \u3058\u3063\u3068 <small>(diam tak bergerak)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 4\u3000\u2462 3\u3000\u2463 3\u3000\u2464 4\u3000\u2465 3\u3000\u2466 4\u3000\u2467 4\u3000\u2468 1</div>\n</div>\n\n<div class=\"exercise-set\" id=\"mondai-3-p95\">\n  <h4 class=\"set-title\">Latihan \u554f\u984c3: Set 13 (Kata Serapan Katakana \u00b7 Hal. 92)</h4>\n  <div class=\"q-instruction\">\n    <div class=\"q-inst-jp\">\u554f\u984c3\u3000\uff08\u3000\u3000\u3000\uff09\u306b\u5165\u308c\u308b\u306e\u306b\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002</div>\n    <div class=\"q-inst-id\">Pilihlah kata yang paling tepat untuk mengisi bagian dalam kurung \uff08\u3000\u3000\u3000\uff09 dari pilihan 1, 2, 3, atau 4.</div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">1</span> <span class=\"q-text\">\u6765\u6708\u884c\u308f\u308c\u308b\u3001\u30de\u30e9\u30bd\u30f3\u5927\u4f1a\u306e\uff08\u3000\u3000\u3000\uff09\u3092\u8003\u3048\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Memikirkan rute (jalur) lomba maraton yang akan diadakan bulan depan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u30a8\u30cd\u30eb\u30ae\u30fc <small>(energi)</small></span>\n      <span class=\"opt\">2. \u30b1\u30fc\u30b9 <small>(kotak / kasus)</small></span>\n      <span class=\"opt\">3. \u30b3\u30fc\u30b9 <small>(rute / jalur)</small></span>\n      <span class=\"opt\">4. \u30b5\u30f3\u30d7\u30eb <small>(sampel / contoh)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">2</span> <span class=\"q-text\"><ruby>\u5c71<rt>\u3084\u307e</rt></ruby><ruby>\u4e0b<rt>\u3057\u305f</rt></ruby>\u3055\u3093\u306f\u3001\u6027\u683c\u304c\u660e\u308b\u304f\uff08\u3000\u3000\u3000\uff09\u3092\u53d6\u308b\u3053\u3068\u304c<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3067\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Yamashita-san berkepribadian ceria dan pandai berkomunikasi.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u30a2\u30a4\u30c7\u30a2 <small>(ide)</small></span>\n      <span class=\"opt\">2. \u30b3\u30df\u30e5\u30cb\u30b1\u30fc\u30b7\u30e7\u30f3 <small>(komunikasi)</small></span>\n      <span class=\"opt\">3. \u30de\u30ca\u30fc <small>(tata krama / etika)</small></span>\n      <span class=\"opt\">4. \u30e1\u30c3\u30bb\u30fc\u30b8 <small>(pesan)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">3</span> <span class=\"q-text\"><ruby>\u8208<rt>\u304d\u3087\u3046</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby>\u306e\u3042\u308b\u4f1a\u793e\u306e\u30db\u30fc\u30e0\u30da\u30fc\u30b8\u306b\uff08\u3000\u3000\u3000\uff09\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Mengakses situs web perusahaan yang diminati.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u30a4\u30f3\u30bf\u30d3\u30e5\u30fc <small>(wawancara)</small></span>\n      <span class=\"opt\">2. \u30a2\u30af\u30bb\u30b9 <small>(akses)</small></span>\n      <span class=\"opt\">3. \u30d5\u30a1\u30c3\u30af\u30b9 <small>(faks)</small></span>\n      <span class=\"opt\">4. \u30c1\u30a7\u30c3\u30af\u30a4\u30f3 <small>(check-in)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">4</span> <span class=\"q-text\">\u308a\u3093\u3054\u3092\u8cb7\u3044\u306b\u884c\u3063\u305f\u3089\u3001\u5e97\u54e1\u3055\u3093\u304c\uff08\u3000\u3000\u3000\uff09\u3067\u4e00\u3064\u591a\u304f\u5165\u308c\u3066\u304f\u308c\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Saat pergi membeli apel, pegawai toko menambahkan satu buah ekstra sebagai bonus gratis (servis).</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u30b5\u30fc\u30d3\u30b9 <small>(layanan / bonus gratis)</small></span>\n      <span class=\"opt\">2. \u30bb\u30f3\u30bf\u30fc <small>(pusat)</small></span>\n      <span class=\"opt\">3. \u30d9\u30e9\u30f3\u30c0 <small>(beranda / balkon)</small></span>\n      <span class=\"opt\">4. \u30d2\u30f3\u30c8 <small>(petunjuk)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">5</span> <span class=\"q-text\">\u4eca\u307e\u3067\u4e00\u5ea6\u3082\u3084\u3063\u305f\u3053\u3068\u304c\u306a\u304b\u3063\u305f\u30b5\u30c3\u30ab\u30fc\u306b\uff08\u3000\u3000\u3000\uff09\u3059\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Mencoba (menantang diri bermain) sepak bola yang belum pernah dimainkan sebelumnya.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u30c8\u30ec\u30fc\u30cb\u30f3\u30b0 <small>(latihan)</small></span>\n      <span class=\"opt\">2. \u30a2\u30c3\u30d7 <small>(naik / peningkatan)</small></span>\n      <span class=\"opt\">3. \u30c1\u30e3\u30ec\u30f3\u30b8 <small>(tantangan / mencoba)</small></span>\n      <span class=\"opt\">4. \u30c0\u30d3\u30f3\u30b0 <small>(menyalin / dubbing)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">6</span> <span class=\"q-text\">\u4f1a\u793e\u3067\u30d3\u30b8\u30cd\u30b9\u306e\uff08\u3000\u3000\u3000\uff09\u3092\u6559\u3048\u308b\u3002</span></div>\n    <div class=\"q-id-trans\">Mengajarkan tata krama (etika) bisnis di perusahaan.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u30de\u30ca\u30fc <small>(tata krama / etika)</small></span>\n      <span class=\"opt\">2. \u30b5\u30a4\u30ba <small>(ukuran)</small></span>\n      <span class=\"opt\">3. \u30ec\u30b7\u30d4 <small>(resep)</small></span>\n      <span class=\"opt\">4. \u30e1\u30cb\u30e5\u30fc <small>(menu)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">7</span> <span class=\"q-text\">\u6025\u306b\u7528\u4e8b\u304c\u3067\u304d\u3066\u3057\u307e\u3044\u3001\u4ed5\u65b9\u306a\u304f\u660e\u65e5\u306e\u4e88\u5b9a\u3092\uff08\u3000\u3000\u3000\uff09\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Karena tiba-tiba ada urusan, dengan terpaksa saya membatalkan jadwal besok.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u30a2\u30ca\u30a6\u30f3\u30b9 <small>(pengumuman)</small></span>\n      <span class=\"opt\">2. \u30ea\u30b5\u30a4\u30af\u30eb <small>(daur ulang)</small></span>\n      <span class=\"opt\">3. \u30ad\u30e3\u30f3\u30bb\u30eb <small>(pembatalan)</small></span>\n      <span class=\"opt\">4. \u30b9\u30c8\u30c3\u30d7 <small>(berhenti)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">8</span> <span class=\"q-text\"><ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby>\u3092\u8aad\u3093\u3060\u3089\u3001\u6700\u5f8c\u306b\uff08\u3000\u3000\u3000\uff09\u3092\u304a\u9858\u3044\u3057\u307e\u3059\u3002</span></div>\n    <div class=\"q-id-trans\">Setelah membaca dokumen, mohon tanda tangannya di bagian akhir.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u30ea\u30b9\u30c8 <small>(daftar)</small></span>\n      <span class=\"opt\">2. \u30b5\u30a4\u30f3 <small>(tanda tangan)</small></span>\n      <span class=\"opt\">3. \u30c7\u30b6\u30a4\u30f3 <small>(desain)</small></span>\n      <span class=\"opt\">4. \u30c6\u30ad\u30b9\u30c8 <small>(teks / buku pelajaran)</small></span>\n    </div>\n  </div>\n  <div class=\"question-block\">\n    <div class=\"q-jp\"><span class=\"q-num\">9</span> <span class=\"q-text\">\u4e8c\u304b\u6708\u524d\u306b\u8cb7\u3063\u305f\u30da\u30f3\u306e\uff08\u3000\u3000\u3000\uff09\u304c\u3082\u3046\u306a\u304f\u306a\u3063\u3066\u3057\u307e\u3044\u307e\u3057\u305f\u3002</span></div>\n    <div class=\"q-id-trans\">Tinta pulpen yang saya beli dua bulan lalu sudah habis.</div>\n    <div class=\"q-options\">\n      <span class=\"opt\">1. \u30bd\u30fc\u30b9 <small>(saus / sumber)</small></span>\n      <span class=\"opt\">2. \u30a8\u30f3\u30b8\u30f3 <small>(mesin)</small></span>\n      <span class=\"opt\">3. \u30a4\u30f3\u30af <small>(tinta)</small></span>\n      <span class=\"opt\">4. \u30da\u30f3\u30ad <small>(cat)</small></span>\n    </div>\n  </div>\n  <div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\u3000\u2461 2\u3000\u2462 2\u3000\u2463 1\u3000\u2464 3\u3000\u2465 1\u3000\u2466 3\u3000\u2467 2\u3000\u2468 3</div>\n</div>\n\n</div><!-- /#mondai-3 -->\n\n</section>\n";
